      if (out.borderWidth == null) out.borderWidth = 1;
      if (out.extraCssText == null) out.extraCssText = 'box-shadow:0 6px 20px rgba(16,24,40,.12);border-radius:8px;';
      if (!out.textStyle || out.textStyle.color == null) out.textStyle = Object.assign({}, out.textStyle || {}, { color: '#1d2433' });
