function themeCycle(){
  var cur = themePref();
  var next = cur === 'light' ? 'dark' : cur === 'dark' ? 'auto' : 'light';
  try { LSX.setItem(THEME_KEY, next); } catch(e){}
  applyTheme(next, true, true);
}
(function(){
  //  기기 설정을 따르는 중에 OS 가 바뀌면 같이 바뀝니다
  try {
    var mq = window.matchMedia && matchMedia('(prefers-color-scheme: dark)');
    if (mq && mq.addEventListener) mq.addEventListener('change', function(){ if (themePref() === 'auto') applyTheme('auto', true); });
  } catch(e){}
  //  단추 모양 맞추기 (화면은 <head> 에서 이미 정해졌습니다)
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function(){ applyTheme(themePref(), false); });
  else applyTheme(themePref(), false);
})();

var BARW = { pct: 60 };
function barW(){ return Math.max(10, Math.min(100, Number(BARW.pct) || 60)) + '%'; }

/*  ── 막대가 <여럿> 일 때 ────────────────────────────────────

    ⚠️ 실제로 터진 버그입니다. 막대 계열마다 barWidth 를 '60%' 로 줬는데,
       ECharts 에서 그 %는 <칸(카테고리) 전체> 기준입니다. 계열이 3개면
       60% × 3 = 180%, 4개면 240% 라 <한 칸을 넘쳐> 옆 칸을 침범합니다.
       화면에서는 이렇게 보였습니다 —
         · 막대 무리가 이름표에서 오른쪽으로 밀림
         · 뒤로 갈수록 밀림이 쌓임
         · 계열을 4개 얹으면 <마지막 막대가 잘림>

    올바른 방법: 계열이 여럿이면 barWidth 를 <주지 않습니다>. ECharts 가
    칸을 나눠 씁니다. 대신 —
      · barCategoryGap : 칸과 칸 사이 여백 (= 100 − 막대가 쓸 %)
      · barGap         : 한 무리 안에서 막대끼리의 간격
    둘은 <첫 막대 계열> 에만 주면 전체에 적용됩니다.

    ⚠️ barMaxWidth 도 여럿일 때는 안 줍니다. 상한에 걸리면 무리 전체 폭이
       줄어드는데 시작 위치는 그대로라 또 어긋납니다.                    */
function barPct(){ return Math.max(10, Math.min(100, Number(BARW.pct) || 60)); }
function barProps(nBar){
  var pct = barPct();
  if (!(nBar > 1)) return { barWidth: pct + '%', barMaxWidth: 64 };
  return { barCategoryGap: (100 - pct) + '%', barGap: '10%' };
}
/*  series 배열을 통째로 받아 막대 폭을 알맞게 붙여 줍니다.
    ⚠️ 같은 x축(xAxisIndex)·같은 stack 끼리만 칸을 나눠 씁니다. 거래량처럼
       별도 축에 있는 막대는 따로 셉니다 — 안 그러면 폭이 엉뚱해집니다.  */
function applyBarProps(series){
  if (!Array.isArray(series)) return series;
  /*  한 x축 안에서 <막대가 몇 자리를 차지하는지> 를 셉니다.
      ⚠️ 쌓기(stack)는 겹쳐 그리므로 이름이 같은 것끼리 ‘한 자리’ 입니다.
         쌓기 무리가 둘이면(예: 콜 묶음 + 풋 묶음) 자리는 2개입니다 —
         예전 코드는 이걸 각각 1로 세어 둘 다 60% 를 줬고, 합이 120% 라
         옆 칸을 침범했습니다.
      ⚠️ 거래량처럼 <다른 x축> 에 있는 막대는 따로 셉니다.               */
  var axes = {};
  series.forEach(function(sr){
    if (!sr || sr.type !== 'bar') return;
    var ax = String(sr.xAxisIndex || 0);
    var a = axes[ax] || (axes[ax] = { list: [], slots: {}, n: 0 });
    a.list.push(sr);
    var slot = sr.stack ? ('s:' + sr.stack) : ('u:' + a.n);
    if (!(slot in a.slots)) { a.slots[slot] = 1; a.n++; }
  });
  Object.keys(axes).forEach(function(ax){
    var a = axes[ax], props = barProps(a.n);
    a.list.forEach(function(sr, i){
      if (a.n > 1){
        //  여럿이면 폭을 <주지 않습니다> — ECharts 가 칸을 나눠 씁니다
        delete sr.barWidth; delete sr.barMaxWidth;
        //  ⚠️ 간격 설정은 ‘첫 계열에만’. 계열마다 다른 값이 들어 있으면
        //     어느 게 이길지 알 수 없어 화면이 그때그때 달라집니다.
        if (i === 0){ sr.barCategoryGap = props.barCategoryGap; sr.barGap = props.barGap; }
        else { delete sr.barCategoryGap; delete sr.barGap; }
      } else {
        sr.barWidth = props.barWidth; sr.barMaxWidth = props.barMaxWidth;
        delete sr.barCategoryGap; delete sr.barGap;
      }
    });
  });
  return series;
}

/*  ── 차트 그릇 잡기 ─────────────────────────────────────────

    ⚠️ 실제로 터진 버그입니다. 퀀트 「일간 수익률 분포」가 두 번째부터
       아예 안 그려졌습니다. 이유 —

         box.innerHTML = '... <div id="distBox"></div>';   ← 그릇을 새로 만듦
         if (!distCharts['distBox']) ...                    ← 이미 있다고 건너뜀
         distChart.setOption(...)                           ← <떨어져 나간> 옛 div 에 그림

       ECharts 는 ‘DOM 노드’ 에 붙습니다. innerHTML 로 그릇을 다시 그리면
       우리가 들고 있던 차트는 화면에서 사라진 옛 노드에 계속 그립니다.
       오류도 안 납니다 — 그냥 <아무것도 안 보입니다>.

    그래서 그릴 때마다 <지금 그 자리에 있는 노드> 에 붙은 것을 찾아 씁니다.
    떨어져 나간 옛 것은 여기서 정리합니다 (안 하면 메모리에 쌓입니다).     */
function chartOn(box, old){
  if (typeof echarts === 'undefined') return null;
  if (typeof box === 'string') box = $(box);
  if (!box || !box.isConnected) return null;
  var cur = echarts.getInstanceByDom(box);
  //  들고 있던 게 화면에서 떨어져 나갔으면 버립니다
  if (old && old !== cur){
    try { var d = old.getDom && old.getDom(); if (!d || !d.isConnected) old.dispose(); } catch(e){}
  }
  if (!cur){
    cur = echarts.init(box);
    if (typeof chartRO !== 'undefined' && chartRO && !box.__roOn){
      box.__roOn = 1; chartRO.observe(box);
    }
  }
  return cur;
}

