if (!window.SAFE_CONFIG) {
  configError = 'config.js 파일을 찾을 수 없습니다. index.html 과 같은 폴더에 있어야 합니다.';
} else if (!/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(SUPABASE_URL)) {
  configError = 'config.js 의 SUPABASE_URL 이 올바르지 않습니다.';
} else if (/^sb_secret_/.test(SUPABASE_KEY)) {
  configError = '⛔ config.js 에 secret key 가 들어 있습니다. Publishable key 로 바꾸세요.';
} else if (!SUPABASE_KEY || /여기에|YOUR/i.test(SUPABASE_KEY)) {
  configError = 'config.js 의 SUPABASE_ANON_KEY 를 아직 입력하지 않았습니다.';
} else {
  sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);
}

function $(id){ return document.getElementById(id); }
//  (16차 학회장: ‘\u00ab \u00bb 기호 사용 안 했으면 · 프로하지 않아 보임’) — 화면에 넣는 모든 글(서버 · DB · AI 답 포함)에서 \u00ab \u00bb → ‘ ’
var ESC_GQ = /[\u00ab\u00bb]/;
function esc(s){ s = String(s==null?'':s); if (ESC_GQ.test(s)) s = s.replace(/\u00ab/g, '\u2018').replace(/\u00bb/g, '\u2019');
  return s.replace(/&/g,'&amp;').replace(/</g,'&lt;')
  .replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;'); }
function show(i){ $(i).classList.remove('hidden'); }
function hide(i){ $(i).classList.add('hidden'); }
function isOfficer(){ return me && me.role === 'officer'; }
function num(n, d){ return Number(n||0).toLocaleString('ko-KR',{minimumFractionDigits:d||0,maximumFractionDigits:d||0}); }
function pct(n){ return (n>=0?'+':'') + Number(n||0).toFixed(2) + '%'; }
/*  ⚠️ toISOString() 은 <UTC> 입니다. 한국은 UTC+9 라, 새벽 0시~오전 9시
    사이에는 ‘오늘’ 이 하루 전으로 나옵니다.

    증시캘린더는 한국시간(kst_date)으로 만들어져 있어서, 그 아홉 시간
    동안 달력이 어제를 ‘오늘’ 로 칠하고, 「다가오는 주요 발표」에 이미
    숫자가 다 나온 어젯밤 지표가 ‘곧 나올 것’ 으로 올라왔습니다.
    같은 화면의 학회 일정 D-day(현지시각)와도 하루가 어긋났습니다.    */
function today(){
  var d = new Date(Date.now() + 9 * 3600 * 1000);
  return d.toISOString().slice(0, 10);
}
function warn(id, html, cls){
  var b = $(id); if (!b) return;
  b.innerHTML = html ? '<div class="note '+(cls||'err')+'">'+html+'</div>' : '';
}

