      var r = f.apply(this, [v].concat(Array.prototype.slice.call(arguments, 1)));
      if (v != null && typeof curTab !== 'undefined' && curTab === G.p && innerItems(G).some(function(it){ return it[0] === v; })){ tvLog(G.p, v); if (typeof preRecStart === 'function') preRecStart(G.p); }   //  (14차) 수요 확인 — 세부 칸 · (15차) 미리 받기 기록
