/*  ── 모델 글 → 화면 (안전하게) ──
    이스케이프를 <먼저> 하고, 그 위에 우리가 정한 몇 가지 모양만 입힙니다.
    링크 · 이미지 · HTML 은 글자 그대로 보입니다.                              */
function aicMd(txt){
  var lines = String(txt || '').replace(/\r/g, '').replace(/\u00ab/g, '\u2018').replace(/\u00bb/g, '\u2019').split('\n');
  var out = [], items = null, base = 0, blank = false;
  var inline = function(s){
    return esc(s).replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>').replace(/`([^`]+)`/g, '<code>$1</code>');
  };
  /*  (10/6 점검) 목록을 진짜로 겹쳐 그립니다 — 예전엔 하위 불릿이 같은 <ol> 의 번호를 먹어 ‘1 · 4 · 7’ 이 됐고,
      처음부터 들여쓴 목록은 둘째 줄부터 하위로 보였습니다. 들여쓰기는 ‘첫 줄 대비’ 로 재고(2칸 = 한 단계 · 세 단계까지),
      빈 줄 하나로는 목록이 끊기지 않습니다.                                                           */
  var renderList = function(its){
    var h = '', st = [];
    its.forEach(function(it){
      while (st.length && st[st.length - 1].lvl > it.lvl) h += '</li></' + st.pop().tag + '>';
      var top = st[st.length - 1];
      if (!top || top.lvl < it.lvl){ h += '<' + it.tag + (it.lvl ? ' class="sub"' : '') + '>'; st.push({ tag: it.tag, lvl: it.lvl }); }
      else if (top.tag !== it.tag){ h += '</li></' + st.pop().tag + '><' + it.tag + (it.lvl ? ' class="sub"' : '') + '>'; st.push({ tag: it.tag, lvl: it.lvl }); }
      else h += '</li>';
      h += '<li>' + it.html;
    });
    while (st.length) h += '</li></' + st.pop().tag + '>';
    return h;
  };
  var flush = function(){ if (items){ out.push(renderList(items)); items = null; } blank = false; };
  lines.forEach(function(raw){
    var l = raw.replace(/\s+$/, '');
    var m;
    if (!l.trim()){ if (items) blank = true; return; }
    //  번호 목록은 번호를 살리고(1. 2. → ol), ‘2026. 10월’ 같은 연도는 목록으로 안 봅니다 (두 자리까지만)
    var ord = /^(\s*)\d{1,2}[.)]\s+(.*)$/.exec(l), bul = /^(\s*)[-*•·]\s+(.*)$/.exec(l);
    if (ord || bul){
      var mm = ord || bul, ind = mm[1].replace(/\t/g, '    ').length;
      if (!items){ items = []; base = ind; }
      var lvl = ind <= base ? 0 : Math.max(1, Math.min(2, Math.round((ind - base) / 2)));
      items.push({ tag: ord ? 'ol' : 'ul', lvl: lvl, html: inline(mm[2]) });
      blank = false;
      return;
    }
    flush();
    if ((m = /^\s*#{1,4}\s+(.*)$/.exec(l))){ out.push('<div class="h">' + inline(m[1]) + '</div>'); return; }
    if (/^\s*\[[^\]]{1,30}\]\s*$/.test(l)){ out.push('<div class="h">' + inline(l.trim()) + '</div>'); return; }
    if ((m = /^\s*(\[(?!\d+\])[^\]]{1,20}\])\s+(.+)$/.exec(l))){ out.push('<p><span class="lead">' + inline(m[1]) + '</span>' + inline(m[2]) + '</p>'); return; }
    out.push('<p>' + inline(l) + '</p>');
  });
  flush();
  return out.join('');
}
