        if (aInf && aInf.wb && aInf.wb.length) out.push('[' + aNm + ' 구조 지표 · 세계은행 (세계 순위)] ' + aInf.wb.map(function(x){ return (MK_WB_NM[x.k] || [x.k])[0] + ' ' + mkMacFmt(mkMacOf(x.k), x.v) + ' (' + x.rk + '/' + x.n + '위 · ' + x.y + ')'; }).join(' · '));
        if (aInf && aInf.kr100 && aInf.kr100.rows) out.push('[한국은행 100대 통계지표] ' + aInf.kr100.rows.slice(0, 40).map(function(r){ return r.n + ' ' + r.v + r.u + ' (' + r.t + ')'; }).join(' · '));
