        if (aBr.brief) out.push('[' + aNm + ' 시황 (AI 요약 · ' + aBr.day + ')] ' + aBr.brief.market.join(' / ') + (aBr.brief.picks && aBr.brief.picks.length ? ' · 유망 산업: ' + aBr.brief.picks.map(function(p){ return p.name + '(' + p.why + ')'; }).join(', ') : ''));
        if (typeof mkUsTrScreenLine === 'function'){ var aUt = mkUsTrScreenLine(MK.cc); if (aUt) out.push(aUt); }
        if (aBr.pplx && aBr.pplx.sectors && aBr.pplx.sectors.length) out.push('[' + aNm + ' 업종 (웹 검색 참고값)] ' + aBr.pplx.sectors.map(function(x){ return x.n + ' 1주 ' + mkPct(x.w1) + ' · 1개월 ' + mkPct(x.m1); }).join(' · '));
