        var aLive = []; var aIdx = typeof mkIdxOf === 'function' ? mkIdxOf(MK.cc) : null, aPf = typeof mkPerpOf === 'function' ? mkPerpOf(MK.cc) : null, aSc = MK.snap && MK.snap.ctry && MK.snap.ctry[MK.cc];
