var AIC_CITE_HOST = /^https:\/\/(fred\.stlouisfed\.org|data\.worldbank\.org|ecos\.bok\.or\.kr|data\.bls\.gov|www\.bls\.gov|apps\.bea\.gov|www\.bea\.gov)\//;
