      if (a.tab === 'flow' && a.flow) flowShow(a.flow);
      if (a.tab === 'stocks' && typeof stkMktSet === 'function'){ if (a.smkt && a.smkt !== STK.mkt) stkMktSet(a.smkt); if (a.preset) stkPreset(a.preset); }
