      boxes.forEach(function(b){ if (!(rr[1] <= b[0] || b[1] <= rr[0] || rr[3] <= b[2] || b[3] <= rr[2])) c += 1000; });
      //  점선이 앞 핀의 글을 가로지르지 않게
