      xAxis: { type: 'category', data: cats, axisLabel: { fontSize: 10.5 } }, yAxis: { type: 'value', scale: true, axisLabel: { fontSize: 10, formatter: '{value}%' }, splitLine: { lineStyle: { opacity: 0.4 } } },
