    if (MK.lay === 'mac' && MK.tabs.indexOf('m:' + MK.mac) < 0) MK.lay = 'mkt';
    if (MK.lay === 'port' && MK.tabs.indexOf('p:all') < 0) MK.lay = 'mkt';
