    if (Array.isArray(p.pp)) MK.pops = p.pp.filter(function(q){ return q && MK.tabs.indexOf(q.id) >= 0 && isFinite(q.x) && isFinite(q.y) && isFinite(q.w) && isFinite(q.h); })
      .filter(function(q, i, a){ return a.map(function(z){ return z.id; }).indexOf(q.id) === i; }).slice(-MK_VIS_MAX)
