  if (t.indexOf('r:') === 0) return MK_RES.some(function(r){ return r.k === k; }) ? { t: 'r', k: k } : null;
  if (t.indexOf('v:') === 0) return MK_VC.some(function(v){ return v.k === k; }) ? { t: 'v', k: k } : null;
  if (t.indexOf('m:') === 0) return MK_MAC.some(function(m){ return m[0] === k; }) ? { t: 'm', k: k } : null;
