      + '<div class="mk-res-what">' + esc(LM.what) + (LM.rows.length ? '<span class="st-hint"> · ' + esc(LM.yr + ' · ' + LM.basis) + '</span>' : '') + '</div>'
      + (LM.rows.length ? mkMacBodyHtml(LM, dark, null, false) : '<div class="mk-wait">' + esc(LM.err ? mkErrTxt(LM.err) : T('로딩 중…', 'Loading…')) + '</div>')
