    + (px ? '<div class="mk-res-px"><span class="n">' + esc(String(px.n).replace(/\s*\(24시간\)/, '') + (px.src === 'bn' || px.pfw ? ' 24h' : '')) + '</span> <b data-lv="pp:' + esc(px.s) + '" data-tw>' + esc(mkPx(px.p, px.s)) + '</b> <b class="' + (px.c > 0 ? 'up' : px.c < 0 ? 'down' : '') + '">' + esc(mkChg(px.c)) + '</b>'
            + (MK_PX_PROXY[px.s] ? ' <i class="mk-pxp" title="' + esc(MK_PX_PROXY[px.s]) + '">' + esc(T('ETF 대신', 'ETF proxy')) + '</i>' : '') + '</div>' : '')
    + (V ? mkVflowHtml(V, q.vs || V.st[0][0], function(S){ return 'data-pst="' + esc(S[0]) + '"'; }) : '')
