function algoAdd(key){ strat[key] = Array.isArray(strat[key]) ? strat[key] : []; if (strat[key].length >= 8){ warnStrat('신호는 8개까지 넣을 수 있습니다.'); return; } strat[key].push(JSON.parse(JSON.stringify(ALGO_DEF.cp))); stratChanged(); algoRender(); }
function algoDel(key, i){ (strat[key] || []).splice(i, 1); stratChanged(); algoRender(); }
