/* ══════════ (18차) 세이피 텔레그램 — 알림 링크 (#go=…) · 홈 카드 ══════════
   학회장: ‘특정 이상 · 움직임 · 뉴스 · 이벤트가 있으면 텔레그램으로 알림을 보내고 해당 정보가 있는 링크로 이동 가능하게’
   · 텔레그램 알림 · 보고서 요약의 ‘터미널에서 보기’ = 터미널주소/#go=종류&열쇠=값 (서버 safey-telegram 의 termGo)
       port&cp=6 물류 해협 · heat&mkt=us 시장 히트맵 · pair&a=US:XOM&b=US:CVX 페어 · yc&cc=US 일드커브 트레이딩 · cal 경제지표 캘린더 · news 뉴스
       algo 자동매매 › 시장 신호 · trade 팀 대회 · report&id=44 AI 리포트 · aimake&m=US&c=NVDA&n=NVIDIA 리포트 바로 만들기 · calc 미분 모델
   · 로그인 전에 들어오면 기억했다가 로그인 뒤에 (같은 창 · 10분 안) · 주소의 #go=… 는 바로 지움 (새로고침해도 같은 일을 또 하지 않게)
   · 값은 전부 정해진 모양만 받음 (모르는 종류 · 이상한 값은 버림) · 공개 범위 밖 탭이면 홈에 머무름  */
var GO18 = { pend: null, busy: false };
var GO_TAB = { live: 'market', tab: null, port: 'market', heat: 'heat', pair: 'quant', yc: 'qmodel', calc: 'qmodel', cal: 'home', news: null, algo: 'trading', trade: 'trading', report: 'ai', aimake: 'ai', home: 'home' };
var GO_NM = { live: '마켓 맵 › 실시간 전광판', tab: '터미널', port: '마켓 맵 › 물류', heat: '모의투자 › 팀 대회 › 시장 히트맵', pair: '퀀트 › 페어 트레이딩', yc: '퀀트 › 일드커브 트레이딩', calc: '퀀트 › 미분 모델', cal: '홈 › 경제지표 캘린더',
  news: '뉴스', algo: '팀 대회 › 자동매매 › 시장 신호', trade: '모의투자 › 팀 대회', report: 'AI 분석 › 리포트', aimake: 'AI 분석 › 새 리포트', home: '홈' };
var GO_SS = 'safe_go_v1';
function goParse(h){
  var m = String(h || '').match(/^#?go=([a-z]{2,7})((?:&[a-z]{1,4}=[^&#]{0,400})*)$/);
  if (!m || !Object.prototype.hasOwnProperty.call(GO_TAB, m[1])) return null;
  var o = { t: m[1] };
  m[2].split('&').forEach(function(kv){
    if (!kv) return; var i = kv.indexOf('='), v = kv.slice(i + 1);
    try { v = decodeURIComponent(v.replace(/\+/g, ' ')); } catch(e){ v = ''; }
    o[kv.slice(0, i)] = v.replace(/[<>"'`]/g, '').slice(0, 60);
  });
  return o;
}
function goSave(o){ try { sessionStorage.setItem(GO_SS, JSON.stringify({ o: o, at: Date.now() })); } catch(e){} }
function goClearHash(){ try { history.replaceState(null, '', location.pathname + location.search); } catch(e){} }
(function(){
  var o = goParse(location.hash);
  if (o){ GO18.pend = o; goSave(o); goClearHash(); return; }
  try { var j = JSON.parse(sessionStorage.getItem(GO_SS) || 'null'); if (j && j.o && Date.now() - Number(j.at) < 600000) GO18.pend = j.o; } catch(e){}
})();
window.addEventListener('hashchange', function(){
  var o = goParse(location.hash); if (!o) return;
  goClearHash();
  if (typeof me !== 'undefined' && me) goRun(o); else { GO18.pend = o; goSave(o); }
});
function goWait(fn, ms){
  var t0 = Date.now();
  return new Promise(function(res){ (function k(){ var ok = false; try { ok = !!fn(); } catch(e){} if (ok || Date.now() - t0 > ms) return res(ok); setTimeout(k, 120); })(); });
}
//  로그인 뒤 (enterApp 끝) — 탭 공개 범위를 받은 다음에
async function goBoot(){
  var o = GO18.pend; GO18.pend = null;
  try { sessionStorage.removeItem(GO_SS); } catch(e){}
  if (!o) return;
  await goWait(function(){ return CLUB.visOk; }, 3000);
  await goRun(o);
}
function goSay(o, extra){ toast('<b>텔레그램 링크</b> · ' + esc(GO_NM[o.t] || '') + (extra ? ' · ' + esc(extra) : ''), 3200); }
async function goRun(o){
  if (!o || GO18.busy) return;
  var tab = GO_TAB[o.t];
  if (tab && typeof tabVisOk === 'function' && !tabVisOk(tab)){ toast(esc((GO_NM[o.t] || '그') + ' 화면은 지금 열 수 없습니다.'), 4200); return; }
  GO18.busy = true;
  try {
    if (o.t === 'home') showTab('home');
    else if (o.t === 'port') await goPort(o);
    else if (o.t === 'heat'){ var hm = /^(us|kr|asset)$/.test(String(o.mkt || '').toLowerCase()) ? String(o.mkt).toLowerCase() : 'us'; showTab('heat'); if (typeof hmSetMkt === 'function' && (typeof HM === 'undefined' || HM.mkt !== hm)) hmSetMkt(hm); goSay(o, hm === 'kr' ? '한국' : hm === 'asset' ? '자산 전체' : 'S&P 500'); }
    else if (o.t === 'pair') goPair(o);
    else if (o.t === 'yc' || o.t === 'calc') goQm(o);
    else if (o.t === 'cal'){ showTab('home'); setTimeout(function(){ var c = document.querySelector('#pane-home .cal-card'); if (c && c.scrollIntoView) c.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 220); goSay(o); }
    else if (o.t === 'news'){ if (typeof nfDock === 'function') nfDock(true); goSay(o); }
    else if (o.t === 'trade' || o.t === 'algo') await goTrade(o);
    else if (o.t === 'report') await goReport(o);
    else if (o.t === 'aimake') await goAiMake(o);
  } catch(e){
    console.warn('텔레그램 링크', o, e);
    toast('링크의 화면을 열지 못했습니다 · ' + esc(String(e && e.message || e).slice(0, 120)), 4200);
  } finally { GO18.busy = false; }
}
//  물류 › 해협 (호르무즈 = 6) — 해협 자료가 들어온 다음에 고름 (먼저 고르면 빈 칸)
async function goPort(o){
  var cp = Number(o.cp), ok = Number.isInteger(cp) && cp >= 1 && cp <= 28;
  showTab('market');
  if (typeof mkSetView === 'function' && typeof MK !== 'undefined' && MK.view !== 'world') mkSetView('world');
  if (typeof mkPortSet === 'function') mkPortSet();
  if (!ok){ goSay(o); return; }
  await goWait(function(){ return MK.ports && MK.ports.d && (MK.ports.d.cps || []).length; }, 8000);
  var row = MK.ports && MK.ports.d ? (MK.ports.d.cps || []).filter(function(c){ return Number(c.id) === cp; })[0] : null;
  if (MK.portSel !== cp && typeof mkPortPick === 'function') mkPortPick(cp);
  goSay(o, row ? row.n : '');
}
function goPair(o){
  var a = typeof qprKey === 'function' ? qprKey(o.a) : null, b = typeof qprKey === 'function' ? qprKey(o.b) : null;
  if (!a || !b || a === b){ showTab('quant'); return; }
  QPR.a = a; QPR.b = b; QPR.data = null;
  var seg = $('qlSeg'), built = !!(seg && seg.children.length);
  //  처음 여는 퀀트 랩이면 initQuant 가 마지막 칸을 엶 → 페어로 바꿈 (이미 열려 있었으면 새 두 종목으로 다시 그림)
  showTab('quant');
  if (built || QL.tab !== 'pair') qlSet('pair');
  goSay(o, a.replace(/^US:/, '') + ' · ' + b.replace(/^US:/, ''));
}
function goQm(o){
  var k = o.t === 'yc' ? 'yc' : 'calc';
  if (k === 'yc'){ var cc = String(o.cc || 'US').toUpperCase(); if (typeof QYC_REG !== 'undefined' && QYC_REG[cc]){ QM.yc = cc; QM.ycPick = 1; } }
  var b = $('qmBodyWrap'), done = !!(b && b.__done);
  if (!done) QM.tab = k;
  showTab('qmodel');
  //  이미 열린 모델 화면이면: 다른 칸 → 그 칸으로 · 같은 일드커브 칸 → showTab 이 새 나라로 다시 계산 (단추 표시만 맞춤)
  if (done && QM.tab !== k) qmSet(k); else if (done && k === 'yc' && typeof qoSeg === 'function') qoSeg('qycCc', QM.yc);
  goSay(o, k === 'yc' ? (QYC_REG[QM.yc] || [''])[0] : '');
}
//  팀 대회 — 내 팀 방 (자동매매 › 시장 신호까지) · 소속 팀이 없으면 순위표
async function goTrade(o){
  showTab('trading');
  await goWait(function(){ return typeof mtCt !== 'undefined' && mtCt && mtBoard && mtBoard.length; }, 6000);
  if (!mtMyTeam){ toast('소속 팀이 없어 순위표를 열었습니다.', 3600); return; }
  await mtEnter(mtMyTeam);
  if (o.t === 'algo'){
    tradeTab('auto');
    await goWait(function(){ return typeof strat !== 'undefined' && strat; }, 5000);
    setTimeout(function(){ var el = $('algoSec'); if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 260);
  }
  goSay(o);
}
async function goReport(o){
  var id = Number(o.id);
  if (!Number.isInteger(id) || id <= 0){ showTab('ai'); return; }
  showTab('ai'); aiShow('lib');
  await aiOpen(id);
}
//  보고서 바로 만들기 — 텔레그램 ‘/report 회사’ 에서 보관함에 없을 때 · 이미 있으면 그걸 열고 요약을 텔레그램으로
//   · 누른 사람의 로그인 · 예산 · 한도 그대로 (서버 ai-report 가 막음) · 같은 링크를 15분 안에 또 누르면 만들기는 다시 안 함
async function goAiMake(o){
  var m = String(o.m || '').toUpperCase(), c = String(o.c || '').toUpperCase();
  showTab('ai'); aiShow('new');
  if (!/^(US|KR)$/.test(m) || !/^[A-Z0-9.\-]{1,12}$/.test(c)) return;
  if (aiBusy){ toast('다른 리포트를 만드는 중입니다. 끝난 뒤에 다시 눌러 주세요.', 4200); return; }
  var r = await sb.rpc('company_search', { q: c });
  var hit = (r && !r.error && r.data || []).filter(function(x){ return String(x.market) === m && String(x.code).toUpperCase() === c; })[0];
  if (!hit){ $('aiQ').value = o.n || c; warn('aiWarn', '회사를 목록에서 찾지 못했습니다. 이름으로 찾아 고른 뒤 리포트 만들기를 눌러 주세요.', 'info'); if (typeof aiSearch === 'function') aiSearch(); return; }
  aiPick = hit; $('aiQ').value = hit.name; $('aiHits').innerHTML = ''; warn('aiWarn', ''); aiSetPicked();
  await aiCheckDup();
  if (aiDup && aiDup.found){
    await aiOpen(aiDup.id);
    goTgDone(aiDup.id);
    goSay(o, hit.name + ' · 보관함 리포트');
    return;
  }
  var key = m + ':' + c, last = null;
  try { last = JSON.parse(sessionStorage.getItem('safe_go_aim_v1') || 'null'); } catch(e){}
  if (last && last.k === key && Date.now() - Number(last.at) < 900000){ goSay(o, hit.name + ' · 리포트 만들기를 눌러 주세요'); return; }
  try { sessionStorage.setItem('safe_go_aim_v1', JSON.stringify({ k: key, at: Date.now() })); } catch(e){}
  goSay(o, hit.name + ' · 만드는 중');
  await aiRun(false);
  if (aiRep && aiRep.id && String(aiRep.market) === String(hit.market) && String(aiRep.code) === String(hit.code)) goTgDone(aiRep.id);
}
//  완성된 리포트 요약을 이 사람 텔레그램으로 (연결 안 했으면 서버가 조용히 건너뜀 · 같은 리포트는 한 번만)
function goTgDone(id){ if (!(Number(id) > 0)) return; edgeCall('safey-telegram', { action: 'report_done', id: Number(id) }).then(function(r){ if (r && r.ok) toast('요약을 텔레그램으로 보냈습니다.', 3200); }, function(){}); }

/* ── 홈 › 세이피 텔레그램 (학회원 누구나) ──────────────────────────────
   연결 (6자리 코드 · 10분) · 받을 알림 고르기 (고르면 바로 저장) · 학회 채널 초대 링크 · 연결 끊기
   서버에 봇이 없으면 (TELEGRAM_BOT_TOKEN 없음) 학회원에게는 카드를 숨김 · 임원진에게만 안내   */
var HTG = { d: null, at: 0, busy: false, err: null, code: null, msg: '', msgK: '', saveT: 0, link: '' };
//  (19차) 설정 › 홈 › 홈 카드 보이기 — 열쇠 hm_tg (전체 공개 · 임원진만 · 숨김 · 서버 tab_vis) · 안 보이는 사람은 서버에 묻지도 않음
function htgOn(){ return typeof tabVisOk !== 'function' || tabVisOk('hm_tg'); }
function htgVis(){
  var c = $('homeTgCard'); if (!c) return;
  if (!htgOn()){ c.classList.add('hidden'); return; }
  var v = typeof tabVis === 'function' ? tabVis('hm_tg') : 'all', tag = $('htgVisTag');
  if (tag){ tag.textContent = v === 'hidden' ? '숨김 · 학회원에게 안 보임' : v === 'officer' ? '임원진만' : ''; tag.classList.toggle('hidden', v !== 'hidden' && v !== 'officer'); }
  if (typeof curTab !== 'undefined' && curTab === 'home') htgInit();
}
function htgInit(){ if (!htgOn()){ var c0 = $('homeTgCard'); if (c0) c0.classList.add('hidden'); return; } if (Date.now() - HTG.at < 300000 && (HTG.d || HTG.err)){ htgRender(); return; } htgLoad(false); }
async function htgLoad(force){
  if (HTG.busy || !$('homeTgCard') || !htgOn()) return;
  HTG.busy = true; if (!HTG.d) htgRender();
  try { HTG.d = await edgeCall('safey-telegram', { action: 'me' }); HTG.err = null; }
  catch(e){ HTG.err = String(e && e.message || e); }
  HTG.at = Date.now(); HTG.busy = false;
  if (force) HTG.msg = '';
  htgRender();
}
function htgSay(m, k){ HTG.msg = m || ''; HTG.msgK = k || ''; var e = $('htgMsg'); if (e){ e.innerHTML = HTG.msg; e.className = 'tg-msg' + (HTG.msgK ? ' ' + HTG.msgK : ''); } }
var HTG_CMDS = [['/logi', '물류 브리핑 (해협 통과 선박)'], ['/heat', '시장 히트맵 (업종 등락)'], ['/signal', '자동매매 시장 신호'], ['/report 엔비디아', 'AI 리포트 요약'],
  ['엔비디아 50주 매수해줘', '모의투자 주문 (미리보기 → 확인)'], ['/ask 질문', '세이피에게 묻기'], ['/sub 전체', '알림 구독 (텔레그램에서)']];
function htgRender(){
  var card = $('homeTgCard'), box = $('htgBody'); if (!card || !box) return;
  if (!htgOn()){ card.classList.add('hidden'); return; }
  var off = typeof isOfficer === 'function' && isOfficer();
  if (!HTG.d){
    //  학회원: 서버가 아직 없거나 오류면 카드를 숨김 (고칠 수 있는 사람만 안내)
    card.classList.toggle('hidden', !!HTG.err && !off);
    box.innerHTML = HTG.err ? '<div class="note">세이피 텔레그램 서버에 묻지 못했습니다 · ' + esc(HTG.err) + '<br>설정 › AI › 세이피 텔레그램에서 상태를 보세요.</div>' : '<div class="empty">로딩 중…</div>';
    return;
  }
  var d = HTG.d;
  if (!d.on){ card.classList.toggle('hidden', !off); box.innerHTML = '<div class="note">텔레그램 봇이 아직 연결되지 않았습니다 (학회원에게는 이 카드가 안 보입니다) · 설정 › AI › 세이피 텔레그램</div>'; return; }
  card.classList.remove('hidden');
  var bot = String(d.bot || ''), h = '';
  var chanBtn = d.channel ? '<button type="button" class="btn-sm" onclick="htgInvite()">학회 채널 들어가기</button>' : '';
  if (!d.linked){
    h += '<p class="htg-lead">시장 알림 · AI 리포트 요약 · 물류 브리핑 · 모의투자 주문을 텔레그램에서 받습니다.</p>'
      + '<div class="htg-feats">'
      + '<div class="htg-f"><b>알림</b><span>호르무즈 봉쇄 · 해제, 페어 신호, 금리차 역전, 지표 쇼크, 속보, 우리 팀 체결 · 누르면 터미널의 그 화면으로</span></div>'
      + '<div class="htg-f"><b>리포트 요약</b><span><code>/report 엔비디아</code> · 보관함에 없으면 터미널에서 바로 만들기</span></div>'
      + '<div class="htg-f"><b>물류 · 시장</b><span><code>/logi</code> 해협 통과량 · <code>/heat</code> 업종 지도 · <code>/signal</code> 시장 신호</span></div>'
      + '<div class="htg-f"><b>모의투자 주문</b><span><code>엔비디아 50주 매수해줘</code> → 미리보기 → 확인 단추 (내 팀만 · 2분 안)</span></div>'
      + '</div>'
      + '<div class="tg-acts"><button type="button" class="btn-sm btn-solid" onclick="htgCode()">내 텔레그램 연결</button>' + chanBtn + '</div>';
    if (HTG.code && HTG.code.exp > Date.now()){
      var b2 = HTG.code.bot || bot;
      h += '<div class="tg-code"><b>' + esc(HTG.code.code) + '</b>'
        + (b2 ? '<a class="btn-sm btn-solid" href="https://t.me/' + encodeURIComponent(b2) + '?start=' + encodeURIComponent(HTG.code.code) + '" target="_blank" rel="noopener">텔레그램에서 열기</a>' : '')
        + '<span class="st-hint">또는 ' + (b2 ? '@' + esc(b2) + ' 에게 ' : '봇에게 ') + '<code>/link ' + esc(HTG.code.code) + '</code> · ' + Math.max(1, Math.ceil((HTG.code.exp - Date.now()) / 60000)) + '분 안에 · 연결한 뒤 새로고침</span></div>';
    }
  } else {
    var subs = d.subs || [], tops = (d.topics || []).filter(function(t){ return Array.isArray(t) && /^[a-z]{2,12}$/.test(String(t[0])); });
    h += '<div class="htg-st"><span class="live-dot"></span><b>연결됨</b>' + (d.tg_name ? '<span>' + esc(d.tg_name) + '</span>' : '') + '</div>'
      + '<div class="tg-sec">받을 알림 <span class="st-hint htg-sub">고르면 바로 저장 · 세이피와의 1:1 대화로 옵니다</span></div>'
      + '<div class="tg-opts htg-topics" id="htgTopics">' + tops.map(function(t){
          return '<label><input type="checkbox" value="' + esc(t[0]) + '"' + (subs.indexOf(t[0]) >= 0 ? ' checked' : '') + ' onchange="htgSubsLater()"> ' + esc(t[1]) + '</label>'; }).join('') + '</div>'
      + '<div class="tg-sec">텔레그램에서 쓰는 말</div>'
      + '<div class="htg-cmds">' + HTG_CMDS.map(function(c){ return '<div class="htg-c"><code>' + esc(c[0]) + '</code><span>' + esc(c[1]) + '</span></div>'; }).join('') + '</div>'
      + '<div class="tg-acts">' + (bot ? '<a class="btn-sm btn-solid" href="https://t.me/' + encodeURIComponent(bot) + '" target="_blank" rel="noopener">텔레그램 열기</a>' : '') + chanBtn
      + '<button type="button" class="btn-sm" onclick="htgUnlink()">연결 끊기</button></div>';
  }
  h += '<div class="tg-msg' + (HTG.msgK ? ' ' + HTG.msgK : '') + '" id="htgMsg">' + (HTG.msg || '') + '</div>';
  box.innerHTML = h;
}
async function htgCode(){
  htgSay('로딩 중…');
  try { var r = await edgeCall('safey-telegram', { action: 'link_code' }); HTG.code = { code: String(r.code), bot: r.bot || '', exp: Date.now() + (Number(r.expires_in) || 600) * 1000 };
    HTG.msg = '10분 안에 텔레그램에서 연결해 주세요. 연결한 뒤 새로고침을 누르면 받을 알림을 고를 수 있습니다.'; HTG.msgK = 'ok'; htgRender(); }
  catch(e){ htgSay(esc(String(e && e.message || e)), 'err'); }
}
function htgSubsLater(){ clearTimeout(HTG.saveT); htgSay('로딩 중…'); HTG.saveT = setTimeout(htgSubsSave, 600); }
async function htgSubsSave(){
  var box = $('htgTopics'); if (!box) return;
  var want = Array.prototype.filter.call(box.querySelectorAll('input[type=checkbox]'), function(x){ return x.checked; }).map(function(x){ return x.value; });
  try { var r = await edgeCall('safey-telegram', { action: 'subs_set', topics: want }); if (HTG.d) HTG.d.subs = r.subs || want;
    htgSay(want.length ? '저장했습니다 · ' + want.length + '가지 알림' : '저장했습니다 · 알림을 모두 껐습니다', 'ok'); }
  catch(e){ htgSay(esc(String(e && e.message || e)), 'err'); }
}
async function htgUnlink(){
  htgSay('로딩 중…');
  try { await edgeCall('safey-telegram', { action: 'unlink' }); HTG.code = null; HTG.msg = '연결을 끊었습니다. 알림도 더 이상 오지 않습니다.'; HTG.msgK = 'ok'; await htgLoad(false); }
  catch(e){ htgSay(esc(String(e && e.message || e)), 'err'); }
}
//  학회 채널 초대 링크 (한 사람 · 하루 · 누를 때마다 새로) — 받은 뒤 누르는 단추로 엶 (팝업 막힘 방지)
async function htgInvite(){
  htgSay('로딩 중…');
  try { var r = await edgeCall('safey-telegram', { action: 'invite', room: 'all' }), link = String(r && r.link || '');
    if (!/^https:\/\/t\.me\/[A-Za-z0-9_+\-\/]+$/.test(link)) throw new Error('초대 링크를 받지 못했습니다.');
    htgSay('초대 링크 (나만 · 오늘 하루) <a class="btn-sm btn-solid" href="' + esc(link) + '" target="_blank" rel="noopener">학회 채널 열기</a>', 'ok'); }
  catch(e){ htgSay(esc(String(e && e.message || e)), 'err'); }
}
//  (설정 › AI › 세이피 텔레그램 · 임원진) 학회 채널로 보낼 시장 알림 주제 — 고르면 바로 저장 (하나도 안 고르면 채널 알림 없음 · 개인 구독은 그대로)
var tgTopT = 0;
function tgTopicsSave(){
  clearTimeout(tgTopT);
  tgTopT = setTimeout(function(){
    var box = $('tgTopics'); if (!box) return;
    var want = Array.prototype.filter.call(box.querySelectorAll('input[type=checkbox]'), function(x){ return x.checked; }).map(function(x){ return x.value; });
    tgSet({ alert_topics: want });
  }, 500);
}

/*>>18차 heat*/
/*<<19차 home*/
/* ══════════ (19차) 설정 › 홈 — 터미널 로고 · 탭 아이콘 (프로필 사진) · 홈 소개 · 홈 카드 보이기 ══════════
   학회장: ‘상단에 세이프 소개를 설정에서 임원진이 수정 가능하게 · 세이프 홈페이지처럼 설정에서 세이프 터미널 프로필 사진 변경 가능하게 ·
           홈탭 아래 세이피 텔레그램 숨기기 할 수 있도록 설정에서’
   · 저장 = 홈페이지와 같은 about 표 (id 1) 의 터미널 전용 칸: term_icon_url · term_logo_url · term_intro (terminal-홈설정.sql)
   · 그림: logos 버킷 terminal/ 아래 · PNG · JPG · WebP · 512KB · 비우면 홈페이지 로고 · 탭 아이콘을 따라감 → 그것도 없으면 SF 마크
   · 홈 소개: 터미널에만 (term_intro) · 또는 ‘홈페이지 소개글도 같이’ (about 기본 칸 · 터미널에만 둔 글은 비움)
   · 쓰기는 임원진만 (about 정책 is_officer · 버킷 정책) · 홈 카드 보이기는 탭 공개와 같은 권한 (학회장 · 설립자 · 서버 tab_vis_set)  */
var TB = { d: null, at: 0, err: null, msg: {}, busy: {}, prev: {}, imsg: '', imsgK: '', hmsg: '', hmsgK: '' };
var TB_LS = 'safe_term_brand_v1';
var TB_KINDS = [
  { k: 'icon', col: 'term_icon_url', home: 'icon_url', label: '탭 아이콘 (프로필 사진)', sub: '브라우저 탭 · 즐겨찾기 · 휴대폰 홈 화면에 보이는 그림', tip: '정사각형 · 192×192 이상이 선명합니다' },
  { k: 'logo', col: 'term_logo_url', home: 'logo_url', label: '터미널 로고', sub: '로그인 화면 · 맨 위 머리 · 홈 소개의 SF 자리', tip: '정사각형 · 배경이 있는 그림이 잘 보입니다' }];
var TB_DEF_ICON = 'data:image/svg+xml,' + encodeURIComponent("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'><defs><linearGradient id='g' x1='0' y1='0' x2='1' y2='1'><stop offset='0' stop-color='#2c3e6b'/><stop offset='1' stop-color='#5a7fd6'/></linearGradient></defs><rect width='64' height='64' rx='14' fill='url(#g)'/><text x='32' y='42' font-family='Arial,Helvetica,sans-serif' font-size='27' font-weight='800' fill='#fff' text-anchor='middle'>SF</text></svg>");
function tbUrlOk(u){ return typeof u === 'string' && u.length < 600 && /^https:\/\/[^\s"'<>]+$/.test(u); }
//  지금 쓰는 그림 — 터미널 것 → 홈페이지 것 → 기본
function tbEff(d){
  d = d || {};
  var pick = function(own, home){ return tbUrlOk(d[own]) ? { u: d[own], src: 'own' } : tbUrlOk(d[home]) ? { u: d[home], src: 'home' } : { u: null, src: 'def' }; };
  return { icon: pick('term_icon_url', 'icon_url'), logo: pick('term_logo_url', 'logo_url') };
}
function tbMarkHtml(el){ return el.classList.contains('hh-logo') ? '<span>SF</span>' : 'SF'; }
function tbApply(d){
  var e = tbEff(d);
  //  탭 아이콘
  var l = document.getElementById('favIcon');
  if (!l){ l = document.createElement('link'); l.id = 'favIcon'; l.rel = 'icon'; document.head.appendChild(l); }
  var href = e.icon.u || TB_DEF_ICON;
  if (l.getAttribute('href') !== href){ if (e.icon.u) l.removeAttribute('type'); else l.setAttribute('type', 'image/svg+xml'); l.setAttribute('href', href); }
  var ap = document.getElementById('favApple');
  if (e.icon.u){ if (!ap){ ap = document.createElement('link'); ap.id = 'favApple'; ap.rel = 'apple-touch-icon'; document.head.appendChild(ap); } if (ap.getAttribute('href') !== e.icon.u) ap.setAttribute('href', e.icon.u); }
  else if (ap) ap.remove();
  //  로고 (로그인 · 머리 · 홈 소개)
  var want = e.logo.u || '';
  Array.prototype.forEach.call(document.querySelectorAll('.logo-mark, .home-hero .hh-logo'), function(el){
    if ((el.__tb || '') === want) return;
    el.__tb = want;
    if (!want){ el.classList.remove('has-img'); el.innerHTML = tbMarkHtml(el); return; }
    el.classList.add('has-img'); el.innerHTML = '<img src="' + esc(want) + '" alt="" decoding="async">';
    var im = el.querySelector('img');
    //  그림을 못 받으면 원래 SF 마크로 (깨진 그림 대신)
    if (im) im.onerror = function(){ el.classList.remove('has-img'); el.innerHTML = tbMarkHtml(el); el.__tb = '\u0000'; };
  });
}
//  이 브라우저에 기억 (다음에 열면 탭 아이콘 · 로고가 바로) — 계정과 상관없는 학회 공통 그림이라 로그인 전에도 씀
function tbKeep(d){ var k = {}; ['term_icon_url', 'term_logo_url', 'icon_url', 'logo_url'].forEach(function(c){ if (tbUrlOk(d && d[c])) k[c] = d[c]; }); try { localStorage.setItem(TB_LS, JSON.stringify(k)); } catch(e){} }
function tbLoad(){
  try { var c = JSON.parse(localStorage.getItem(TB_LS) || 'null'); if (c && !TB.d) tbApply(c); } catch(e){}
  if (typeof sb === 'undefined' || !sb || !sb.from) return Promise.resolve();
  return Promise.resolve(sb.from('about').select('*').eq('id', 1).maybeSingle()).then(function(r){
    if (r && r.error){ TB.err = String(r.error.message || r.error); return; }
    TB.d = (r && r.data) || {}; TB.at = Date.now(); TB.err = null; tbKeep(TB.d); tbApply(TB.d);
  }, function(e){ TB.err = String(e && e.message || e); });
}
function tbErr(e){
  var m = String(e && (e.message || e) || '');
  if (/term_|column .* does not exist|schema cache|bucket not found|Bucket not found/i.test(m)) return 'SQL Editor 에서 terminal-홈설정.sql 을 먼저 돌려 주세요.';
  if (/row-level security|violates row|permission denied|Unauthorized|not authorized|42501|403/i.test(m)) return '임원진만 바꿀 수 있습니다.';
  return typeof errMsg === 'function' ? errMsg(e) : m;
}
//  about 한 줄 고치기 — 줄이 없으면 (홈페이지 소개글을 한 번도 안 고친 경우) 새로 만듦
async function tbWrite(patch){
  var r = await sb.from('about').update(patch).eq('id', 1).select('id');
  if (r.error) throw new Error(tbErr(r.error));
  if (!r.data || !r.data.length){
    var r2 = await sb.from('about').insert(Object.assign({ id: 1, title: '' }, patch)).select('id');
    if (r2.error) throw new Error(tbErr(r2.error));
  }
}
function tbPath(u){ var m = String(u || '').match(/\/storage\/v1\/object\/public\/logos\/(terminal\/[A-Za-z0-9._-]+)$/); return m ? m[1] : null; }   //  터미널 것만 (홈페이지 파일은 안 건드림)
function tbSay(k, t, cls){ TB.msg[k] = { t: t || '', c: cls || '' }; var el = $('tbMsg-' + k); if (el){ el.textContent = TB.msg[k].t; el.className = 'tg-msg' + (TB.msg[k].c ? ' ' + TB.msg[k].c : ''); } }
function tbFileOk(f){ if (!f) return '그림 파일을 골라 주세요.'; if (['image/png', 'image/jpeg', 'image/webp'].indexOf(f.type) < 0) return 'PNG · JPG · WebP 만 됩니다 (SVG 는 보안상 안 받습니다).'; if (f.size > 524288) return '512KB 보다 큽니다. 줄여서 올려 주세요.'; return ''; }
//  고르자마자 미리보기 (올리기 전)
function tbPick(k){
  var inp = $('tbFile-' + k), f = inp && inp.files && inp.files[0], bad = tbFileOk(f);
  if (TB.prev[k]){ try { URL.revokeObjectURL(TB.prev[k]); } catch(e){} TB.prev[k] = null; }
  var pv = $('tbPrev-' + k), go = $('tbGo-' + k);
  if (!f){ if (pv) pv.innerHTML = ''; if (go) go.disabled = true; tbSay(k, ''); return; }
  if (bad){ if (pv) pv.innerHTML = ''; if (go) go.disabled = true; tbSay(k, bad, 'err'); return; }
  try { TB.prev[k] = URL.createObjectURL(f); } catch(e){ TB.prev[k] = null; }
  if (pv) pv.innerHTML = TB.prev[k] ? '<span class="tb-pv-l">새 그림</span><img src="' + TB.prev[k] + '" alt="">' : '';
  if (go) go.disabled = false;
  tbSay(k, f.name.slice(0, 40) + ' · ' + Math.max(1, Math.round(f.size / 1024)) + 'KB · 바꾸기를 누르면 적용됩니다');
}
async function tbUpload(k){
  var spec = TB_KINDS.filter(function(x){ return x.k === k; })[0]; if (!spec || TB.busy[k]) return;
  var inp = $('tbFile-' + k), f = inp && inp.files && inp.files[0], bad = tbFileOk(f);
  if (bad){ tbSay(k, bad, 'err'); return; }
  TB.busy[k] = true; tbSay(k, '로딩 중…');
  var go = $('tbGo-' + k); if (go) go.disabled = true;
  var path = 'terminal/' + k + '-' + Date.now() + '.' + (f.type === 'image/png' ? 'png' : f.type === 'image/webp' ? 'webp' : 'jpg');
  var old = TB.d && TB.d[spec.col], up = null;
  try {
    up = await sb.storage.from('logos').upload(path, f, { contentType: f.type, upsert: false, cacheControl: '31536000' });
    if (up && up.error) throw new Error(tbErr(up.error));
    var pub = sb.storage.from('logos').getPublicUrl(path), url = pub && pub.data && pub.data.publicUrl;
    if (!tbUrlOk(url)) throw new Error('그림 주소를 받지 못했습니다.');
    var p = {}; p[spec.col] = url;
    try { await tbWrite(p); } catch(e){ sb.storage.from('logos').remove([path]).then(function(){}, function(){}); throw e; }
    var op = tbPath(old); if (op && op !== path) sb.storage.from('logos').remove([op]).then(function(){}, function(){});   //  예전 그림 정리 (실패해도 그냥 둠)
    await tbLoad();
    TB.msg[k] = { t: '바꿨습니다. 다른 학회원은 새로고침하면 보입니다.', c: 'ok' };
    if (TB.prev[k]){ try { URL.revokeObjectURL(TB.prev[k]); } catch(e){} TB.prev[k] = null; }
    tbRender();
  } catch(e){ tbSay(k, String(e && e.message || e), 'err'); if (go) go.disabled = false; }
  finally { TB.busy[k] = false; }
}
async function tbClear(k, btn){
  var spec = TB_KINDS.filter(function(x){ return x.k === k; })[0]; if (!spec || TB.busy[k]) return;
  if (btn && btn.getAttribute('data-sure') !== '1'){ btn.setAttribute('data-sure', '1'); btn.textContent = '정말 기본으로'; return; }
  TB.busy[k] = true; tbSay(k, '로딩 중…');
  var old = TB.d && TB.d[spec.col];
  try {
    var p = {}; p[spec.col] = null; await tbWrite(p);
    var op = tbPath(old); if (op) sb.storage.from('logos').remove([op]).then(function(){}, function(){});
    await tbLoad();
    TB.msg[k] = { t: '터미널 전용 그림을 뺐습니다' + (tbEff(TB.d)[k].src === 'home' ? ' · 지금은 홈페이지 그림을 따라갑니다.' : ' · 기본 SF 마크로 돌아갔습니다.'), c: 'ok' };
    tbRender();
  } catch(e){ tbSay(k, String(e && e.message || e), 'err'); }
  finally { TB.busy[k] = false; }
}
function tbRender(){
  var box = $('tbBody'); if (!box) return;
  if (!TB.d && !TB.err){ box.innerHTML = '<div class="empty">로딩 중…</div>'; return; }
  if (!TB.d){ box.innerHTML = '<div class="note">소개 · 로고 표를 읽지 못했습니다 · ' + esc(TB.err) + '</div>'; return; }
  var e = tbEff(TB.d), sqlOk = Object.prototype.hasOwnProperty.call(TB.d, 'term_icon_url');
  var SRC = { own: '터미널 전용 그림', home: '홈페이지 그림을 따라감', def: '기본 SF 마크' };
  box.innerHTML = (sqlOk ? '' : '<div class="note warn" style="margin-bottom:10px">아직 바꿀 수 없습니다 · SQL Editor 에서 <b>terminal-홈설정.sql</b> 을 먼저 돌려 주세요.</div>')
    + TB_KINDS.map(function(x){
      var cur = e[x.k], m = TB.msg[x.k] || { t: '', c: '' };
      var img = cur.u ? '<img src="' + esc(cur.u) + '" alt="지금 ' + esc(x.label) + '">' : '<span class="sf">SF</span>';
      return '<div class="tb-row" data-k="' + x.k + '">'
        + '<div class="tb-cur' + (x.k === 'icon' ? ' ic' : '') + '">' + img + '</div>'
        + '<div class="tb-main"><div class="tb-h"><b>' + esc(x.label) + '</b><span class="tb-src ' + cur.src + '">' + esc(SRC[cur.src]) + '</span><span class="st-hint">' + esc(x.sub) + ' · ' + esc(x.tip) + '</span></div>'
        + (x.k === 'icon' ? '<div class="tb-fav" aria-hidden="true"><span class="tb-tab"><i>' + (cur.u ? '<img src="' + esc(cur.u) + '" alt="">' : '<img src="' + TB_DEF_ICON + '" alt="">') + '</i>SAFE Terminal</span></div>' : '')
        + '<div class="tb-acts"><input type="file" id="tbFile-' + x.k + '" accept="image/png,image/jpeg,image/webp" onchange="tbPick(\'' + x.k + '\')"' + (sqlOk ? '' : ' disabled') + '>'
        + '<button type="button" class="btn-sm btn-solid" id="tbGo-' + x.k + '" onclick="tbUpload(\'' + x.k + '\')" disabled>바꾸기</button>'
        + (cur.src === 'own' ? '<button type="button" class="btn-sm" onclick="tbClear(\'' + x.k + '\', this)">기본으로</button>' : '') + '</div>'
        + '<div class="tb-pv" id="tbPrev-' + x.k + '"></div>'
        + '<div class="tg-msg' + (m.c ? ' ' + m.c : '') + '" id="tbMsg-' + x.k + '">' + esc(m.t) + '</div></div></div>';
    }).join('')
    + '<p class="st-hint" style="margin:10px 0 0">PNG · JPG · WebP, 512KB 까지. 터미널 전용 그림을 빼면 홈페이지 로고 · 탭 아이콘을 따라가고, 그것도 없으면 SF 마크입니다. 홈페이지 그림은 여기서 안 바뀝니다.</p>';
}

/* ── 홈 소개 (미션 · 목적 · 목표) ── */
var HI_FIELDS = [['hero_title1', '한 줄 문구 · 앞 (굵게)', 40, 0], ['hero_title2', '한 줄 문구 · 뒤', 60, 0], ['hero_desc', '미션', 300, 2], ['about_sub', '목적', 300, 2],
  ['v1_title', '목표 1 · 제목', 40, 0], ['v1_desc', '목표 1 · 설명', 200, 1], ['v2_title', '목표 2 · 제목', 40, 0], ['v2_desc', '목표 2 · 설명', 200, 1], ['v3_title', '목표 3 · 제목', 40, 0], ['v3_desc', '목표 3 · 설명', 200, 1]];
function hiIntro(d){ var t = d && d.term_intro; return t && typeof t === 'object' && !Array.isArray(t) ? t : null; }
//  지금 홈에 보이는 글 (터미널 전용 → 홈페이지 소개글 → 기본 글)
function hiMerged(d){
  var ti = hiIntro(d) || {}, out = {};
  Object.keys(HH_FB).forEach(function(k){ var v = ti[k] != null && String(ti[k]).trim() ? ti[k] : d && d[k]; if (v != null && String(v).trim()) out[k] = String(v); });
  return out;
}
function hiSay(t, c){ TB.imsg = t || ''; TB.imsgK = c || ''; var el = $('hiMsg'); if (el){ el.textContent = TB.imsg; el.className = 'tg-msg' + (TB.imsgK ? ' ' + TB.imsgK : ''); } }
function hiRender(){
  var box = $('hiBody'); if (!box) return;
  if (!TB.d){ box.innerHTML = TB.err ? '<div class="note">소개글을 읽지 못했습니다 · ' + esc(TB.err) + '</div>' : '<div class="empty">로딩 중…</div>'; return; }
  var sqlOk = Object.prototype.hasOwnProperty.call(TB.d, 'term_intro'), own = !!hiIntro(TB.d), M = hiMerged(TB.d);
  var field = function(f){
    var v = M[f[0]] != null ? M[f[0]] : HH_FB[f[0]], id = 'hi_' + f[0];
    return '<div class="hi-f' + (f[3] === 2 ? ' wide' : '') + '"><label for="' + id + '">' + esc(f[1]) + '</label>'
      + (f[3] ? '<textarea id="' + id + '" maxlength="' + f[2] + '" rows="' + (f[3] === 2 ? 2 : 2) + '">' + esc(v) + '</textarea>' : '<input type="text" id="' + id + '" maxlength="' + f[2] + '" value="' + esc(v) + '">')
      + '</div>';
  };
  box.innerHTML = '<div class="hi-src"><span class="tb-src ' + (own ? 'own' : 'home') + '">' + (own ? '지금: 터미널에만 둔 글' : '지금: 홈페이지 소개글과 같음') + '</span>'
      + '<span class="st-hint">비운 칸은 ' + (own ? '홈페이지 소개글' : '기본 글') + '로 보입니다</span></div>'
    + '<div class="hi-grid">' + HI_FIELDS.map(field).join('') + '</div>'
    + '<label class="hi-sync"><input type="checkbox" id="hiSync"' + (sqlOk ? '' : ' checked disabled') + '> 홈페이지 소개글도 같이 바꾸기 <span class="st-hint">홈페이지 첫 화면 · 소개 칸 글이 함께 바뀝니다</span></label>'
    + (sqlOk ? '' : '<div class="st-hint" style="margin-top:4px">터미널에만 따로 두려면 terminal-홈설정.sql 이 필요합니다 (지금은 홈페이지와 같이만 바뀜).</div>')
    + '<div class="tg-acts"><button type="button" class="btn-sm btn-solid" id="hiGo" onclick="hiSave()">저장</button>'
    + (own ? '<button type="button" class="btn-sm" onclick="hiReset(this)">홈페이지 글로 되돌리기</button>' : '') + '</div>'
    + '<div class="tg-msg' + (TB.imsgK ? ' ' + TB.imsgK : '') + '" id="hiMsg">' + esc(TB.imsg) + '</div>';
}
function hiVals(){
  var o = {}; HI_FIELDS.forEach(function(f){ var el = $('hi_' + f[0]); o[f[0]] = el ? String(el.value).replace(/[<>]/g, '').replace(/\s*[—–]\s*/g, ' - ').replace(/\s+/g, ' ').trim().slice(0, f[2]) : ''; });
  return o;
}
async function hiSave(){
  if (TB.busy.hi) return;
  var V = hiVals(), sync = !!($('hiSync') && $('hiSync').checked), sqlOk = TB.d && Object.prototype.hasOwnProperty.call(TB.d, 'term_intro');
  if (!V.hero_desc || !V.about_sub){ hiSay('미션 · 목적은 비울 수 없습니다.', 'err'); return; }
  var patch = {};
  if (sync){
    HI_FIELDS.forEach(function(f){ patch[f[0]] = V[f[0]] || null; });
    patch.updated_at = new Date().toISOString();
    if (sqlOk) patch.term_intro = null;
  } else {
    var ti = {}, base = TB.d || {};
    //  홈페이지 글과 같은 칸은 따로 두지 않음 (나중에 홈페이지를 고치면 그쪽을 따라가게)
    HI_FIELDS.forEach(function(f){ var hv = base[f[0]] != null && String(base[f[0]]).trim() ? String(base[f[0]]).trim() : HH_FB[f[0]]; if (V[f[0]] && V[f[0]] !== hv) ti[f[0]] = V[f[0]]; });
    patch.term_intro = Object.keys(ti).length ? ti : null;
  }
  TB.busy.hi = true; hiSay('로딩 중…'); var go = $('hiGo'); if (go) go.disabled = true;
  try {
    await tbWrite(patch); await tbLoad();
    var m = hiMerged(TB.d); try { LSX.setItem(HH_LS, JSON.stringify(m)); } catch(e){}
    if (typeof homeHeroRender === 'function') homeHeroRender(m);
    TB.imsg = sync ? '저장했습니다 · 홈페이지 소개글도 같이 바뀌었습니다.' : '저장했습니다 · 터미널 홈에만 보입니다.'; TB.imsgK = 'ok';
    hiRender();
  } catch(e){ hiSay(String(e && e.message || e), 'err'); if (go) go.disabled = false; }
  finally { TB.busy.hi = false; }
}
async function hiReset(btn){
  if (btn && btn.getAttribute('data-sure') !== '1'){ btn.setAttribute('data-sure', '1'); btn.textContent = '정말 되돌리기'; return; }
  TB.busy.hi = true; hiSay('로딩 중…');
  try { await tbWrite({ term_intro: null }); await tbLoad(); var m = hiMerged(TB.d); try { LSX.setItem(HH_LS, JSON.stringify(m)); } catch(e){} if (typeof homeHeroRender === 'function') homeHeroRender(m);
    TB.imsg = '터미널에만 둔 글을 지웠습니다 · 홈페이지 소개글을 따라갑니다.'; TB.imsgK = 'ok'; hiRender(); }
  catch(e){ hiSay(String(e && e.message || e), 'err'); }
  finally { TB.busy.hi = false; }
}

/* ── 홈 카드 보이기 (전체 공개 · 임원진만 · 숨김) — 탭 공개와 같은 서버 tab_vis · 숨김이어도 바꿀 수 있는 사람에게는 표시와 함께 보임 ── */
var HC_ROWS = [['hm_tg', '세이피 텔레그램', '홈 맨 아래 카드 · 텔레그램 연결 · 알림 구독']];
function hcSay(t, c){ TB.hmsg = t || ''; TB.hmsgK = c || ''; var el = $('hcMsg'); if (el){ el.textContent = TB.hmsg; el.className = 'tg-msg' + (TB.hmsgK ? ' ' + TB.hmsgK : ''); } }
function hcRender(){
  var box = $('hcBody'); if (!box) return;
  var can = !!(CLUB.manage && CLUB.ok);
  box.innerHTML = HC_ROWS.map(function(r){
    var v = tabVis(r[0]);
    return '<div class="hc-row"><div class="hc-n"><b>' + esc(r[1]) + '</b><span class="st-hint">' + esc(r[2]) + '</span></div><span class="mode-seg tv-seg">'
      + [['all', '전체 공개'], ['officer', '임원진만'], ['hidden', '숨김']].map(function(o){ return '<button type="button" data-v="' + o[0] + '" class="' + (v === o[0] ? 'on' : '') + '"' + (can ? '' : ' disabled') + ' onclick="hcSet(\'' + r[0] + '\',\'' + o[0] + '\')">' + o[1] + '</button>'; }).join('')
      + '</span></div>';
  }).join('')
    + (can ? '' : '<p class="st-hint" style="margin:8px 0 0">' + (CLUB.ok ? '학회장 · 설립자만 바꿀 수 있습니다 (탭 공개와 같은 권한).' : '서버 설정(terminal-직책탭공개.sql)을 아직 실행하지 않아 바꿀 수 없습니다.') + '</p>')
    + '<div class="tg-msg' + (TB.hmsgK ? ' ' + TB.hmsgK : '') + '" id="hcMsg">' + esc(TB.hmsg) + '</div>';
}
async function hcSet(k, v){
  hcSay('로딩 중…');
  try {
    var r = await sb.rpc('tab_vis_set', { p_tab: k, p_vis: v });
    if (r.error) throw new Error(tbErr(r.error));
    CLUB.vis[k] = v;
    var nm = (HC_ROWS.filter(function(x){ return x[0] === k; })[0] || [k, k])[1];
    TB.hmsg = '저장했습니다: ' + nm + ' → ' + ({ all: '전체 공개', officer: '임원진만', hidden: '숨김' }[v]) + (v === 'hidden' ? ' (바꿀 수 있는 사람에게만 표시와 함께 보임)' : ''); TB.hmsgK = 'ok';
    hcRender(); if (typeof htgVis === 'function') htgVis();
  } catch(e){ hcSay(String(e && e.message || e), 'err'); }
}
function hsRender(){ tbRender(); hiRender(); hcRender(); }
function hsInit(){ hsRender(); tbLoad().then(hsRender, hsRender); }
//  홈 소개 칸의 ‘수정’ (임원진) → 설정 › 홈
function hsOpen(){ adForce = 'home'; showTab('admin'); }
//  탭 공개 범위를 서버에서 받은 뒤 (clubLoad → tabVisApply) 홈 카드도 다시 맞춤
(function(){
  if (typeof tabVisApply !== 'function') return;
  var f0 = tabVisApply;
  tabVisApply = function(){ var r = f0.apply(this, arguments); try { if (typeof htgVis === 'function') htgVis(); } catch(e){} return r; };
})();

