    top.innerHTML = '<span class="ph-cat ' + P[0] + '">' + esc(P[1]) + '</span>';
    if (h1){ h.insertBefore(top, h1); top.appendChild(h1); } else h.insertBefore(top, h.firstChild);
    var en = document.createElement('div'); en.className = 'ph-en'; en.setAttribute('aria-hidden', 'true'); en.textContent = P[2];
    top.parentNode.insertBefore(en, top.nextSibling);
