/* ── 그림 도우미 — 선 하나 (밴드 · 기준선 · 끝 점) · 퀀트 히어로와 같은 class (qh-line · qh-area · qh-k · qh-ax · qh-s) ── */
function h19Line(vals, o){
  o = o || {};
  var v = (vals || []).map(Number).filter(function(x){ return isFinite(x); }); if (v.length < 2) return '';
  var W = 640, H = 200, x0 = 18, x1 = W - (o.padR || 96), y0 = 22, y1 = 160;
  var lo = o.min != null ? o.min : Math.min.apply(null, v), hi = o.max != null ? o.max : Math.max.apply(null, v);
  (o.lines || []).forEach(function(L){ if (o.min == null) lo = Math.min(lo, L[0]); if (o.max == null) hi = Math.max(hi, L[0]); });
  if (hi - lo < 1e-9){ hi += 1; lo -= 1; }
  var pad = o.min != null ? 0 : (hi - lo) * 0.08; lo -= pad; hi += pad;
  var X = function(i){ return x0 + (x1 - x0) * i / (v.length - 1); }, Y = function(y){ return y1 - (y1 - y0) * (y - lo) / (hi - lo); };
  var pts = v.map(function(y, i){ return [X(i), Y(y)]; }), s = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + esc(o.aria || '') + '">';
  (o.bands || []).forEach(function(B){ var a = Y(Math.min(hi, B[1])), b = Y(Math.max(lo, B[0])); if (b > a) s += '<rect class="h19-band ' + (B[2] || '') + '" x="' + x0 + '" y="' + a.toFixed(1) + '" width="' + (x1 - x0) + '" height="' + (b - a).toFixed(1) + '"/>'; });
  (o.lines || []).forEach(function(L){ var y = Y(L[0]); if (y < y0 - 4 || y > y1 + 4) return; s += '<line class="qh-k" x1="' + x0 + '" x2="' + x1 + '" y1="' + y.toFixed(1) + '" y2="' + y.toFixed(1) + '"/>' + (L[1] ? '<text class="qh-ax" x="' + (x1 + 8) + '" y="' + (y + 4).toFixed(1) + '">' + esc(L[1]) + '</text>' : ''); });
  if (o.area !== false) s += '<path class="qh-area" d="' + qSvgPath(pts) + 'L' + x1.toFixed(1) + ',' + y1 + 'L' + x0 + ',' + y1 + 'Z"/>';
  s += '<line class="qh-base" x1="' + x0 + '" x2="' + x1 + '" y1="' + y1 + '" y2="' + y1 + '"/>';
  s += '<path class="qh-line" d="' + qSvgPath(pts) + '" fill="none" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>';
  if (o.tail) s += o.tail(X, Y, x1, v.length);
  var e = pts[pts.length - 1];
  s += '<circle class="qh-s big" cx="' + e[0].toFixed(1) + '" cy="' + e[1].toFixed(1) + '" r="6"/>';
  if (o.xl) s += '<text class="qh-ax" x="' + x0 + '" y="' + (y1 + 22) + '">' + esc(o.xl[0]) + '</text><text class="qh-ax" x="' + x1 + '" y="' + (y1 + 22) + '" text-anchor="end">' + esc(o.xl[1]) + '</text>';
  return s + '</svg>';
}
//  qHero 는 처음 한 번만 꼬리표 · 제목을 씀 → 팀 · 통화쌍 · 시장이 바뀌면 처음부터 다시 그림
function h19Hero(id, key, h){ var el = $(id); if (!el) return; if (el.__k !== key){ el.__k = key; el.__on = 0; } qHero(id, h); }
function h19Show(id, on){ var el = $(id); if (el) el.classList.toggle('hidden', !on); return el; }
function h19Pct(x, d){ return (x > 0 ? '+' : '') + x.toFixed(d == null ? 1 : d) + '%'; }

/* ── 홈 — SAFE · 다음 학회 일정 D-day · 다음 주요 발표 (학회 일정표 · 증시 캘린더에서 · 새 요청 없음) ── */
var H19_HOME_SVG = '<svg viewBox="0 0 640 200" role="img" aria-label="Analyze Understand Invest">'
  + '<path class="qh-area" d="M24,160 C150,156 210,128 300,104 C390,80 450,58 600,34 L600,160 Z"/>'
  + '<line class="qh-base" x1="24" x2="616" y1="160" y2="160"/>'
  + '<path class="qh-line" d="M24,160 C150,156 210,128 300,104 C390,80 450,58 600,34" fill="none" stroke-width="3" stroke-linecap="round"/>'
  + '<line class="qh-k" x1="120" x2="120" y1="152" y2="160"/><line class="qh-k" x1="300" x2="300" y1="104" y2="160"/><line class="qh-k" x1="600" x2="600" y1="34" y2="160"/>'
  + '<circle class="qh-s" cx="120" cy="152" r="5"/><circle class="qh-s" cx="300" cy="104" r="5"/><circle class="qh-s big" cx="600" cy="34" r="7"/>'
  + '<text class="qh-ax" x="120" y="182" text-anchor="middle">ANALYZE</text><text class="qh-ax" x="300" y="182" text-anchor="middle">UNDERSTAND</text><text class="qh-ax" x="600" y="182" text-anchor="end">INVEST</text></svg>';
function h19Dow(iso){ return ['일', '월', '화', '수', '목', '금', '토'][new Date(iso + 'T00:00:00').getDay()]; }
function h19Home(){
  var box = $('homeHero'); if (!box || !box.classList.contains('hh19')) return;
  var v = $('hh19V'); if (v && !v.__on){ v.__on = 1; v.innerHTML = H19_HOME_SVG; }
  var t = typeof today === 'function' ? today() : new Date().toISOString().slice(0, 10);
  var ev = (typeof evRows !== 'undefined' ? evRows : []).filter(function(e){ return e && e.starts_on && (e.ends_on || e.starts_on) >= t; })
            .sort(function(a, b){ return a.starts_on < b.starts_on ? -1 : a.starts_on > b.starts_on ? 1 : 0; })[0];
  var L = $('hh19L'), N = $('hh19N'), no = $('hh19Note');
  if (ev){
    var dd = Math.round((Date.parse(ev.starts_on > t ? ev.starts_on : t) - Date.parse(t)) / 864e5);
    if (L) L.textContent = '다음 학회 일정';
    if (N) N.textContent = dd <= 0 ? 'TODAY' : 'D-' + dd;
    if (no) no.textContent = String(ev.title || '일정').slice(0, 40) + ' · ' + Number(ev.starts_on.slice(5, 7)) + '/' + Number(ev.starts_on.slice(8, 10)) + ' (' + h19Dow(ev.starts_on) + ')' + (ev.at_time ? ' ' + String(ev.at_time).slice(0, 5) : '');
  } else {
    if (L) L.textContent = '오늘';
    if (N) N.textContent = Number(t.slice(5, 7)) + '.' + ('0' + Number(t.slice(8, 10))).slice(-2);
    if (no) no.textContent = (typeof evLoaded !== 'undefined' && evLoaded) ? '예정된 학회 일정이 없습니다' : '';
  }
  //  다음 주요 발표 (★★★ · 발표 전)
  var act = $('hh19Act'), E = typeof econData !== 'undefined' && econData && econData.events ? econData.events : [];
  var nx = E.filter(function(e){ return e && e.importance >= 3 && e.actual == null && e.kst_date >= t; })
            .sort(function(a, b){ return (a.kst_date + (a.kst_time || '')) < (b.kst_date + (b.kst_time || '')) ? -1 : 1; })[0];
  if (act){
    act.classList.toggle('hidden', !nx);
    if (nx){
      var tm = /^\d{1,2}:\d{2}/.test(String(nx.kst_time || '')) ? String(nx.kst_time).slice(0, 5) : (typeof ecKoTime === 'function' ? ecKoTime(nx.kst_time) : '');
      act.querySelector('b').textContent = nx.name + ' · ' + Number(nx.kst_date.slice(5, 7)) + '/' + Number(nx.kst_date.slice(8, 10)) + ' (' + h19Dow(nx.kst_date) + ') ' + tm;
      act.querySelector('em').textContent = (nx.previous_txt != null ? '이전 ' + nx.previous_txt + ' · ' : '') + '모든 시각은 한국시간 · 아래 증시 캘린더';
    }
  }
}

/* ── 매크로 경제 — 고른 팀의 대표 지표 하나 (카드와 같은 값 · mcMain) · 읽는 법은 정해진 기준만 ── */
var H19_MAC = { infl: 'CPIAUCSL', jobs: 'UNRATE', mfg: 'TCU', rates: 'T10Y2Y' };
function h19MacItem(team){
  var t = MACRO_TEAMS[team]; if (!t) return null;
  var want = H19_MAC[team], it = want ? t.items.filter(function(x){ return x.c === want; })[0] : null;
  return it || t.items.filter(function(x){ return x.b && x.st >= 3; })[0] || t.items.filter(function(x){ return x.b; })[0] || t.items[0];
}
function h19Sahm(sp){
  //  삼 법칙: 최근 3개월 평균 실업률 − 그 전 12개월 동안의 ‘3개월 평균’ 최저 (0.5%p 이상이면 신호)
  if (!sp || sp.length < 16) return null;
  var m3 = []; for (var i = 2; i < sp.length; i++) m3.push((sp[i] + sp[i - 1] + sp[i - 2]) / 3);
  var cur = m3[m3.length - 1], prev = m3.slice(-13, -1); if (prev.length < 12) return null;
  return cur - Math.min.apply(null, prev);
}
function h19MacRead(team, it, s, yoy){
  var v = s.v, a3 = s.a3;
  if (team === 'infl' && it.c === 'CPIAUCSL' && yoy != null){
    var gap = yoy - 2;
    if (yoy >= 3) return { act: ['sell', '물가 압력 높음 · 금리 인하 기대는 약해지는 쪽', '전년비 ' + yoy.toFixed(1) + '% · 연준 목표 2%보다 ' + gap.toFixed(1) + '%p 높음'], fx: '소비자물가 전년비 = 1년 전 같은 달보다 물가가 얼마나 올랐나 · 연준 목표는 2% (근원 PCE 기준)' };
    if (yoy >= 2) return { act: ['hold', '목표 2% 근처 · 다음 발표의 방향 확인', '전년비 ' + yoy.toFixed(1) + '% · 목표와 차이 ' + (gap >= 0 ? '+' : '') + gap.toFixed(1) + '%p'], fx: '소비자물가 전년비 = 1년 전 같은 달보다 물가가 얼마나 올랐나 · 연준 목표는 2% (근원 PCE 기준)' };
    return { act: ['buy', '목표 2% 아래 · 금리 인하 여지 (채권에 우호적)', '전년비 ' + yoy.toFixed(1) + '%'], fx: '소비자물가 전년비 = 1년 전 같은 달보다 물가가 얼마나 올랐나 · 연준 목표는 2%' };
  }
  if (team === 'jobs' && it.c === 'UNRATE'){
    var sh = h19Sahm(s.spark);
    var fx = '삼 법칙 = 최근 3개월 평균 실업률이 직전 12개월 중 가장 낮던 3개월 평균보다 0.5%p 이상 높으면 경기 침체 초입 신호 (1970년 이후 침체마다 켜짐)';
    if (sh == null) return { act: ['hold', '실업률 ' + v.toFixed(1) + '%', '자료가 모자라 삼 법칙은 계산하지 않음'], fx: fx };
    if (sh >= 0.5) return { act: ['sell', '삼 법칙 켜짐 · 경기 둔화 경고', '3개월 평균이 저점보다 +' + sh.toFixed(2) + '%p'], fx: fx };
    if (sh >= 0.3) return { act: ['hold', '삼 법칙 근접 · 고용 둔화 관찰', '3개월 평균이 저점보다 +' + sh.toFixed(2) + '%p (기준 0.5%p)'], fx: fx };
    return { act: ['buy', '고용 견조 · 경기 확장 유지', '3개월 평균이 저점보다 +' + sh.toFixed(2) + '%p (기준 0.5%p)'], fx: fx };
  }
  if (team === 'mfg' && it.c === 'TCU'){
    var fx2 = '설비가동률 = 공장이 낼 수 있는 생산 가운데 실제로 쓰는 비율 · 1972년 이후 평균은 80% 안팎';
    if (v >= 80) return { act: ['buy', '가동률 높음 · 증설 · 설비투자 압력', v.toFixed(1) + '% · 80% 이상'], fx: fx2 };
    if (v < 75) return { act: ['sell', '가동률 낮음 · 수요 약함', v.toFixed(1) + '% · 75% 아래'], fx: fx2 };
    return { act: ['hold', '가동률 보통 (75~80%)', v.toFixed(1) + '% · 3개월 ' + (a3 > 0 ? '오름' : a3 < 0 ? '내림' : '보합')], fx: fx2 };
  }
  if (team === 'rates' && it.c === 'T10Y2Y'){
    var fx3 = '10년 − 2년 국채 금리차 · 0 아래(역전) = 시장이 앞으로 금리 인하 · 경기 둔화를 본다는 뜻 · 역전 뒤 경기 침체가 온 적이 많음';
    if (v < 0) return { act: ['sell', '장단기 금리 역전 · 경기 침체 선행 신호', v.toFixed(2) + '%p'], fx: fx3 };
    if (v < 0.5) return { act: ['hold', '곡선 평탄 (0~0.5%p)', v.toFixed(2) + '%p · 최근 ' + (a3 > 0 ? '가팔라지는 중' : a3 < 0 ? '평탄해지는 중' : '보합')], fx: fx3 };
    return { act: ['buy', '정상 곡선 (우상향)', v.toFixed(2) + '%p'], fx: fx3 };
  }
  var dir = a3 > 0 ? '오름' : a3 < 0 ? '내림' : '보합';
  return { act: ['hold', '최근 방향 ' + dir, (s.ya != null ? '1년 전 ' + mcNum(s.ya) + ' → 지금 ' + mcNum(v) : '')], fx: it.d ? String(it.d).slice(0, 140) : '' };
}
var h19MacT = 0;
function h19MacLater(){ clearTimeout(h19MacT); h19MacT = setTimeout(h19Macro, 120); }
function h19Macro(){
  var el = $('h19Mac'); if (!el || typeof MACRO_TEAMS === 'undefined' || typeof macroTeam === 'undefined') return;
  var team = macroTeam, t = MACRO_TEAMS[team], it = h19MacItem(team), s = it && mcCached(mcKey(it));
  if (!t || !it || !s || !s.spark || s.spark.length < 3){ el.classList.add('hidden'); return; }
  el.classList.remove('hidden');
  var m = mcMain(it, s), label = indName(it.s, it.c, it.i, it.l);
  var yoy = it.t === 'idx' && s.ya ? (s.v / s.ya - 1) * 100 : null;
  var R = h19MacRead(team, it, s, yoy), part = m.parts && m.parts[0], pp = m.lbl === '%p' || m.lbl === 'pp';      //  %p 는 큰 숫자 뒤에 붙임
  var lines = it.c === 'T10Y2Y' ? [[0, '0 = 역전']] : it.c === 'TCU' ? [[80, '80%']] : [];
  h19Hero('h19Mac', team + '|' + it.c + '|' + (isEn() ? 'en' : 'ko'), { th: 'paper', tags: [[t.n, 'g'], [it.s.toUpperCase() + ' · ' + (it.cy === 'D' ? '일' : it.cy === 'Q' ? '분기' : '월'), 'y']],
    title: (isEn() ? (t.en || t.n) : (t.en || t.n)), sub: (it.c + ' · ' + mcDateShort(s.d, it.cy) + (it.t === 'idx' ? ' · LINE = INDEX LEVEL' : '')).toUpperCase(),
    svg: h19Line(s.spark, { lines: lines, aria: label, xl: [(it.cy === 'D' ? s.spark.length + 'D' : s.spark.length + 'M') + ' AGO', 'NOW'] }),
    lab: label, val: m.big + (pp ? '%p' : ''), valCls: 'gold', note: [pp ? '' : m.lbl, part ? part.k + ' ' + part.v : ''].filter(Boolean).join(' · '),
    fx: R.fx, act: R.act });
}

/* ── 주식분석 — 시장 폭 (200일선 위 종목 비율 · 서버 계산 stk_scan 그대로) ── */
function h19Stk(){
  var el = $('h19Stk'); if (!el || typeof STK === 'undefined') return;
  var D = STK.data && STK.data[STK.mkt]; if (!D || !D.br || D.br.a200 == null){ el.classList.add('hidden'); return; }
  el.classList.remove('hidden');
  var B = D.br, ph = stkPhase(B.a200), h = (D.hist || []).filter(function(x){ return x && x.a200 != null; });
  var ACT = { hot: ['sell', '과열 (80% 이상) · 과열 경계 · 변동성 주의', '대부분 종목이 이미 오름세'], bull: ['buy', '강세 · 추세에 우호적 (보유)', '60~80%'],
    mid: ['hold', '중립 · 방향 확인', '40~60%'], bear: ['hold', '약세 · 방어적 · 반등 확인 뒤', '20~40%'], cold: ['buy', '침체 (20% 이하) · 역사적 침체 구간', '역사적으로 바닥 부근 · 더 내릴 수는 있음'] };
  var a = ACT[ph[0]];
  h19Hero('h19Stk', STK.mkt + '|' + ph[0], { th: 'blue', tags: [[STK.mkt === 'US' ? 'S&P 500' : '한국 상위 100', 'y'], [ph[1], 'g']], title: 'Market Breadth',
    sub: '% ABOVE 200-DAY · ' + B.n + ' STOCKS · ' + String(D.asof || '').toUpperCase(),
    svg: h19Line(h.map(function(x){ return x.a200; }), { min: 0, max: 100, bands: [[80, 100, 'hot'], [0, 20, 'cold']], lines: [[80, '과열 80%'], [20, '침체 20%']], aria: '200일선 위 종목 비율', xl: h.length ? [String(h[0].d).slice(5), String(h[h.length - 1].d).slice(5)] : null }),
    lab: '200일선 위 종목', val: B.a200, fmt: function(x){ return x.toFixed(1) + '%'; }, valCls: 'gold', note: '50일선 위 ' + B.a50.toFixed(1) + '% · 오른 ' + B.adv + ' · 내린 ' + B.dec,
    fx: '시장 폭 = 지수가 아니라 종목 가운데 몇 %가 오름세(200일선 위)인지 · 52주 신고가 ' + B.nh + ' · 신저가 ' + B.nl + ' · RSI 중앙값 ' + (B.rsiMed != null ? B.rsiMed.toFixed(0) : '-'),
    act: [a[0], a[1], a[2]] });
}

/* ── 산업분석 — 산업 사이클 시계 (병목 모니터의 긴장도 · 6개월 변화 · cycClockRows 그대로) ── */
function h19Ind(){
  var el = $('h19Ind'); if (!el || typeof cycClockRows !== 'function') return;
  var R = []; try { R = cycClockRows(); } catch(e){ R = []; }
  if (!R.length){ el.classList.add('hidden'); return; }
  el.classList.remove('hidden');
  var by = { rec: [], exp: [], slow: [], con: [] }; R.forEach(function(r){ by[r.q[0]].push(r); });
  var dom = ['exp', 'slow', 'con', 'rec'].sort(function(a, b){ return by[b].length - by[a].length; })[0];
  var avg = Math.round(R.reduce(function(p, r){ return p + r.x; }, 0) / R.length);
  var NM = { rec: '회복', exp: '확장', slow: '둔화', con: '침체' };
  var ACT = { exp: ['buy', '확장 우세 · 경기민감 업종에 우호적', ''], slow: ['hold', '둔화 우세 · 이익 정점 경계', ''], con: ['sell', '침체 우세 · 방어적', ''], rec: ['buy', '회복 우세 · 초기 경기민감 업종 관심', ''] };
  var W = 640, H = 200, cx = 330, cy = 98, sx = 2.6, sy = 2.4;
  var s = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="산업 사이클 시계">'
    + '<line class="qh-k" x1="' + (cx - 130) + '" x2="' + (cx + 130) + '" y1="' + cy + '" y2="' + cy + '"/><line class="qh-k" x1="' + cx + '" x2="' + cx + '" y1="14" y2="182"/>'
    + '<text class="qh-ax" x="' + (cx + 126) + '" y="30" text-anchor="end">확장 ' + by.exp.length + '</text><text class="qh-ax" x="' + (cx + 126) + '" y="178" text-anchor="end">둔화 ' + by.slow.length + '</text>'
    + '<text class="qh-ax" x="' + (cx - 126) + '" y="178">침체 ' + by.con.length + '</text><text class="qh-ax" x="' + (cx - 126) + '" y="30">회복 ' + by.rec.length + '</text>';
  R.forEach(function(r){ var x = cx + Math.max(-125, Math.min(125, (r.x - 50) * sx)), y = cy - Math.max(-80, Math.min(80, r.dy * sy));
    s += '<circle class="qh-s" cx="' + x.toFixed(1) + '" cy="' + y.toFixed(1) + '" r="5"><title>' + esc((r.g.n || '') + ' · ' + r.x + ' · ' + (r.dy > 0 ? '+' : '') + r.dy) + '</title></circle>'; });
  s += '</svg>';
  var cn = typeof bnCtryName === 'function' && typeof bnCtry !== 'undefined' ? bnCtryName(bnCtry) : '';
  var a = ACT[dom];
  h19Hero('h19Ind', cn + '|' + dom, { th: 'paper', tags: [[cn || '산업', 't'], ['Industry Clock', 'p']], title: 'Industry Cycle', sub: R.length + ' INDUSTRY GROUPS · TENSION PERCENTILE SINCE 2015 · 6M CHANGE',
    svg: s, lab: '평균 수급 긴장도', val: avg, fmt: function(x){ return String(Math.round(x)); }, valCls: 'gold', note: NM[dom] + ' ' + by[dom].length + '곳이 가장 많음 · 0~100 백분위',
    fx: '가로 = 지금 수급 긴장도 (가동률 · 재고 · 주문 · 가격의 2015년 이후 백분위 평균) · 세로 = 6개월 전보다 바뀐 폭 · 업황은 보통 회복 → 확장 → 둔화 → 침체 순으로 돎',
    act: [a[0], a[1], '회복 ' + by.rec.length + ' · 확장 ' + by.exp.length + ' · 둔화 ' + by.slow.length + ' · 침체 ' + by.con.length] });
}

/* ── 환율 분석 — 고른 통화쌍 · 지금 값 · 고른 기간의 모델 방향 (mkFxDir 그대로) ── */
function h19Fx(){
  var el = $('h19Fx'); if (!el || typeof mkFxReady !== 'function') return;
  if (!mkFxReady()){ el.classList.add('hidden'); return; }
  var P = MK_FX_PAIRS.filter(function(x){ return x.k === MK.fxPair; })[0], M = P && MK.fx[P.k];
  if (!M || M.err || !M.hist || M.hist.length < 30){ el.classList.add('hidden'); return; }
  el.classList.remove('hidden');
  var hSel = MK.fxH || 21, r = M.h[hSel] || M.h[21], a = mkFxAnchor(P, M), D = mkFxDir(P, r);
  var hist = M.hist.slice(-252), vals = hist.map(function(x){ return x[1]; });
  var md = a * Math.exp(r.mu), lo = a * Math.exp(r.mu - r.sd), hiV = a * Math.exp(r.mu + r.sd), pc = (Math.exp(r.mu) - 1) * 100;
  var tail = function(X, Y, x1, n){
    var xe = x1 + 70, y0 = Y(vals[n - 1]);
    return '<path class="h19-fan" d="M' + x1.toFixed(1) + ',' + y0.toFixed(1) + 'L' + xe + ',' + Y(hiV).toFixed(1) + 'L' + xe + ',' + Y(lo).toFixed(1) + 'Z"/>'
      + '<line class="qh-k" x1="' + x1.toFixed(1) + '" y1="' + y0.toFixed(1) + '" x2="' + xe + '" y2="' + Y(md).toFixed(1) + '"/>';
  };
  var all = vals.concat([lo, hiV, md]), mn = Math.min.apply(null, all), mx = Math.max.apply(null, all);
  var ACT = D ? [D.d > 0 ? 'buy' : D.d < 0 ? 'sell' : 'hold', mkFxHn(hSel) + ' 뒤 ' + D.word + (D.lv ? ' (' + D.lv + ')' : '') + ' · ' + D.mean, '중앙 ' + mkFxFmt(md, P.k) + ' (' + mkPct2(pc) + ') · 68% 범위 ' + mkFxFmt(lo, P.k) + ' ~ ' + mkFxFmt(hiV, P.k)] : null;
  h19Hero('h19Fx', P.k, { th: 'blue', tags: [[P.n, 'y'], ['FX Model', 'p']], title: P.n, sub: 'RIDGE · CARRY · MOMENTUM · PPP · DXY · VIX · LAST ' + String(M.lastD || '').toUpperCase(),
    svg: h19Line(vals, { padR: 160, min: mn - (mx - mn) * 0.06, max: mx + (mx - mn) * 0.06, tail: tail, aria: P.n + ' 1년', xl: [String(new Date(hist[0][0]).toISOString()).slice(0, 7), mkFxHn(hSel) + ' 뒤'] }),
    lab: '지금', val: mkFxFmt(a, P.k), valCls: 'gold', note: D ? '오를 확률 ' + Math.round(D.pUp * 100) + '% · ' + mkFxHn(hSel) : '',
    fx: '모델 = 금리차 · 모멘텀 · 1년 평균 회귀 · 물가로 본 적정 환율 · 달러지수 · VIX 를 최근 3년 걷기 검증으로 맞춘 확률 범위',
    act: ACT });
}

/* ── 탭이 열리거나 그 탭의 자료가 새로 그려질 때 ── */
function h19Tab(name){
  try {
    if (name === 'home') h19Home();
    else if (name === 'research') h19Macro();
    else if (name === 'stocks') h19Stk();
    else if (name === 'industry') h19Ind();
    else if (name === 'fxa') h19Fx();
  } catch(e){ console.warn('히어로', name, e); }
}
(function(){
  var wrap = function(nm, after){ if (typeof window[nm] !== 'function') return; var f0 = window[nm]; window[nm] = function(){ var r = f0.apply(this, arguments); try { after(); } catch(e){} return r; }; };
  wrap('showTab', function(){ h19Tab(curTab); });
  wrap('stkAllRender', h19Stk);
  wrap('cycRender', h19Ind);
  wrap('mkFxRender', h19Fx);
  wrap('evRender', h19Home);
  wrap('renderEcon', h19Home);
  wrap('mcPaint', h19MacLater);
  wrap('renderMacroTeam', h19MacLater);
  wrap('homeHeroRender', function(){ setTimeout(h19Home, 0); });
  wrap('innerVisApply', function(){ if (typeof qmSegTidy === 'function') qmSegTidy(); });      //  모델 묶음: 단추가 다 숨으면 머리글도
})();

/* ══════════ (19차) 세이피 — 답 길이 · 말로 대화 기다림 · 설정 › AI 모델 · 목소리 ══════════
   학회장: ‘세이피 답 최대한 간략하게 · 3줄 이내, 5줄 이내, 10줄 이내로 답하기 옵션’
           ‘대화 시작할 때 마이크 30초 유지 · 말하면 끝까지 듣고 · 말 중간 pause 20초 정도 · 세이피가 답한 뒤 1분 · 대화에 대한 기본적인 배려심’
           ‘설정에 세이피 haiku, opus 가장 싼 버전으로 전환 · 설정에서도 목소리 옵션’
   · 답 길이: 이 브라우저에 기억 (safe_aic_len_v1 · 기본 3줄) → 서버가 그 줄 수 안으로 답함
   · 듣기 (aivMic 은 index 안의 19차 판) — 말을 시작하기 전: 처음 30초 · 답을 읽은 뒤 1분 · 말을 시작한 뒤: 쉼이 20초(여유 · 기본) 이어지면 보냄
     다 말했으면 마이크를 한 번 더 누르거나 Enter = 바로 보냄 · 글자를 치기 시작하면 듣기를 멈추고 친 글은 그대로
   · 설정 › AI: 모델 (Haiku 5.5 · Opus 5.5) · 목소리 (Google 30종 · ElevenLabs 목소리 ID) · 빠르기 · 미리 듣기 (열쇠는 Secrets 에만)  */
var AIV_WAIT = { start: 30000, reply: 60000 };
var AIV_PAUSE = { slow: 20000, mid: 8000, fast: 3000 };
var AIC_LEN_KEY = 'safe_aic_len_v1';
function aicLen(){ var v = 3; try { v = Number(LSX.getItem(AIC_LEN_KEY)) || 3; } catch(e){} return [3, 5, 10].indexOf(v) >= 0 ? v : 3; }
function aicLenSet(n){ n = [3, 5, 10].indexOf(Number(n)) >= 0 ? Number(n) : 3; try { LSX.setItem(AIC_LEN_KEY, String(n)); } catch(e){} aicLenRender(); }
function aicLenRender(){
  var g = $('aicLenSeg'); if (!g) return; var n = aicLen();
  Array.prototype.forEach.call(g.querySelectorAll('button'), function(b){ var on = Number(b.getAttribute('data-n')) === n; b.classList.toggle('on', on); b.setAttribute('aria-pressed', on ? 'true' : 'false'); });
}
function aivPauseMs(){ return AIV_PAUSE[AIV.pause] || AIV_PAUSE.slow; }
function aivPauseSet(v){ AIV.pause = AIV_PAUSE[v] ? v : 'slow'; aivSave(); aivBtn(); }
//  말 빠르기 — 서버 목소리는 서버가 · 브라우저 목소리는 여기서 (설정 › AI 의 빠르기 · 미리 듣기 중이면 그 값)
function aivRate(){ var s = AIVS.spPrev || (aicStatus && Number(aicStatus.speed)) || 1; return Math.min(1.2, Math.max(0.8, s)); }
(function(){ var go = function(){ aicLenRender(); try { aivBtn(); } catch(e){} }; if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', go); else setTimeout(go, 0); })();

/* ── 설정 › AI — 모델 ── */
function aicModelRow(st){
  if (!st || st.model == null) return '<p class="st-hint aic-model" style="margin:8px 0 0">모델 · 목소리 고르기: SQL Editor 에서 <b>terminal-세이피설정.sql</b> 을 한 번 돌리면 여기서 바꿀 수 있습니다.</p>';
  var m = st.model === 'opus' ? 'opus' : 'haiku';
  return '<div class="aic-model"><b>모델</b><span class="px-seg" role="group" aria-label="세이피 모델">'
    + '<button type="button" class="' + (m === 'haiku' ? 'on' : '') + '" aria-pressed="' + (m === 'haiku') + '" onclick="aicModelSave(\'haiku\')">Haiku 5.5</button>'
    + '<button type="button" class="' + (m === 'opus' ? 'on' : '') + '" aria-pressed="' + (m === 'opus') + '" onclick="aicModelSave(\'opus\')">Opus 5.5</button></span>'
    + '<span class="st-hint">' + (m === 'opus'
        ? 'Opus 5.5 · Opus 가운데 가장 싼 판 · 더 깊게 생각 · 입력 $4 · 출력 $20 (100만 토큰) · Haiku 5.5 의 약 40배'
        : 'Haiku 5.5 · 가장 빠르고 쌈 (기본) · 입력 $0.10 · 출력 $0.50 (100만 토큰)')
    + ' · 터미널 · 텔레그램 세이피가 같이 씀 · 이 키로 못 쓰는 모델이면 Haiku 4.5 로 답함</span></div>';
}
async function aicModelSave(m){
  var msg = $('aicSetMsg'); if (msg){ msg.style.color = ''; msg.textContent = '저장 중…'; }
  try {
    var r = await sb.rpc('ai_chat_admin_opts', { p_model: m });
    if (r.error) throw new Error(/ai_chat_admin_opts/.test(String(r.error.message || '')) ? 'terminal-세이피설정.sql 을 먼저 돌려 주세요.' : errMsg(r.error));
    aicStatus = r.data || aicStatus;
    var row = document.querySelector('.aic-model'); if (row) row.outerHTML = aicModelRow(aicStatus);
    if (msg){ msg.style.color = 'var(--pos)'; msg.textContent = '저장했습니다 - 세이피 모델: ' + (m === 'opus' ? 'Opus 5.5' : 'Haiku 5.5') + ' (다음 질문부터)'; }
  } catch(e){ if (msg){ msg.style.color = 'var(--neg)'; msg.textContent = e.message || String(e); } }
}

