  var S = lvSecs(), sig = S.map(function(g){ return g[0] + ':' + g[2].map(function(t){ return t.id; }).join(','); }).join('|');
  if (LV.built === sig && $('lvBoard')){ lvSnapTiles(); return; }
  LV.built = sig;
