/*<<21차*/
/* ══════════ (21차) 마켓 맵 › 원자재 › 병목 지수 — 학회장: ‘원자재 마켓맵에 병목 지수도 넣으면 좋겠다 · 근거와 출처와 함께’ ══════════
   · 서버(market-data res_bn · 6시간)가 요소마다 0~100 (재고 · 수급 · 물류 · 가격 · 포지션) + 지금 값 · 출처 · 기준일
   · 화면이 ‘공급 집중’ (나라 생산 비중 HHI · 이 칸의 생산 표) 을 더해 무게 평균 → 0~100 (70 이상 공급 병목 · 30 이하 공급 과잉 · 산업분석 수급 긴장도와 같은 눈금)
   · 요소가 둘 미만이면 점수 없이 요소만 · 지어내지 않음 · 출처는 공개 기관 이름 (EIA · USDA · IMF PortWatch · CFTC · 생산 표 출처)        */
var RB = { d: null, at: 0, busy: false, err: null, open: false };
var RB_W = { inv: 30, bal: 20, log: 15, px: 20, pos: 5, hhi: 10 };
var RB_NM = { inv: ['재고', 'Inventory'], bal: ['수급', 'Balance'], log: ['물류', 'Logistics'], px: ['가격', 'Price'], pos: ['포지션', 'Positioning'], hhi: ['공급 집중', 'Supply concentration'] };
function rbLoad(force){
  if (RB.busy || (!force && RB.d && Date.now() - RB.at < 30 * 60_000)) return;
  RB.busy = true;
  edge({ source: 'res_bn' }).then(function(d){
    RB.busy = false;
    if (d && d.error === 'pending'){ setTimeout(function(){ rbLoad(true); }, 20000); return; }
    if (!d || d.error){ RB.err = d && d.error || 'x'; rbPaint(); return; }
    RB.d = d; RB.at = Date.now(); RB.err = null; rbPaint();
  }, function(e){ RB.busy = false; RB.err = e; rbPaint(); });
}
//  공급 집중 (HHI · 이 칸의 나라 생산 비중) — 2,500 → 50 · 5,000 이상 → 100
function rbHhi(k){
  var L = (MK.lay === 'res' && MK.res === k && MK.layD) ? MK.layD : (typeof mkLayerDataFor === 'function' ? mkLayerDataFor('res', k) : null);
  if (!L || !L.rows || L.rows.length < 3) return null;
  var rs = L.rows.filter(function(r){ return r.cc !== 'OT' && r.s != null; }); if (rs.length < 3) return null;
  var h = Math.round(rs.reduce(function(a, r){ return a + r.s * r.s; }, 0)), t3 = rs.slice(0, 3).reduce(function(a, r){ return a + r.s; }, 0), R = mkResOf(k);
  return { k: 'hhi', s: Math.max(0, Math.min(100, Math.round(h / 50))), v: T('생산 상위 3개국 ', 'Top 3 producers ') + Math.round(t3) + '% · HHI ' + h.toLocaleString('en-US') + (h >= 2500 ? T(' (고집중)', ' (high)') : h >= 1500 ? T(' (다소 집중)', ' (moderate)') : T(' (분산)', ' (low)')), src: String(R.src || L.src || T('마켓 맵 생산 표', 'production table')), d: String(L.yr || R.yr || '') };
}
function rbOf(k){
  var C = (RB.d && RB.d.c && RB.d.c[k] || []).slice(), h = rbHhi(k); if (h) C.push(h);
  var core = C.filter(function(c){ return c.k !== 'hhi'; });
  //  같은 요소가 둘이면 (예: 재고) 하나만 — 서버 순서대로
  var seen = {}; C = C.filter(function(c){ if (seen[c.k]) return false; seen[c.k] = 1; return true; });
  var W = RB.d && RB.d.w || RB_W, sw = 0, ss = 0; C.forEach(function(c){ var w = W[c.k] || 0; sw += w; ss += w * c.s; });
  return { k: k, comps: C, score: core.length >= 2 && sw ? Math.round(ss / sw) : null, n: core.length };
}
function rbWhy(o){
  var hot = o.comps.filter(function(c){ return c.s >= 65; }).sort(function(a, b){ return b.s - a.s; }), cold = o.comps.filter(function(c){ return c.s <= 35; }).sort(function(a, b){ return a.s - b.s; });
  var L = [];
  if (hot.length) L.push(T('빠듯하게 만드는 쪽: ', 'Tightening: ') + hot.slice(0, 2).map(function(c){ return T(RB_NM[c.k][0], RB_NM[c.k][1]) + ' ' + c.s; }).join(' · '));
  if (cold.length) L.push(T('느슨하게 만드는 쪽: ', 'Loosening: ') + cold.slice(0, 2).map(function(c){ return T(RB_NM[c.k][0], RB_NM[c.k][1]) + ' ' + c.s; }).join(' · '));
  return L;
}
function rbBox(k){
  if (!RB.d) return '<div class="rb-box" id="rbBox"><div class="rb-h"><span class="rb-k">' + esc(T('원자재 병목 지수', 'Commodity bottleneck index')) + '</span></div><div class="mk-wait">' + esc(RB.err ? T('지금은 계산할 수 없습니다.', 'Unavailable now.') : T('로딩 중…', 'Loading…')) + '</div></div>';
  var o = rbOf(k), sg = typeof bnSignal === 'function' ? bnSignal(o.score) : { c: 'var(--text)', t: '' }, why = rbWhy(o);
  var gauge = '<div class="rb-g" role="img" aria-label="' + esc(T('병목 지수 ', 'index ') + (o.score == null ? '-' : o.score)) + '"><span class="z lo"></span><span class="z md"></span><span class="z hi"></span>' + (o.score == null ? '' : '<i style="left:' + o.score + '%"></i>') + '<em class="t30">30</em><em class="t70">70</em></div>';
  var rows = o.comps.slice().sort(function(a, b){ return (RB_W[b.k] || 0) - (RB_W[a.k] || 0); }).map(function(c){ var s2 = bnSignal(c.s);
    return '<div class="rb-r"><div class="rb-rt"><b>' + esc(T(RB_NM[c.k][0], RB_NM[c.k][1])) + '</b><span class="rb-w">' + esc(T('무게 ', 'w ') + (RB_W[c.k] || 0)) + '</span><span class="rb-bar"><i style="width:' + c.s + '%;background:' + s2.c + '"></i></span><b class="rb-s" style="color:' + s2.c + '">' + c.s + '</b></div>'
      + '<p>' + esc(c.v) + '</p><p class="rb-src">' + esc(T('출처 ', 'Source ') + c.src + (c.d ? ' · ' + c.d : '')) + '</p></div>'; }).join('');
  return '<div class="rb-box" id="rbBox"><div class="rb-h"><span class="rb-k">' + esc(T('원자재 병목 지수', 'Commodity bottleneck index')) + '</span>'
    + '<b class="rb-v" style="color:' + sg.c + '">' + (o.score == null ? '-' : o.score) + '</b><span class="rb-t" style="color:' + sg.c + '">' + esc(o.score == null ? T('자료가 모자라 점수 없음', 'Not enough data') : sg.t) + '</span>'
    + '<button type="button" class="btn-sm rb-cmp" onclick="rbCmpTog()">' + esc(RB.open ? T('비교 닫기', 'Close') : T('다른 원자재와 비교', 'Compare')) + '</button></div>' + gauge
    + (why.length ? '<ul class="rb-why">' + why.map(function(l){ return '<li>' + esc(l) + '</li>'; }).join('') + '</ul>' : '')
    + '<details class="rb-d"' + (RB.det ? ' open' : '') + ' ontoggle="RB.det=this.open"><summary>' + esc(T('요소 ', 'Components ') + o.comps.length + T('개 · 근거 · 출처', ' · evidence · sources')) + '</summary>' + rows
    + '<p class="st-hint">' + esc(T('요소마다 0~100 (높을수록 공급이 빠듯) · 있는 요소만 무게로 평균 · 70 이상 공급 병목 · 30 이하 공급 과잉 · 요소가 둘 미만이면 점수를 내지 않음', '0-100 per component · weighted average of available components')) + '</p></details>'
    + (RB.open ? rbCmpHtml(k) : '') + '</div>';
}
function rbCmpHtml(k){
  var L = MK_RES.map(function(R){ var o = rbOf(R.k); return { k: R.k, n: R.n, s: o.score, n2: o.n }; }).filter(function(x){ return x.s != null; }).sort(function(a, b){ return b.s - a.s; });
  var miss = MK_RES.filter(function(R){ return rbOf(R.k).score == null; }).map(function(R){ return R.n; });
  return '<div class="rb-cmp-l">' + L.map(function(x){ var sg = bnSignal(x.s); return '<button type="button" class="rb-ci' + (x.k === k ? ' on' : '') + '" onclick="mkResSet(\'' + x.k + '\')"><span class="n">' + esc(x.n) + '</span><span class="rb-bar"><i style="width:' + x.s + '%;background:' + sg.c + '"></i></span><b style="color:' + sg.c + '">' + x.s + '</b></button>'; }).join('')
    + (miss.length ? '<p class="st-hint">' + esc(T('자료가 모자라 점수 없음: ', 'No score: ') + miss.join(' · ')) + '</p>' : '') + '</div>';
}
