function ttClean(m){ var o = {}; if (m && typeof m === 'object') Object.keys(m).forEach(function(k){ if ((k === '*' || ttTabs().indexOf(k) >= 0) && TT_OK[m[k]]) o[k] = m[k]; }); return o; }
