function ttPick(st){ if (!TT_OK[st]) return; if (TT.target === '*') TT.map['*'] = st; else { if (st === (TT.map['*'] || 'paper')) delete TT.map[TT.target]; else TT.map[TT.target] = st; } if (TT.map['*'] === 'paper') delete TT.map['*']; TT.msg = ''; ttApply(); ttRender(); }
function ttReset(k){ delete TT.map[k]; TT.msg = ''; ttApply(); ttRender(); }
function ttAllSame(){ var st = TT.target === '*' ? (TT.map['*'] || 'paper') : ttStyleOf(TT.target); TT.map = st === 'paper' ? {} : { '*': st }; TT.msg = ''; ttApply(); ttRender(); }
