  var nm = function(s){ return (typeof CB_PXN !== 'undefined' && CB_PXN[s]) || s; }, L = I.rows.map(function(r){ return { s: r.s, n: r.n, avg: r.avg, hit: r.hit, base: r.base, ex: r.avg - r.base }; }).sort(function(a, b){ return b.ex - a.ex; });
  var it = function(r, side){ var st = side > 0 ? (r.ex >= 1 && r.avg > 0) : (r.ex <= -1 && r.avg < r.base); return '<div class="qvd-it"><div class="qvd-n"><b>' + esc(nm(r.s)) + '</b><span class="qvd-tag">' + esc(side > 0 ? (st ? T('사기 · 강함', 'Buy · strong') : T('사기 · 상대 우위', 'Buy · relative')) : (st ? T('줄이기 · 강함', 'Trim · strong') : T('줄이기 · 상대 열위', 'Trim · relative'))) + '</span></div>'
    + '<p>' + esc(T('같은 국면 13주 뒤 평균 ', 'avg 13w fwd ') + (r.avg > 0 ? '+' : '') + r.avg.toFixed(2) + T('% (전체 평균 ', '% (all ') + (r.base > 0 ? '+' : '') + r.base.toFixed(2) + T('%) · 오른 비율 ', '%) · up ') + r.hit + '% · ' + r.n + T('주', ' wks')) + '</p></div>'; };
  var buy = L.filter(function(r){ return r.ex > 0; }).slice(0, 2), sell = L.slice().reverse().filter(function(r){ return r.ex < 0; }).slice(0, 2);
  var one = (buy[0] ? T('사기 1순위 ', 'Buy #1 ') + nm(buy[0].s) : '') + (buy[0] && sell[0] ? ' · ' : '') + (sell[0] ? T('줄이기 1순위 ', 'Trim #1 ') + nm(sell[0].s) : '');
  return '<div class="qvd fed-imp"><div class="qvd-h"><span class="qvd-k">' + esc(T('결론', 'BOTTOM LINE')) + '</span><b>' + esc(T('이 국면에서 뭘 살까', 'What to own in this regime')) + '</b><span class="qvd-b">' + esc(T('순유동성 13주 ', 'net liquidity 13w ') + cbEok(I.c13) + T(' (', ' (') + (I.sg > 0 ? T('늘어나는 쪽', 'rising') : T('줄어드는 쪽', 'falling')) + T(') 이던 과거 주들 · ', ') weeks since ') + (I.from || '') + T(' 부터', '')) + '</span></div>'
    + (one ? '<p class="qvd-one">' + esc('→ ' + one) + '</p>' : '')
    + '<div class="qvd-g n2"><div class="qvd-col buy"><h4>' + esc(T('사기 · 비중 늘리기', 'Buy · add')) + '</h4>' + (buy.length ? buy.map(function(r){ return it(r, 1); }).join('') : '<p class="qvd-none">' + esc(T('평소보다 나았던 자산이 없음', 'none')) + '</p>') + '</div>'
    + '<div class="qvd-col sell"><h4>' + esc(T('팔기 · 비중 줄이기', 'Sell · trim')) + '</h4>' + (sell.length ? sell.map(function(r){ return it(r, -1); }).join('') : '<p class="qvd-none">' + esc(T('평소보다 못했던 자산이 없음', 'none')) + '</p>') + '</div></div>'
    + '<p class="qvd-rule"><b>' + esc(T('규칙', 'Rule')) + '</b>' + esc(T('지금과 같은 방향 (순유동성 13주 변화 부호) 이던 주마다 13주 뒤 수익 → 그 평균이 전체 평균보다 큰 순 · 강함 = 1%p 넘게 차이 · 과거 상관이라 인과 · 예측이 아님 (자금흐름 › 연준 심화의 시장 영향 분석과 같은 자료)', 'conditional 13-week forward returns')) + '</p>'
