    + '<div class="v"><b data-lv="lt:' + esc(key) + '" data-tw>' + esc(val) + '</b><span class="c ' + cls + '" data-lv="ltc:' + esc(key) + '">' + esc(mkChg(it.c, it.unit)) + '</span></div>'
