  (MK_FX_OF[cc] || []).forEach(function(f){ var it = mkSnapItem('fx', f); if (it) html += mkLiveTile('f:' + f, it.n, it, { closed: it.cl, tip: it.n + T(' · 전일 종가 대비', ' vs prior close') }); });
