function mkPxMo(px){ return px && px.src === 'imf_m' ? '<i class="mk-mo" title="' + esc(T('IMF 1차 상품 월평균 가격 · ' + (px.d || '') + ' · 전월 대비 (한 달 남짓 늦게 발표)', 'IMF monthly average · m/m')) + '">' + esc(T('월간', 'mo')) + '</i>' : ''; }
