function mkOvTip(p){
  var d = p.data || {};
  if (p.seriesId === 'ovW') return '<b>' + esc(d.name || '') + '</b><br><span style="opacity:.75">' + esc(d.wk === 'canal' ? T('운하 · 배가 땅을 가로질러 지나는 물길', 'Canal') : d.wk === 'strait' ? T('해협 · 배가 지나는 좁은 바다', 'Strait') : T('큰 배가 오가는 강 (내륙 수운)', 'Navigable river')) + '</span>';
  if (p.seriesId === 'ovNode'){
    if (d.kind === 'water') return '<b>' + esc(d.full || d.name || '') + '</b><br><span style="opacity:.75">' + esc(d.wk === 'canal' ? T('운하 · 배가 땅을 가로질러 지나는 물길', 'Canal') : d.wk === 'strait' ? T('해협 · 배가 지나는 좁은 바다', 'Strait') : T('큰 배가 오가는 강 (내륙 수운)', 'Navigable river')) + '</span>';
    if (d.kind === 'ex') return '<b>' + mkFlag2(d.cc) + ' ' + esc(mkNm(d.cc)) + '</b> ' + esc(T('수출', 'exports')) + '<br><b>' + esc(mkUsdKo(d.v)) + '</b> <span style="opacity:.75">' + esc(T('· 지도에 그린 흐름 합', '· sum of drawn flows')) + '</span>';
    if (d.kind === 'im') return '<b>' + mkFlag2(d.cc) + ' ' + esc(mkNm(d.cc)) + '</b> ' + esc(T('수입', 'imports')) + '<br><b>' + esc(mkUsdKo(d.v)) + '</b> <span style="opacity:.75">' + esc(T('· 지도에 그린 흐름 합', '· sum of drawn flows')) + '</span>';
    if (d.kind === 'rs' && typeof mkRsTip === 'function') return mkRsTip(d.cc);
    if (d.kind === 'cp' && typeof mkPortTip === 'function') return mkPortTip(d.id);
    if (d.kind === 'pt' && typeof mkPrtTip === 'function') return mkPrtTip(d.id);
    if (d.kind === 'greg' && typeof mkGfwRegTip === 'function') return mkGfwRegTip(d.id);
    if (d.kind === 'gport' && typeof mkGfwPortTip === 'function') return mkGfwPortTip(d.id);
    if ((d.kind === 'vcA' || d.kind === 'vcB') && typeof mkVcfTip === 'function') return mkVcfTip(d);
    if ((d.kind === 'esrUS' || d.kind === 'esrB') && typeof mkEsrTip === 'function') return mkEsrTip(d);
    return esc(p.name || '');
  }
  if (p.seriesId === 'ovShip' && d.g && typeof mkGfwTip === 'function') return mkGfwTip(d);
  if (mkIsShipSer(p.seriesId) && typeof mkShipTip === 'function') return mkShipTip(d);
  if (d.kind === 'greg' && typeof mkGfwRegTip === 'function') return mkGfwRegTip(d.i != null ? d.i : d.id);
  if (d.kind === 'rs' && typeof mkRsFlowTip === 'function') return mkRsFlowTip(d);
  if (d.kind === 'vcf' && typeof mkVcfTip === 'function') return mkVcfTip(d);
  if (d.kind === 'esr' && typeof mkEsrTip === 'function') return mkEsrTip(d);
  if (d.kind === 'lane') return '<b>' + esc(d.n || '') + '</b><br><span style="opacity:.75">' + esc(T('주요 항로 (모식도)', 'Main lane (schematic)')) + '</span>';
  return mkFlowTip(p);
}
