var MK_PORT_KO = { 1: 'Suez Canal', 2: 'Panama Canal', 3: 'Bosporus', 4: 'Bab el-Mandeb', 5: 'Malacca', 6: 'Hormuz', 7: 'Cape of Good Hope', 8: 'Gibraltar', 9: 'Dover', 10: 'Oresund', 11: 'Taiwan Strait', 12: 'Korea Strait' };
function mkPortLoad(){
  var P = MK.ports || (MK.ports = {}); if (P.d || P.busy) return;
  //  (10/9 4차) 못 받았으면 1분 동안은 다시 안 부름 — 다시 그릴 때마다 부르는 칸(밸류체인 · 개요)이 서버를 계속 두드리지 않게
  if (P.err && Date.now() - (P.errAt || 0) < 60000) return;
  P.busy = true;
  if (typeof edge !== 'function'){ P.busy = false; P.err = 'no edge'; return; }
  edge({ source: 'ports' }).then(function(d){ P.busy = false; if (d && d.cps && d.cps.length){ P.d = d; P.err = ''; } else { P.err = (d && d.error) || T('자료를 받지 못했습니다', 'No data'); P.errAt = Date.now(); } }, function(e){ P.busy = false; P.err = String(e && e.message || e); P.errAt = Date.now(); })
    .then(function(){ if (MK.lay === 'port'){ var bx = $('mkRes'); if (bx) bx.__k = ''; mkResRender(); mkMapPaint(); } if (MK.pops && MK.pops.some(function(q){ return q.id === 'p:all'; })) mkPopsRender(); mkOvMoreRefresh(); if (MK.lay === 'vc'){ var bv = $('mkRes'); if (bv) bv.__k = ''; mkResRender(); } });
}
//  해협 하나 — 최근 7일 · 30일 평균 · 전년 같은 30일 평균 · 전년 대비 · 배 종류 비중
function mkPortStat(cp){
  var s = cp.s, n = s.t.length, avg = function(a, k){ var x = a.slice(Math.max(0, n - k)); return x.length ? x.reduce(function(p, v){ return p + v; }, 0) / x.length : null; };
  var a7 = avg(s.t, 7), a30 = avg(s.t, 30), ly = cp.ly ? cp.ly[0] : null;
  var tk = avg(s.tk, 30), ct = avg(s.ct, 30), db = avg(s.db, 30), tot = a30 || 1, l7 = mkLy7(cp.py, 't');
  return { a7: a7, a30: a30, ly: ly, yoy: ly ? (a30 / ly - 1) * 100 : null, yoy7: ly ? (a7 / ly - 1) * 100 : null, mix: { tk: tk / tot * 100, ct: ct / tot * 100, db: db / tot * 100 }, cap: avg(s.cap, 30),
    l7: l7, yoyL7: l7 ? (a7 / l7 - 1) * 100 : null };
}
/*  (10/12 14차 학회장: ‘물류 전년 30일 평균만 말고 전년 데이터도 볼 수 있게’) — 서버가 1년 전 같은 요일(52주 전) 일별 값을 올해 날짜 줄에 맞춰 붙여 줌 (py)
    · 칸: ‘1년 전 같은 7일’ · 그림: 올해 막대 + 1년 전 7일 평균 선 / ‘1년 전 같은 기간’ 으로 바꾸면 1년 전 막대 + 올해 선  */
function mkLy7(py, k){ var a = py && py[k]; if (!a) return null; var v = a.slice(-7).filter(function(x){ return x != null && isFinite(x); }); return v.length >= 4 ? v.reduce(function(p, q){ return p + q; }, 0) / v.length : null; }
function mkMa7(a){ return (a || []).map(function(v, i){ var w = a.slice(Math.max(0, i - 6), i + 1).filter(function(x){ return x != null && isFinite(x); }); return w.length >= 4 ? Math.round(w.reduce(function(p, q){ return p + q; }, 0) / w.length * 10) / 10 : null; }); }
function mkLyView(k){ MK.portLyV = k === 'ly' ? 'ly' : 'both'; var bx = $('mkRes'); if (bx) bx.__k = ''; mkResRender(); }
