function mkShipTy(ty){ return ty >= 80 && ty <= 89 ? ['tk', T('유조선', 'Tanker')] : ty >= 70 && ty <= 79 ? ['cg', T('화물선', 'Cargo')] : ty >= 60 && ty <= 69 ? ['ps', T('여객선', 'Passenger')] : ty === 31 || ty === 32 || ty === 52 ? ['tg', T('예인선', 'Tug')] : ty === 30 ? ['fs', T('어선', 'Fishing')] : ty ? ['ot', T('기타', 'Other')] : ['un', T('종류 미상', 'Unknown')]; }
