//  목적지 원문 → [한국어 이름 또는 null, 원문 정리] · ‘CNSHA>SGSIN’ 은 마지막 항구 · ‘KR PUS’ · ‘SG SIN’ 도
function mkShipDest(raw){
  var t = String(raw || '').toUpperCase().replace(/[@_]+/g, ' ').trim(); if (!t) return null;
  var last = t.split(/>|=>|->|\bTO\b/).pop().trim() || t, sq = last.replace(/[^A-Z]/g, '');
  var code = /^[A-Z]{5}$/.test(sq) && MK_LOCODE[sq] ? sq : (/^[A-Z]{2} ?[A-Z0-9]{3}\b/.test(last) && MK_LOCODE[last.slice(0, 2) + last.replace(/^[A-Z]{2} ?/, '').slice(0, 3)] ? last.slice(0, 2) + last.replace(/^[A-Z]{2} ?/, '').slice(0, 3) : null);
  if (!code){ var en = Object.keys(MK_PORT_EN).filter(function(k){ return sq.indexOf(k) === 0; })[0]; if (en) code = MK_PORT_EN[en]; }
  return [code ? MK_LOCODE[code] : null, t.slice(0, 30)];
}
