    + (x.yoy7 != null ? '<br><span style="font-weight:700;color:' + mkPortCol(x.yoy7, document.documentElement.getAttribute('data-theme') === 'dark') + '">' + esc(T('전년 같은 때 대비 ', 'vs last year ') + (x.yoy7 > 0 ? '+' : '') + x.yoy7.toFixed(0) + '%') + '</span>' : '')
    + '<br><span style="opacity:.75">' + esc(cp.memo) + '</span><br><span style="opacity:.75">' + esc(T('누르면 확대 · 둘레의 무역선', 'Click: zoom in · trade ships')) + '</span>';
