    + '|' + mkPortMode() + ':' + mkGfwOn() + ':' + (Gf.d ? Gf.d.at : Gf.pend ? 'p' : Gf.err ? 'e' : Gf.busy ? 'b' : '') + ':' + (MK.gfwSel != null ? MK.gfwSel : '') + ':' + (MK.gfwPortSel || '') + ':' + (MK.gfwShow || '')
    + '|' + (MK.portLyV || '') + ':' + (MK.ctrSel || '') + ':' + (MK.ctrK || '') + ':' + (d && d.ctr ? d.ctr.length : 0);
  if (box.__k === key) return;
