  box.classList.remove('is-vc', 'is-mac'); box.classList.add('is-port');
  var top = '<div class="mk-res-top"><span class="mk-drag" id="mkResDrag" title="' + esc(T('끌어서 옮기기 (지도 위 어디든) · 두 번 누르면 제자리', 'Drag to move · double-click to dock')) + '" aria-hidden="true">⋮⋮</span><div class="mk-res-t"><span class="k">' + esc(T('물류', 'Shipping')) + '</span><b>' + esc(gm ? T('주간 분석 (4~5일 전)', 'Weekly analysis (4-5 days lag)') : tab === 'pt' ? T('항구 입항', 'Port calls') : tab === 'ct' ? T('나라별 입항 · 출항 화물', 'Country port calls & cargo') : T('해협 통과량', 'Chokepoint transits')) + '</b></div>'
    + '<span class="mk-res-px"></span><button type="button" class="mk-x" onclick="mkLayerSet(\'mkt\')" aria-label="' + esc(T('시장 지도로', 'Back to markets')) + '" title="' + esc(T('시장 지도로 돌아가기', 'Back to markets')) + '">×</button></div>';
  if (!d && !gm){ box.innerHTML = top + '<div class="mk-wait">' + esc(P.err ? mkErrTxt(P.err) : T('로딩 중…', 'Loading…')) + '</div>'; return; }
