function mkPortTabSet(t){ t = t === 'pt' || t === 'ct' ? t : 'cp'; if (MK.portTab === t) return; MK.portTab = t; mkSavePrefs(); var bx = $('mkRes'); if (bx) bx.__k = ''; mkResRender(); mkLayBarRender(); mkOvPaint(); if (MK.pops && MK.pops.some(function(q){ return q.id === 'p:all'; })) mkPopsRender(); }
