//  ‘약 n일 전’ (UTC 시각 글 → 지금까지)
function mkGfwAgo(iso){ var t = Date.parse(String(iso || '').replace(' ', 'T') + (/Z$/.test(iso || '') || String(iso || '').length <= 10 ? '' : 'Z')); if (!isFinite(t)) return ''; var h = (Date.now() - t) / 3600000; return h < 48 ? Math.max(1, Math.round(h)) + T('시간 전', ' h ago') : Math.round(h / 24) + T('일 전', ' days ago'); }
function mkGfwHrs(h){ return h == null ? T('아직 다시 켜지 않음', 'still off') : h >= 48 ? (Math.round(h / 24 * 10) / 10) + T('일', ' days') : (Math.round(h * 10) / 10) + T('시간', ' h'); }
