function vcLkNameOf(t, L){ var a = L.filter(function(x){ return x[1] === t; })[0]; if (a) return vcLkNm(t, a[2]); var b = L.filter(function(x){ return x[3] === t; })[0]; return vcLkNm(t, b ? b[4] : t); }
