  return '<div class="mk-vcd"><div class="mk-vcd-h"><b>' + esc(T('깊이 보기', 'Deep dive')) + '</b><span class="st-hint">' + esc(T(' · 단계별 집중 · 위험 · 대표 기업 주가 · 물류 · 원자재', ' · concentration · stocks · logistics · inputs')) + '</span></div>'
