function mkVcPerfHtml(V){
  var A = (MK.vcPerf || {})[mkVcPerfKey(V)] || {}, co = mkVcCo(V);
  if (!co.length) return '<div class="mk-vcd-perf"></div>';
  if (!A.d) return '<div class="mk-vcd-perf"><div class="mk-vcd-h2">' + esc(T('단계별 대표 기업 · 주가 흐름', 'Stage leaders · price action')) + '</div><div class="mk-wait">' + esc(A.err ? mkErrTxt(A.err) : T('로딩 중…', 'Loading…')) + '</div></div>';
  var R = A.d.rows || {}, by = {};
  co.forEach(function(c){ var p = R[c.s]; if (!p) return; (by[c.st] || (by[c.st] = { n: c.stn, cs: [] })).cs.push(Object.assign({}, c, p)); });
  var stages = V.st.filter(function(S){ return by[S[0]]; }).map(function(S){ var g = by[S[0]], m3 = g.cs.map(function(c){ return c.r3m; }).filter(function(v){ return v != null; }); return { k: S[0], n: g.n, cs: g.cs, m3: m3.length ? m3.reduce(function(a, b){ return a + b; }, 0) / m3.length : null }; });
  if (!stages.length) return '<div class="mk-vcd-perf"></div>';
  var hot = stages.filter(function(s){ return s.m3 != null; }).sort(function(a, b){ return b.m3 - a.m3; })[0];
  var tbl = stages.map(function(s){ return '<div class="mk-vcd-g"><div class="gh"><b>' + esc(s.n) + '</b>' + (s.m3 != null ? '<span class="' + mkUd(s.m3) + '">' + esc(T('평균 3개월 ', 'avg 3M ') + mkPct(s.m3, 1)) + '</span>' : '') + '</div>'
    + s.cs.map(function(c){ return '<div class="mk-vcd-c"><span class="n">' + esc(c.n) + ' <i>' + esc(c.s) + '</i></span><span class="' + mkUd(c.r1m) + '">' + esc(mkPct(c.r1m, 1)) + '</span><span class="' + mkUd(c.r3m) + '">' + esc(mkPct(c.r3m, 1)) + '</span><span class="' + mkUd(c.ytd) + '">' + esc(mkPct(c.ytd, 1)) + '</span>'
      + (c.sp && c.sp.length > 2 ? mkSpark(c.sp.map(function(v){ return { v: v }; }), 70, 18, 100) : '<span></span>') + '</div>'; }).join('') + '</div>'; }).join('');
  return '<div class="mk-vcd-perf"><div class="mk-vcd-h2">' + esc(T('단계별 대표 기업 · 주가 흐름', 'Stage leaders · price action')) + (hot ? '<span class="hot">' + esc(T('자금 유입이 강한 단계: ', 'Hottest: ') + hot.n + ' ' + mkPct(hot.m3, 1)) + '</span>' : '') + '</div>'
    + '<div class="mk-vcd-ch" id="mkVcdCh"></div>'
    + '<div class="mk-vcd-c h" aria-hidden="true"><span>' + esc(T('기업', 'Company')) + '</span><span>' + esc(T('1개월', '1M')) + '</span><span>' + esc(T('3개월', '3M')) + '</span><span>' + esc(T('연초', 'YTD')) + '</span><span>' + esc(T('60일', '60d')) + '</span></div>'
    + tbl + '<p class="st-hint">' + esc(T('미국 상장(ADR 포함) · 한국 상장 · 일봉 종가 · 단계 평균 = 단순 평균', 'US & KR listings · daily close')) + '</p></div>';
}
function mkVcdDraw(V){
  var el = $('mkVcdCh'), A = (MK.vcPerf || {})[mkVcPerfKey(V)]; if (!el || !A || !A.d || typeof echarts === 'undefined') return;
  var R = A.d.rows || {}, co = mkVcCo(V), by = {};
  co.forEach(function(c){ var p = R[c.s]; if (p && p.r3m != null) (by[c.stn] || (by[c.stn] = [])).push(p.r3m); });
  var ks = Object.keys(by); if (!ks.length){ el.style.display = 'none'; return; }
  var rows = ks.map(function(k){ return [k, by[k].reduce(function(a, b){ return a + b; }, 0) / by[k].length]; }).sort(function(a, b){ return a[1] - b[1]; });
  el.style.height = Math.max(90, rows.length * 26 + 30) + 'px';
  mkVcdChart = chartOn(el, mkVcdChart); if (!mkVcdChart) return;
  var dk = document.documentElement.getAttribute('data-theme') === 'dark';
  mkVcdChart.__axNoKeep = true;
  mkVcdChart.setOption({ animation: MOTION_OK, animationDuration: 800, grid: { left: 6, right: 46, top: 6, bottom: 6, containLabel: true },
    tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' }, valueFormatter: function(v){ return mkPct(v, 1); } },
    xAxis: { type: 'value', axisLabel: { formatter: '{value}%', fontSize: 10 }, splitLine: { lineStyle: { opacity: 0.5 } } },
    yAxis: { type: 'category', data: rows.map(function(r){ return r[0]; }), axisTick: { show: false }, axisLabel: { fontSize: 11 } },
    series: [{ type: 'bar', data: rows.map(function(r){ return { value: +r[1].toFixed(2), itemStyle: { color: r[1] >= 0 ? (dk ? '#ef6b5e' : '#c0392b') : (dk ? '#5b9cf0' : '#1b5fa8'), borderRadius: 3 } }; }), barWidth: 14,
      label: { show: true, position: 'right', formatter: function(p){ return mkPct(p.value, 1); }, fontSize: 10.5 } }] }, true);
}
