function mkResEtfNote(t){ return t === 'imf' ? T('IMF 1차 상품 월평균 가격 · 한 달 남짓 늦게 발표', 'IMF monthly average') : t === 'phys' ? T('실물 보관형 ETF · 현물 값에 가까움', 'physically backed ETF') : t === 'fut' ? T('선물형 ETF · 만기 교체 비용 때문에 현물 · 선물 값과 다를 수 있음', 'futures ETF · roll costs') : T('관련 기업 주식 ETF · 원자재 값과 다를 수 있음', 'equity ETF · differs from commodity price'); }
