  return { last: last, m1: r(21), m3: r(63), ytd: prev ? (last.v / prev.v - 1) * 100 : null, y1: n > 252 ? r(252) : null, hi: hi, lo: lo, pos: hi.v > lo.v ? (last.v - lo.v) / (hi.v - lo.v) * 100 : 50, dd: (last.v / hi.v - 1) * 100 };
