  var sb = mkRateLast(MK_FX_RATE_CODE(rb) + '|M'), sq = mkRateLast(MK_FX_RATE_CODE(rq) + '|M'); if (!sb || !sq) return null;
  var lb = mkRateLast(MK_FX_LONG(rb) + '|M'), lq = mkRateLast(MK_FX_LONG(rq) + '|M'), long = !!(lb && lq);
