         + (candle ? '' : '<span class="dot" style="background:' + pal[i % pal.length] + '"></span>')
         + esc(isEn() ? x.en : x.ko) + ((isEn() ? x.en : x.ko) === x.sym ? '' : ' <span style="opacity:.7">' + esc(x.sym) + '</span>')
