  keys.forEach(function(k){ if (ord[k] == null) ord[k] = 50 + keys.indexOf(k); });
  var E = FL.filter(function(f){ return keys.indexOf(f[0]) >= 0 && keys.indexOf(f[1]) >= 0 && f[0] !== f[1]; }).map(function(f, i){ return { a: f[0], b: f[1], w: f[2], i: i, fw: true }; });
  if (!E.length) return null;
