var VCD_SC = [['GL', '세계', 'Global'], ['US', '미국', 'US'], ['KR', '한국', 'Korea'], ['CN', '중국', 'China'], ['JP', '일본', 'Japan'], ['EU', '유럽', 'Europe']];
