  for (var i = 0; i < n; i++){ var dx = xs[i] - mx, dy = ys[i] - myy; sxx += dx * dx; syy += dy * dy; sxy += dx * dy; }
  if (!sxx || !syy) return null;
  var r = sxy / Math.sqrt(sxx * syy), b = sxy / sxx, t = r * Math.sqrt((n - 2) / Math.max(1e-9, 1 - r * r));
