function flowShow(which){
  //  (15차) 예전 ‘기관 보유 (13F · 국민연금)’ 한 칸 → 13F · 국민연금 두 칸 (예전 길 · 세이피 이동은 13F 로)
  if (which === 'inst') which = (typeof tabVisOk === 'function' && !tabVisOk('fl_f13') && tabVisOk('fl_nps')) ? 'nps' : 'f13';
  flowTab = which;
  ['dark','cong','liq','f13','nps'].forEach(function(k){
    var p = $('flowPane-' + k); if (p) p.classList.toggle('hidden', k !== which);
    var b = $('flowTab-' + k); if (b) b.classList.toggle('on', k === which);
  });
  if (which === 'liq'){ liqInit(); cbLoad(); Object.keys(liqCharts).concat(Object.keys(cbCharts)).forEach(function(id){ var c = liqCharts[id] || cbCharts[id]; if (c) setTimeout(function(){ try { c.resize(); } catch(e){} }, 60); }); }
  if (which === 'dark' && dkChart) setTimeout(function(){ dkChart.resize(); }, 60);
  if (which === 'cong' && !cgRows.length) cgLoad();
  if (which === 'f13'){ if ($('f13Quick') && !$('f13Quick').children.length) f13Quick(); setTimeout(function(){ pfVizResize('f13Viz'); }, 60); }
  if (which === 'nps'){ npsLoad(false); setTimeout(function(){ try { if (npsChart) npsChart.resize(); } catch(e){} pfVizResize('npsViz'); }, 60); }
}
/* ══════════ (10/11 13차 학회장: ‘13F 기관 보유 자금 흐름으로 옮기고 · NPS 보유도 추가’) — 국민연금 국내주식 ══════════
   ① 대량보유 보고 (분기 · 그 분기에 낸 5% 신규 취득 · 1%p 넘는 변동 · 5% 아래로 보고 — 회사마다 직전 보고 대비) ② 국내주식 전체 (연말 · 평가액 · 비중 · 지분율 · 상위 20 막대)
   · 원자료에 종목코드가 없어 종목명으로 · 누르면 재무제표 탭에서 그 이름으로 검색 · 해외(미국) 주식은 아래 13F 의 ‘국민연금’ 단추  */
