  var miss = function(w){ return '<div class="note">' + esc(w) + ' 기록을 아직 받지 못했습니다' + (DEM.err && /does not exist|not find|PGRST202|42883/i.test(DEM.err.tv + DEM.err.ai) ? ' - Supabase 에서 terminal-14차.sql 을 먼저 실행해 주세요.' : '.') + ' <span class="officer-hint">(' + esc((w === '탭 방문' ? DEM.err.tv : DEM.err.ai) || '') + ')</span></div>'; };
  //  ① 탭 방문
