  h += '<div class="tg-sec">보내는 곳 · 알림</div>'
    + '<div class="mode-seg tg-seg"><button class="' + (st.live ? '' : 'on') + '" onclick="tgSet({live:false})">시험 중 (임원진 그룹)</button>'
    + '<button class="' + (st.live ? 'on' : '') + '" onclick="tgSet({live:true})"' + (ch.all ? '' : ' disabled title="학회 전체 채널을 먼저 등록하세요"') + '>학회 전체 채널</button></div>'
    + '<div class="tg-opts">' + [['morning', '아침 브리핑 (화~금 07:00 · 토 주간 요약 · 월 주말 브리핑)'], ['releases', '미국 지표 발표 알림'], ['ops', '오류 알림 (임원진 그룹)'], ['ai_point', '오늘의 포인트 (AI · 숫자 확인 통과할 때만)'], ['alerts', '시장 알림 (10분마다 살핌 · 아래 주제만)']].map(function(o){
        return '<label><input type="checkbox"' + (st[o[0]] ? ' checked' : '') + ' onchange="tgSet({' + o[0] + ':this.checked})"> ' + esc(o[1]) + '</label>'; }).join('') + '</div>';
  //  (18차) 학회 채널로 보낼 시장 알림 주제 (개인 구독은 학회원이 홈 › 세이피 텔레그램에서) · 알림 링크용 터미널 주소
  var TOPS = [['cp', '해협 · 물류'], ['pair', '페어 신호'], ['yc', '일드커브'], ['macro', '지표 쇼크'], ['news', '속보'], ['heat', '시장 급변']];
  var tOn = Array.isArray(st.alert_topics) ? st.alert_topics : TOPS.map(function(t){ return t[0]; });
  h += '<div class="tg-topics' + (st.alerts === false ? ' off' : '') + '" id="tgTopics">' + TOPS.map(function(t){
        return '<label><input type="checkbox" value="' + t[0] + '"' + (tOn.indexOf(t[0]) >= 0 ? ' checked' : '') + (st.alerts === undefined ? ' disabled' : '') + ' onchange="tgTopicsSave()"> ' + esc(t[1]) + '</label>'; }).join('') + '</div>'
    + (st.alerts === undefined ? '<div class="st-hint">시장 알림 설정 칸이 아직 없습니다 · SQL Editor 에서 terminal-텔레그램2.sql 을 돌려 주세요.</div>' : '')
    + (k.url ? '' : '<div class="st-hint">알림 · 리포트 요약에 ‘터미널에서 보기’ 링크를 붙이려면 Supabase Secrets 에 TG_TERMINAL_URL (터미널 주소) 을 넣어 주세요.</div>');
