function tgSay(m, kind){ TG.msg = m || ''; TG.msgK = kind || ''; var e = $('tgMsg'); if (e){ e.textContent = TG.msg; e.className = 'tg-msg' + (TG.msgK ? ' ' + TG.msgK : ''); } }
async function tgAct(body, okMsg){
  tgSay('로딩 중…');
  try { var r = await edgeCall('safey-telegram', body); tgSay(r && r.skipped ? '보내지 못했습니다 · ' + r.skipped : okMsg, r && r.skipped ? 'err' : 'ok'); await tgLoad(true); }
  catch(e){ tgSay(String(e && e.message || e), 'err'); }
}
async function tgSet(p){ p.action = 'settings'; await tgAct(p, '바꿨습니다.'); }
//  (10/11) 초대 링크 받기 → 복사 (한 사람 · 하루 동안 · 봇이 그 방 관리자여야 함)
async function tgInviteBtn(room){
  tgSay('로딩 중…');
  try {
    var r = await edgeCall('safey-telegram', { action: 'invite', room: room }), link = String(r && r.link || '');
    if (!/^https:\/\/t\.me\//.test(link)) throw new Error('초대 링크를 받지 못했습니다.');
    var said = (room === 'ops' ? '임원진 그룹' : '학회 전체 채널') + ' 초대 링크 (한 사람 · 하루): ' + link;
    try { await navigator.clipboard.writeText(link); tgSay(said + ' · 복사했습니다', 'ok'); } catch(e){ tgSay(said, 'ok'); }
  } catch(e){ tgSay(String(e && e.message || e), 'err'); }
}
async function tgCode(){
  tgSay('로딩 중…');
  try { var r = await edgeCall('safey-telegram', { action: 'link_code' }); TG.code = { code: String(r.code), bot: r.bot || '', exp: Date.now() + (Number(r.expires_in) || 600) * 1000 }; tgSay('10분 안에 텔레그램에서 연결해 주세요. 연결한 뒤 ‘새로고침’ 을 누르면 ‘연결됨’ 으로 바뀝니다.', 'ok'); tgRender(); }
  catch(e){ tgSay(String(e && e.message || e), 'err'); }
}

function adTabInit(){
  var v = adForce;
  adForce = null;
  if (!v){ try { v = LSX.getItem(AD_KEY) || 'mt'; } catch(e){ v = 'mt'; } }
  adTab(v);
}

async function loadAdmin(){
  //  (10/6 점검) ‘팀원 배정’ 의 팀 목록은 모의투자 탭을 먼저 열어야만 채워졌습니다 — 설정을 먼저 열어도 채웁니다
  if (!teams.length){
    try {
      var tr = await sb.rpc('my_teams');
      if (!tr.error){
        teams = tr.data || [];
        var opt = teams.map(function(t){ return '<option value="'+t.id+'">'+esc(t.name)+' ('+t.gen+'기)</option>'; }).join('');
        ['assignTeam', 'teamSel'].forEach(function(id){ var e = $(id); if (e && !e.options.length) e.innerHTML = opt; });
      }
    } catch(e){}
  }
  loadAiSpend();
  loadAiViews();
  loadTradableStat();
  adLiveStart();
  loadPresence(); presTick();
  rsInit();
  var s = await sb.from('app_settings').select('current_gen').eq('id',1).maybeSingle();
  if (s.data) $('curGen').value = s.data.current_gen;
  renderIndicatorTable();
  loadMembers(); loadLabels();
}
/*  ── 대회 초기화 ────────────────────────────────────────────

    ⚠️ 되돌릴 수 없습니다. 백업도 안 만듭니다 (학회장 결정). 그래서
       <누르기 전에> 무엇이 몇 건 지워지는지 숫자로 먼저 보여줍니다.
       "매매 214건 · 스냅샷 63일치" 를 보고 나면 실수로 누르는 일이
       확 줄어듭니다.

    ⚠️ 한 팀만 초기화할 때는 대회 시작·종료 시각을 안 건드립니다 —
       한 팀 사고 때문에 전 팀 일정이 바뀌면 안 되니까요. 그래서 팀을
       고르면 날짜 칸을 숨깁니다.

    ⚠️ 진짜 자물쇠는 DB 함수(contest_reset)에 있습니다. 화면은 안내입니다. */
var rsInited = false;
async function rsInit(){
  //  팀 목록을 채웁니다 (한 번만)
  var sel = $('rsTeam');
  if (sel && !rsInited){
    rsInited = true;
    try {
      var r = await sb.from('teams').select('id,name,gen').order('name');
      var g = me && me.current_gen;
      (r.data || []).filter(function(t){ return !g || t.gen === g; })
        .forEach(function(t){
          var o = document.createElement('option');
          o.value = t.id; o.textContent = t.name + ' 만';
          sel.appendChild(o);
        });
    } catch(e){ /* 팀을 못 읽어도 ‘전체’ 로는 됩니다 */ }
    //  기본값: 다음 월요일 09:00 시작 (한국시간)
    var d = new Date(), add = (8 - d.getDay()) % 7 || 7;
    var mon = new Date(d.getFullYear(), d.getMonth(), d.getDate() + add, 9, 0);
    var pad = function(n){ return String(n).padStart(2, '0'); };
    var fmt = function(x){ return x.getFullYear() + '-' + pad(x.getMonth()+1) + '-'
      + pad(x.getDate()) + 'T' + pad(x.getHours()) + ':' + pad(x.getMinutes()); };
    if ($('rsStart') && !$('rsStart').value) $('rsStart').value = fmt(mon);
  }
  rsPreview(); rsLog();
}

function rsScopeTeam(){
  var v = ($('rsTeam') || {}).value;
  return v ? Number(v) : null;
}

async function rsPreview(){
  var box = $('rsPreview'); if (!box) return;
  //  한 팀만 고르면 대회 기간은 안 건드리므로 칸을 숨깁니다
  var one = rsScopeTeam();
  var wr = $('rsWhenRow'); if (wr) wr.style.display = one ? 'none' : '';
  box.textContent = '세는 중…';
  try {
    var r = await sb.rpc('contest_reset_preview', { p_team_id: one });
    if (r.error) throw new Error(errMsg(r.error));
    /*  ⚠️ 마지막 점검에서 찾음: 서버가 빈 답을 주면 ‘전체 NaN팀 에서 지워질 것 —
        매매 0건’ 이 찍혔습니다. <지울 게 0건> 이라는 거짓말이 됩니다 — 초기화
        단추 바로 위 문구라 특히 위험합니다. 못 셌으면 못 셌다고 적습니다.   */
    if (!r.data || typeof r.data !== 'object')
      throw new Error('지워질 양을 세지 못했습니다 (서버가 빈 답을 줬습니다)');
    var d = r.data;
    var names = aiArr(d.team_names);
    box.innerHTML =
        '<b>' + (one ? esc(String(d.scope || ''))
                     : '전체 ' + (isFinite(Number(d.teams)) && d.teams != null ? Number(d.teams) + '팀' : '팀'))
      + '</b> 에서 지워질 것 · '
      + '매매 <b>' + num(d.trades, 0) + '건</b>'
      + ' · 스냅샷 <b>' + num(d.snapshots, 0) + '일치</b>'
      + ' · 배당 <b>' + num(d.dividends, 0) + '건</b>'
      + ' · 자동매매 기록 <b>' + num(d.auto_runs, 0) + '건</b>'
      + ' · 전략 <b>' + num(d.strategies, 0) + '개</b>'
      + (d.first_trade
          ? '<br><span style="opacity:.8">매매 기간 ' + esc(d.first_trade)
            + ' ~ ' + esc(d.last_trade || '') + '</span>' : '')
      + (!one && names.length
          ? '<br><span style="opacity:.8">대상 팀 · ' + esc(names.join(' · ')) + '</span>' : '');
  } catch(e){
    box.innerHTML = '<span style="color:var(--neg)">' + esc(e.message) + '</span>';
  }
}

async function rsRun(){
  var one = rsScopeTeam();
  var seed = Number(($('rsSeed') || {}).value);
  var note = (($('rsNote') || {}).value || '').trim();
  var where = one ? (($('rsTeam').selectedOptions[0] || {}).textContent || '이 팀')
                  : '전체 팀';
  /*  ⚠️ 타이핑 확인은 안 넣습니다 (학회장 결정). 대신 <무엇이 몇 건>
      지워지는지 확인창에 다시 한 번 적습니다 — 숫자를 보고 누르게. */
  var pv = ($('rsPreview') || {}).textContent || '';
  if (!confirm(where + ' 을(를) 초기화합니다.\n\n' + pv
      + '\n\n되돌릴 수 없습니다. 계속할까요?')) return;

  var btn = $('rsGo'); btn.disabled = true; btn.textContent = '초기화 중…';
  $('rsMsg').style.color = 'var(--text-sub)'; $('rsMsg').textContent = '';
  try {
    var args = { p_team_id: one, p_seed: isFinite(seed) && seed > 0 ? seed : null,
                 p_starts: null, p_ends: null, p_note: note || null };
    if (!one){
      //  ⚠️ 화면은 한국시간으로 받습니다. 서버에 보낼 때 시간대를 밝힙니다.
      var s1 = ($('rsStart') || {}).value, s2 = ($('rsEnd') || {}).value;
      if (s1) args.p_starts = s1 + ':00+09:00';
      if (s2) args.p_ends   = s2 + ':00+09:00';
    }
    var r = await sb.rpc('contest_reset', args);
    if (r.error) throw new Error(errMsg(r.error));
    var d = r.data || {}, del = d.deleted || {};
    $('rsMsg').style.color = 'var(--pos)';
    $('rsMsg').innerHTML = '✅ 초기화했습니다 · 팀 ' + num(d.teams, 0) + '개 · '
      + '매매 ' + num(del.trades, 0) + '건 · 스냅샷 ' + num(del.snapshots, 0) + '일치 · '
      + '전략 ' + num(del.strategies, 0) + '개를 지웠습니다.';
    await rsPreview(); await rsLog();
    //  모의투자 화면도 새로 읽게 합니다 (열어둔 채로 초기화했을 수 있습니다)
    try { mtBoard = []; tstate = null; mtAcc = null; } catch(e){}
  } catch(e){
    $('rsMsg').style.color = 'var(--neg)';
    $('rsMsg').textContent = e.message;
  }
  btn.disabled = false; btn.textContent = '초기화 실행';
}

async function rsLog(){
  var t = $('rsTable'); if (!t) return;
  try {
    var r = await sb.rpc('reset_log_list', { p_limit: 20 });
    if (r.error) throw new Error(errMsg(r.error));
    var rows = aiArr(r.data);
    if (!rows.length){
      t.innerHTML = '<tr><td class="empty">아직 초기화한 적이 없습니다.</td></tr>'; return;
    }
    t.innerHTML = '<thead><tr><th style="width:130px">언제</th><th style="width:90px">누가</th>'
      + '<th style="width:110px">범위</th><th>지운 것</th><th>메모</th></tr></thead><tbody>'
      + rows.map(function(x){
          var d = x.deleted || {};
          return '<tr><td class="st-hint">' + esc(String(x.at || '').slice(0, 16).replace('T', ' ')) + '</td>'
            + '<td>' + esc(x.by || '-') + '</td>'
            + '<td>' + esc(x.scope === 'all' ? '전체' : (x.scope || '-')) + '</td>'
            + '<td class="st-hint">매매 ' + num(d.trades, 0) + ' · 스냅샷 ' + num(d.snapshots, 0)
            +   ' · 전략 ' + num(d.strategies, 0) + '</td>'
            + '<td class="st-hint">' + esc(x.note || '') + '</td></tr>';
        }).join('') + '</tbody>';
  } catch(e){
    t.innerHTML = '<tr><td class="empty">' + esc(e.message) + '</td></tr>';
  }
}

/*  ── 지금 누가 켜놨나 ────────────────────────────────────────

    ⚠️ 무엇을 남기나. 브라우저·OS 요약("Chrome · Windows")과, <그 브라우저에
       저장된 임의의 번호> 뿐입니다. IP·위치·화면 크기 같은 지문은 안 씁니다
       (접속 기록과 같은 원칙입니다).

    ⚠️ 왜 임의의 번호가 필요한가. 노트북 두 대가 둘 다 "Chrome · Windows"
       라서, 이 번호가 없으면 <몇 대인지> 를 셀 수가 없습니다. 사람을
       따라다니는 값이 아니고, 브라우저 저장소를 지우면 사라집니다.

    ⚠️ 「자리비움」은 ‘자리에 없다’ 가 아니라 ‘이 화면을 안 보고 있다’ 입니다.
       다른 탭을 보면 신호를 멈춥니다 — 30명이 하루 종일 켜두면 헛되이
       서버를 두드리게 되니까요.                                          */
var PRES_KEY = 'safe_device_id';
function deviceId(){
  try {
    var v = LSX.getItem(PRES_KEY);
    if (!v || v.length < 8){
      v = 'd' + Math.random().toString(36).slice(2, 10)
              + Math.random().toString(36).slice(2, 6);
      LSX.setItem(PRES_KEY, v);
    }
    return v;
  } catch(e){
    /*  저장소를 막아둔 브라우저(사생활 보호 모드 등)도 있습니다.
        그때는 이번 창에서만 쓰는 번호로 갑니다 — 기기 수가 조금
        부풀 수 있지만 화면이 멈추는 것보다 낫습니다.                  */
    if (!window.__devId) window.__devId = 'x' + Math.random().toString(36).slice(2, 12);
    return window.__devId;
  }
}

var presTimer = null, presLoadTimer = null;
async function presencePing(){
  if (!me) return;
  try { await sb.rpc('presence_ping', { p_device_id: deviceId(), p_device: deviceLabel() }); }
  catch(e){ /* 이 SQL 을 아직 안 돌린 곳도 있습니다 — 조용히 넘어갑니다 */ }
}
/*  1분마다 ‘켜져 있다’ 고 알립니다. 화면을 안 보고 있으면 멈춥니다.   */
function presenceStart(){
  if (presTimer) return;
  presencePing();
  presTimer = setInterval(function(){
    if (document.visibilityState === 'visible') presencePing();
  }, 60000);
  document.addEventListener('visibilitychange', function(){
    if (document.visibilityState === 'visible') presencePing();
  });
}

//  설정 탭을 열어두면 30초마다 다시 봅니다 (탭을 닫으면 멈춥니다)
function presTick(){
  if (presLoadTimer){ clearInterval(presLoadTimer); presLoadTimer = null; }
  var on = $('presAuto') && $('presAuto').checked;
  if (!on) return;
  presLoadTimer = setInterval(function(){
    var pane = $('pane-admin');
    if (!pane || pane.classList.contains('hidden')){ clearInterval(presLoadTimer); presLoadTimer = null; return; }
    if (document.visibilityState === 'visible') loadPresence();
  }, 30000);
}

function presDot(st){
  var m = { online:['on','접속 중'], idle:['idle','자리비움'],
            offline:['off','오프라인'], never:['never','접속한 적 없음'] }[st]
        || ['off','오프라인'];
  return '<span class="pres ' + m[0] + '"><i></i>' + m[1] + '</span>';
}
function presAgo(t){
  if (!t) return '-';
  var s = Math.max(0, (Date.now() - Date.parse(t)) / 1000);
  if (s < 60)    return '방금';
  if (s < 3600)  return Math.floor(s / 60) + '분 전';
  if (s < 86400) return Math.floor(s / 3600) + '시간 전';
  return Math.floor(s / 86400) + '일 전';
}

async function loadPresence(){
  var t = $('presTable'); if (!t) return;
  try {
    var r = await sb.rpc('presence_list', { p_minutes: 5 });
    if (r.error) throw new Error(errMsg(r.error));
    var d = r.data || {}, rows = d.rows || [];
    if (!rows.length){
      t.innerHTML = '<tr><td class="empty">아직 기록이 없습니다. '
        + '학회원이 한 번 접속하면 여기에 나옵니다.</td></tr>';
      $('presSum').textContent = ''; return;
    }
    var onN = rows.filter(function(x){ return x.status === 'online'; }).length;
    var idleN = rows.filter(function(x){ return x.status === 'idle'; }).length;
    var devN = rows.reduce(function(a, x){ return a + (Number(x.devices_now) || 0); }, 0);
    $('presSum').innerHTML =
      '<b>' + onN + '명</b>이 켜져 있습니다 (기기 ' + devN + '대)'
      + (idleN ? ' · 자리비움 ' + idleN + '명' : '')
      + ' · 전체 ' + rows.length + '명'
      + ' <span style="opacity:.75">· 최근 ' + Number(d.minutes || 5) + '분 기준</span>';

    t.innerHTML = '<thead><tr><th>이름</th><th style="width:104px">상태</th>'
      + '<th class="num" style="width:78px">지금 기기</th>'
      + '<th class="num" style="width:92px">최근 7일</th>'
      + '<th class="num" style="width:86px" title="최근 7일, 3분 넘게 두 기기가 동시에 켜져 있던 횟수">동시접속</th>'
      + '<th style="width:96px">마지막 활동</th><th>기기</th></tr></thead><tbody>'
      + rows.map(function(x){
          var ovN = Number(x.overlap_7d) || 0;
          var devs = aiArr(x.devices).slice(0, 4).map(function(v){
            return '<span class="pres-dev">' + esc(aiStr(v.device) || '기타') + '</span>'; }).join('');
          return '<tr>'
            + '<td><b>' + esc(x.name || '-') + '</b>'
            +   (x.role === 'officer' ? ' <span class="pres-off">임원</span>' : '')
            +   '<div class="st-hint">' + esc(x.gen || '') + '기</div></td>'
            + '<td>' + presDot(x.status) + '</td>'
            + '<td class="num">' + (Number(x.devices_now) || 0) + '</td>'
            + '<td class="num st-hint">' + (Number(x.devices_7d) || 0) + '</td>'
            + '<td class="num">' + (ovN ? '<span class="ovl-n">' + ovN + '회</span>' : '<span class="st-hint">-</span>') + '</td>'
            + '<td class="st-hint">' + esc(presAgo(x.last_seen)) + '</td>'
            + '<td>' + (devs || '<span class="st-hint">-</span>') + '</td></tr>';
        }).join('') + '</tbody>';
  } catch(e){
    t.innerHTML = '<tr><td class="empty">' + esc(e.message) + '</td></tr>';
    $('presSum').textContent = '';
  }
  loadOverlaps();
}

/*  ── 동시접속 기록 ──────────────────────────────────────────────
    ⚠️ 학회장: ‘두 기기 동시접속을 탐지할 수 있나’ → 위치·IP 없이 기록만.
       서버(presence_ping)가 신호를 받을 때 같은 계정의 다른 기기가 150초 안에
       신호를 보냈으면 한 줄을 남기고, 계속 겹치면 그 줄을 늘려 갑니다.
    ⚠️ 본인이 노트북·휴대폰을 같이 켜 둔 것도 잡힙니다. 그래서 <기기 조합> 을
       앞에 세웁니다 — PC 둘 · 휴대폰 둘만 붉게 칠합니다.
    ⚠️ 3분이 안 된 겹침은 기본으로 숨깁니다. 노트북을 덮고 휴대폰을 켜면
       신호가 잠깐(최대 150초) 겹쳐 보이는데, 그건 동시접속이 아니라 <기기 전환> 입니다.
    ⚠️ 서버가 아는 건 ‘브라우저 저장소가 다른 둘’ 입니다. 한 PC 에서 크롬과 엣지를
       같이 켜거나 시크릿 창을 열어도 둘로 잡힙니다. 그래서 ‘PC 두 대’ 라고 단정하지
       않고 ‘PC 둘’ 이라 쓰고, <OS 가 서로 다를 때만> ‘기기 두 대 확실’ 이라고 적습니다
       (Windows 와 Mac 은 한 기기일 수 없으니까요).                                  */
var OVL_KIND = { pc2:['PC 둘', true], mobile2:['휴대폰 둘', true], mix:['PC + 휴대폰', false] };
//  이름표 ‘브라우저 · OS’ 에서 OS 만 (모르면 '')
function ovlOs(lab){
  var p = String(lab == null ? '' : lab).split(' · ');
  var o = p.length > 1 ? p[p.length - 1].trim() : '';
  return o === '기타' ? '' : o;
}
//  두 기기가 <확실히> 다른 기기인가 = OS 를 둘 다 알고, 서로 다르다
function ovlSure(x){
  var a = ovlOs(x && x.dev_a), b = ovlOs(x && x.dev_b);
  return !!(a && b && a !== b);
}
//  ⚠️ 날짜와 시각을 <둘 다 한국 시간> 으로 뽑습니다. 날짜만 UTC 로 자르면
//     밤 9시 넘은 기록이 ‘하루 전 날짜 + 한국 시각’ 으로 찍힙니다.
function ovlStamp(t){
  var d = new Date(t);
  if (isNaN(d.getTime())) return ['', ''];
  var ps = new Intl.DateTimeFormat('ko-KR', { timeZone:'Asia/Seoul', month:'numeric', day:'numeric',
    hour:'2-digit', minute:'2-digit', hourCycle:'h23' }).formatToParts(d);
  var g = function(k){ var x = ps.filter(function(p){ return p.type === k; })[0]; return x ? x.value : ''; };
  return [g('month') + '월 ' + g('day') + '일', g('hour') + ':' + g('minute')];
}
function ovlWhen(a, b){
  var A = ovlStamp(a), B = ovlStamp(b);
  return A[0] + ' ' + A[1] + ' ~ ' + (A[0] === B[0] ? '' : B[0] + ' ') + B[1];
}
async function loadOverlaps(){
  var t = $('ovlTable'); if (!t) return;
  var showShort = $('ovlShort') && $('ovlShort').checked;
  try {
    var r = await sb.rpc('presence_overlaps', { p_days: 14 });
    if (r.error){
      //  ⚠️ terminal-동시접속.sql 을 아직 안 돌렸으면 함수가 없습니다 — errMsg 는 이걸
      //     ‘terminal-점검.sql 을 돌려 보라’ 로 바꾸므로, <원래 말> 로 먼저 가립니다.
      var raw = String(r.error.message || '') + ' ' + String(r.error.code || '');
      if (/presence_overlaps|schema cache|PGRST202|42883/i.test(raw))
        throw new Error('동시접속 기록을 켜려면 SQL Editor 에서 terminal-동시접속.sql 을 돌려 주세요.');
      throw new Error(errMsg(r.error));
    }
    var d = r.data || {};
    var all = aiArr(d.rows);
    var rows = all.filter(function(x){ return showShort || Number(x.mins) >= 3; });
    var hot = rows.filter(function(x){ return (OVL_KIND[x.kind] || [])[1]; });
    var hotSure = hot.filter(ovlSure).length;
    var dayAgo = Date.now() - 864e5;
    var hot24 = hot.filter(function(x){ return Date.parse(x.last_at) > dayAgo; }).length;
    $('ovlSum').innerHTML = rows.length
      ? rows.length + '건' + (hot.length ? ' · 그중 <b style="color:#c0392b">PC 둘·휴대폰 둘 ' + hot.length + '건</b>'
          + (hotSure ? ' (OS 가 달라 기기 두 대가 확실한 것 ' + hotSure + '건)' : '')
          + (hot24 ? ' · 최근 24시간 ' + hot24 + '건' : '') : '')
        + (!showShort && all.length > rows.length ? ' · 3분 안 된 겹침 ' + (all.length - rows.length) + '건 숨김' : '')
      : '';
    if (!rows.length){
      t.innerHTML = '<tr><td class="empty">최근 14일 동안 ' + (showShort ? '' : '3분 넘게 ')
        + '두 기기에서 동시에 켜진 계정이 없습니다.</td></tr>';
      return;
    }
    t.innerHTML = '<thead><tr><th>이름</th><th style="width:110px">기기 조합</th>'
      + '<th>언제</th><th class="num" style="width:70px">얼마나</th><th>두 기기</th></tr></thead><tbody>'
      + rows.slice(0, 80).map(function(x){
          var k = OVL_KIND[x.kind] || ['기타', false];
          var m = Number(x.mins) || 0;
          return '<tr>'
            + '<td><b>' + esc(x.name || '-') + '</b>'
            +   (x.role === 'officer' ? ' <span class="pres-off">임원</span>' : '')
            +   '<div class="st-hint">' + esc(x.gen || '') + '기</div></td>'
            + '<td><span class="ovl-kind' + (k[1] ? ' hot' : '') + '">' + esc(k[0]) + '</span>'
            +   (k[1] ? '<div class="st-hint" style="font-size:11px;margin-top:2px">'
                  + (ovlSure(x) ? 'OS 가 달라 기기 두 대 확실' : '한 기기의 다른 브라우저·시크릿 창일 수도')
                  + '</div>' : '')
            + '</td>'
            + '<td class="st-hint">' + esc(ovlWhen(x.first_at, x.last_at)) + '</td>'
            + '<td class="num">' + (m < 1 ? '1분 미만' : esc(num(m, 0)) + '분') + '</td>'
            + '<td><span class="pres-dev">' + esc(aiStr(x.dev_a) || '기타') + '</span>'
            +   '<span class="pres-dev">' + esc(aiStr(x.dev_b) || '기타') + '</span></td></tr>';
        }).join('') + '</tbody>';
  } catch(e){
    t.innerHTML = '<tr><td class="empty">' + esc(String((e && e.message) || e)) + '</td></tr>';
    $('ovlSum').textContent = '';
  }
}

async function saveGen(){
  var g = Number($('curGen').value);
  if (!(g > 0)){ $('genMsg').textContent = '올바른 기수를 입력해주세요.'; return; }
  if (!confirm(g+'기로 바꾸면 다른 기수 학회원은 즉시 접속이 끊깁니다. 계속할까요?')) return;
  var r = await sb.from('app_settings').update({ current_gen:g, updated_at:new Date().toISOString() }).eq('id',1);
  $('genMsg').style.color = r.error ? 'var(--danger)' : 'var(--ok)';
  $('genMsg').textContent = r.error ? errMsg(r.error) : '저장했습니다. 현재 활동 기수: '+g+'기';
  if (!r.error) me.current_gen = g;
}
function renderIndicatorTable(){
  var t = $('icTable');
  if (!catalog.length){ t.innerHTML = '<tr><td class="empty">등록된 지표가 없습니다.</td></tr>'; return; }
  t.innerHTML = '<thead><tr><th>출처</th><th>코드</th><th>이름</th><th>단위</th><th>분류</th>'
    + '<th style="width:132px">중요도</th><th></th></tr></thead><tbody>'
    + catalog.map(function(c){
        var n = starOf(c);
        return '<tr><td>'+esc(srcName(c.source, c.code))+'</td>'
          + '<td class="num">'+esc(c.code)+(c.item_code?' / '+esc(c.item_code):'')+'</td>'
          + '<td>'+esc(c.label)+'</td><td>'+esc(c.unit||'-')+'</td><td>'+esc(c.category)+'</td>'
          /*  ⚠️ 임원진이 여기서 바로 바꿉니다. SQL 편집기를 열어야만 바꿀 수
              있으면 아무도 안 바꿉니다. 바꾸면 ‘손으로 정한 것’ 이 되어
              지표 SQL 을 다시 돌려도 안 덮어씁니다.                     */
          + '<td><select onchange="setIndicatorStar('+c.id+',this.value)" '
          +   'style="width:104px" title="발표 때 시장이 얼마나 움직이는가">'
          +   [3,2,1].map(function(k){
                return '<option value="'+k+'"'+(n===k?' selected':'')+'>'
                     + starTxt(k) + '</option>'; }).join('')
          + '</select>'
          + (c.importance_auto === false
              ? '<div class="st-hint" style="font-size:11px">손으로 정함</div>' : '')
          + '</td>'
          + '<td class="num"><button class="xbtn" onclick="delIndicator('+c.id+')">&times;</button></td></tr>'
          /*  ⚠️ 설명은 길어서 칸에 안 들어갑니다. 아래 줄을 통째로 씁니다.
              여기서 못 고치면 SQL 편집기를 열어야 하고, 그러면 아무도 안 고칩니다. */
          + '<tr class="ic-desc"><td></td><td colspan="6">'
          +   '<input type="text" value="' + esc(c.description || '') + '"'
          +     ' placeholder="이 지표가 무엇을 재는지 한 줄로 (화면에서 고르면 여기 뜹니다)"'
          +     ' style="width:100%" onchange="setIndicatorDesc(' + c.id + ',this.value)">'
          + '</td></tr>'
          /*  영문 이름 — 비워 두면 EN 모드에서 사전·자동 번역이 쓰입니다 (placeholder 가 그 값).
              어색하면 여기 적어 두면 그걸 씁니다 (terminal-영문이름.sql 로 칸을 먼저 만들어야 합니다). */
          + '<tr class="ic-desc"><td></td><td colspan="6"><div style="display:flex;gap:6px;align-items:center">'
          +   '<span class="st-hint" style="flex:none">EN</span>'
          +   '<input type="text" value="' + esc(c.label_en || '') + '"'
          +     ' placeholder="' + esc('영문 이름 · 비우면 → ' + (EN_NAMES[enKey(c.source, c.code, c.item_code)] || koToEn(c.label))) + '"'
          +     ' style="flex:1" onchange="setIndicatorEn(' + c.id + ',this.value)">'
          + '</div></td></tr>';
      }).join('') + '</tbody>';
}

/*  임원진이 영문 이름을 적습니다 — EN 모드에서 이 이름이 먼저입니다.          */
async function setIndicatorEn(id, v){
  var t = String(v || '').trim().slice(0, 80);
  var r = await sb.from('indicator_catalog').update({ label_en: t || null }).eq('id', id);
  if (r.error){
    alert(/label_en/.test(String(r.error.message || '')) ? 'terminal-영문이름.sql 을 먼저 실행해야 영문 이름 칸이 생깁니다.' : errMsg(r.error));
    return;
  }
  var c = catalog.filter(function(x){ return Number(x.id) === Number(id); })[0];
  if (c) c.label_en = t || null;
  var k = c ? enKey(c.source, c.code, c.item_code) : null;
  if (k){ if (t) catEn[k] = t; else delete catEn[k]; }
  if (isEn()) applyLang();
}
/*  임원진이 지표 설명을 고칩니다.                                     */
async function setIndicatorDesc(id, v){
  var t = String(v || '').trim().slice(0, 300);
  var r = await sb.from('indicator_catalog')
    .update({ description: t || null }).eq('id', id);
  if (r.error){ alert(errMsg(r.error)); return; }
  var c = catalog.filter(function(x){ return Number(x.id) === Number(id); })[0];
  if (c) c.description = t || null;
  showCatDesc();
}

/*  임원진이 별을 바꿉니다.
    ⚠️ importance_auto 를 false 로 같이 내려서, 나중에 지표 중요도 SQL 을
       다시 돌려도 이 지표만은 안 덮어쓰게 합니다.                       */
async function setIndicatorStar(id, v){
  var n = Math.max(1, Math.min(3, Number(v) || 1));
  var r = await sb.from('indicator_catalog')
    .update({ importance: n, importance_auto: false }).eq('id', id);
  if (r.error){ alert(errMsg(r.error)); return; }
  var c = catalog.filter(function(x){ return Number(x.id) === Number(id); })[0];
  if (c){ c.importance = n; c.importance_auto = false; }
  renderIndicatorTable();
  renderCatalogSel();
}
async function addIndicator(){
  var code = $('icCode').value.trim(), label = $('icLabel').value.trim();
  if (!code || !label){ $('icMsg').textContent = '코드와 이름을 입력해주세요.'; return; }
  var r = await sb.from('indicator_catalog').insert({
    source:$('icSource').value, code:code, item_code:$('icItem').value.trim()||null,
    cycle:$('icCycle').value, label:label, unit:$('icUnit').value.trim()||null,
    category:$('icCat').value.trim()||'기타', sort_order:900 });
  if (r.error){ $('icMsg').style.color='var(--danger)'; $('icMsg').textContent = errMsg(r.error); return; }
  $('icMsg').style.color='var(--ok)'; $('icMsg').textContent='추가했습니다.';
  ['icCode','icItem','icLabel','icUnit'].forEach(function(i){ $(i).value=''; });
  await loadCatalog(); renderIndicatorTable();
}
async function delIndicator(id){
  if (!confirm('이 지표를 목록에서 지우시겠습니까?')) return;
  var r = await sb.from('indicator_catalog').delete().eq('id', id);
  if (r.error){ alert(errMsg(r.error)); return; }
  await loadCatalog(); renderIndicatorTable();
}

/* ══════════ 오류 한글화 ══════════ */
function errMsg(error){
  var m = String(error && (error.message || error) || '');
  if (/row-level security|permission denied|violates row/i.test(m)) return '권한이 없습니다. 임원진에게 문의하거나 다시 로그인해주세요.';
  //  토큰이 낡은 것(절전 뒤)은 갈아 끼우면 되는 일이라 로그아웃시키지 않습니다
  if (/jwt expired|token is expired|exp.*claim/i.test(m)){ if (typeof authRefreshSoon === 'function') authRefreshSoon(); return '로그인 토큰이 낡아 새로 받았습니다 · 방금 누른 것을 한 번 더 눌러주세요.'; }
  if (/JWT|invalid token|refresh token/i.test(m)) return '로그인이 끊겼습니다. 다시 로그인해주세요.';
  if (/Failed to fetch|NetworkError/i.test(m)) return '서버에 연결할 수 없습니다. Supabase 프로젝트가 일시정지되었는지 확인해주세요.';
  if (/does not exist|relation|function/i.test(m))
    return '필요한 SQL 을 아직 실행하지 않았습니다. Supabase SQL 편집기에서 '
         + 'terminal-점검.sql 을 돌리면 무엇이 빠졌는지 알려줍니다.';
  if (/duplicate/i.test(m)) return '이미 등록된 항목입니다.';
  return m;
}

/* ══════════════════════════════════════════════════════════════
   전략 자동매매 (페이퍼)

   서버가 필요 없습니다. 종가 기준이라 지나간 날짜를 나중에
   한꺼번에 재생해도 매일 감시한 것과 결과가 같습니다.
   ══════════════════════════════════════════════════════════════ */

var strat = null, stratList = [], teamMode = 'manual';
var tradeView = 'manual';

/* 직접 매매 / 자동매매 탭 전환. 아래 포트폴리오·성과 카드는 둘 다에서 공통으로 보입니다. */
function tradeTabAuto(){
  if (!strat) loadStrategy();
  if (typeof prevChart !== 'undefined' && prevChart)
    setTimeout(function(){ try { prevChart.resize(); } catch(e){} }, 60);
}

/* ── 지표 계산 ──
   종가만 있는 데이터도 돌아가도록, 고가·저가가 없으면 종가로 대체합니다.
   거래량이 없는 지표는 조건이 성립하지 않은 것으로 처리합니다. */
function _sma(a, n){
  var out = new Array(a.length).fill(null), sum = 0;
  for (var i=0;i<a.length;i++){
    if (a[i] == null){ out[i] = null; continue; }
    sum += a[i];
    if (i >= n) sum -= a[i-n];
    if (i >= n-1) out[i] = sum/n;
  }
  return out;
}
function _ema(a, n){
  var out = new Array(a.length).fill(null), k = 2/(n+1), e = null, sum = 0;
  for (var i=0;i<a.length;i++){
    if (i < n-1){ sum += a[i]; continue; }
    if (i === n-1){ sum += a[i]; e = sum/n; out[i] = e; continue; }
    e = a[i]*k + e*(1-k); out[i] = e;
  }
  return out;
}
function _stdev(a, n){
  var out = new Array(a.length).fill(null);
  for (var i=n-1;i<a.length;i++){
    var m = 0, j;
    for (j=i-n+1;j<=i;j++) m += a[j];
    m /= n;
    var v = 0;
    for (j=i-n+1;j<=i;j++) v += (a[j]-m)*(a[j]-m);
    out[i] = Math.sqrt(v/n);
  }
  return out;
}
function _hh(a, n){ var o=new Array(a.length).fill(null);
  for (var i=n-1;i<a.length;i++){ var m=-Infinity; for(var j=i-n+1;j<=i;j++) if(a[j]>m) m=a[j]; o[i]=m; } return o; }
function _ll(a, n){ var o=new Array(a.length).fill(null);
  for (var i=n-1;i<a.length;i++){ var m=Infinity; for(var j=i-n+1;j<=i;j++) if(a[j]<m) m=a[j]; o[i]=m; } return o; }

function calcSMA(c,n){ return _sma(c,n); }
function calcEMA(c,n){ return _ema(c,n); }

function calcRSI(c, n){
  var out = new Array(c.length).fill(null);
  if (c.length < n+1) return out;
  var g=0, l=0, i;
  for (i=1;i<=n;i++){ var ch=c[i]-c[i-1]; if (ch>0) g+=ch; else l-=ch; }
  g/=n; l/=n;
  out[n] = l===0 ? 100 : 100 - 100/(1 + g/l);
  for (i=n+1;i<c.length;i++){
    var d=c[i]-c[i-1], gg=d>0?d:0, ll=d<0?-d:0;
    g=(g*(n-1)+gg)/n; l=(l*(n-1)+ll)/n;
    out[i] = l===0 ? 100 : 100 - 100/(1 + g/l);
  }
  return out;
}
function calcChange(c, n){
  var out = new Array(c.length).fill(null);
  for (var i=n;i<c.length;i++){ if (c[i-n] > 0) out[i] = (c[i]/c[i-n]-1)*100; }
  return out;
}
/* 이격도 (%) : 종가가 이동평균에서 얼마나 떨어져 있나 */
function calcVsMA(c, ma){
  var out = new Array(c.length).fill(null);
  for (var i=0;i<c.length;i++){ if (ma[i] && ma[i] > 0) out[i] = (c[i]/ma[i]-1)*100; }
  return out;
}
/* MACD 히스토그램 (MACD − 신호선) */
function calcMACDHist(c, fast, slow, sig){
  var ef = _ema(c, fast), es = _ema(c, slow);
  var macd = c.map(function(_,i){ return (ef[i]!=null && es[i]!=null) ? ef[i]-es[i] : null; });
  var valid = macd.filter(function(x){ return x!=null; });
  var sl = _ema(valid, sig);
  var out = new Array(c.length).fill(null), k = 0;
  for (var i=0;i<c.length;i++){
    if (macd[i]==null) continue;
    if (sl[k]!=null) out[i] = macd[i] - sl[k];
    k++;
  }
  return out;
}
function calcMACDLine(c, fast, slow){
  var ef=_ema(c,fast), es=_ema(c,slow);
  return c.map(function(_,i){ return (ef[i]!=null&&es[i]!=null)?ef[i]-es[i]:null; });
}
/* 볼린저 %B (0=하단, 100=상단) 와 밴드폭(%) */
function calcBB(c, n, mult, want){
  var mid=_sma(c,n), sd=_stdev(c,n), out=new Array(c.length).fill(null);
  for (var i=0;i<c.length;i++){
    if (mid[i]==null || sd[i]==null) continue;
    var up=mid[i]+mult*sd[i], lo=mid[i]-mult*sd[i];
    if (want==='pct') out[i] = (up-lo)>0 ? (c[i]-lo)/(up-lo)*100 : null;
    else              out[i] = mid[i]>0 ? (up-lo)/mid[i]*100 : null;
  }
  return out;
}
/* 스토캐스틱 %K */
function calcStochK(h, l, c, n){
  var hh=_hh(h,n), ll=_ll(l,n), out=new Array(c.length).fill(null);
  for (var i=0;i<c.length;i++){
    if (hh[i]==null||ll[i]==null) continue;
    var r = hh[i]-ll[i];
    out[i] = r>0 ? (c[i]-ll[i])/r*100 : 50;
  }
  return out;
}
/* 윌리엄스 %R (-100 ~ 0) */
function calcWillR(h, l, c, n){
  var hh=_hh(h,n), ll=_ll(l,n), out=new Array(c.length).fill(null);
  for (var i=0;i<c.length;i++){
    if (hh[i]==null||ll[i]==null) continue;
    var r = hh[i]-ll[i];
    out[i] = r>0 ? (hh[i]-c[i])/r*-100 : -50;
  }
  return out;
}
/* CCI */
function calcCCI(h, l, c, n){
  var tp = c.map(function(_,i){ return (h[i]+l[i]+c[i])/3; });
  var m = _sma(tp, n), out = new Array(c.length).fill(null);
  for (var i=n-1;i<c.length;i++){
    if (m[i]==null) continue;
    var dev=0;
    for (var j=i-n+1;j<=i;j++) dev += Math.abs(tp[j]-m[i]);
    dev/=n;
    out[i] = dev>0 ? (tp[i]-m[i])/(0.015*dev) : 0;
  }
  return out;
}
/* ATR 비율 (%) — 변동성 크기 */
function calcATRPct(h, l, c, n){
  var tr = new Array(c.length).fill(null), out = new Array(c.length).fill(null);
  for (var i=1;i<c.length;i++){
    tr[i] = Math.max(h[i]-l[i], Math.abs(h[i]-c[i-1]), Math.abs(l[i]-c[i-1]));
  }
  var a=null;
  for (var j=1;j<c.length;j++){
    if (j < n){ continue; }
    if (j === n){
      var s=0; for (var k=1;k<=n;k++) s+=tr[k]; a=s/n;
    } else { a = (a*(n-1)+tr[j])/n; }
    out[j] = c[j]>0 ? a/c[j]*100 : null;
  }
  return out;
}
/* ADX — 추세가 얼마나 강한가 (0~100) */
function calcADX(h, l, c, n){
  var len=c.length, plus=new Array(len).fill(0), minus=new Array(len).fill(0), tr=new Array(len).fill(0);
  for (var i=1;i<len;i++){
    var up=h[i]-h[i-1], dn=l[i-1]-l[i];
    plus[i]  = (up>dn && up>0) ? up : 0;
    minus[i] = (dn>up && dn>0) ? dn : 0;
    tr[i] = Math.max(h[i]-l[i], Math.abs(h[i]-c[i-1]), Math.abs(l[i]-c[i-1]));
  }
  var out=new Array(len).fill(null);
  if (len < n*2+2) return out;
  var sp=0, sm=0, st=0, x;
  for (x=1;x<=n;x++){ sp+=plus[x]; sm+=minus[x]; st+=tr[x]; }
  var dxs=[];
  for (x=n+1;x<len;x++){
    sp = sp - sp/n + plus[x];
    sm = sm - sm/n + minus[x];
    st = st - st/n + tr[x];
    var pdi = st>0 ? sp/st*100 : 0, mdi = st>0 ? sm/st*100 : 0;
    var dx = (pdi+mdi)>0 ? Math.abs(pdi-mdi)/(pdi+mdi)*100 : 0;
    dxs.push({ i:x, dx:dx });
  }
  var adx=null;
  for (var y=0;y<dxs.length;y++){
    if (y < n-1) continue;
    if (y === n-1){ var s2=0; for (var z=0;z<n;z++) s2+=dxs[z].dx; adx=s2/n; }
    else adx = (adx*(n-1)+dxs[y].dx)/n;
    out[dxs[y].i] = adx;
  }
  return out;
}
/* 거래량 비율 (%) — 오늘 거래량 ÷ n일 평균 */
function calcVolRatio(q, n){
  var m=_sma(q,n), out=new Array(q.length).fill(null);
  for (var i=0;i<q.length;i++){ if (m[i] && m[i]>0) out[i] = q[i]/m[i]*100; }
  return out;
}
/* MFI — 거래량을 반영한 RSI */
function calcMFI(h, l, c, q, n){
  var tp=c.map(function(_,i){ return (h[i]+l[i]+c[i])/3; });
  var out=new Array(c.length).fill(null);
  for (var i=n;i<c.length;i++){
    var pos=0, neg=0;
    for (var j=i-n+1;j<=i;j++){
      var mf = tp[j]*q[j];
      if (tp[j] > tp[j-1]) pos += mf; else if (tp[j] < tp[j-1]) neg += mf;
    }
    out[i] = neg===0 ? 100 : 100 - 100/(1 + pos/neg);
  }
  return out;
}
/* 기간 고점·저점 대비 (%) */
function calcVsHigh(c, h, n){
  var hh=_hh(h,n), out=new Array(c.length).fill(null);
  for (var i=0;i<c.length;i++){ if (hh[i]&&hh[i]>0) out[i]=(c[i]/hh[i]-1)*100; }
  return out;
}
function calcVsLow(c, l, n){
  var ll=_ll(l,n), out=new Array(c.length).fill(null);
  for (var i=0;i<c.length;i++){ if (ll[i]&&ll[i]>0) out[i]=(c[i]/ll[i]-1)*100; }
  return out;
}
/* 연속 상승(+) · 하락(−) 일수 */
function calcStreak(c){
  var out=new Array(c.length).fill(null), s=0;
  for (var i=1;i<c.length;i++){
    if (c[i] > c[i-1]) s = s>0 ? s+1 : 1;
    else if (c[i] < c[i-1]) s = s<0 ? s-1 : -1;
    else s = 0;
    out[i]=s;
  }
  return out;
}
/* 연환산 변동성 (%) */
function calcVolatility(c, n){
  var r=new Array(c.length).fill(null), i;
  for (i=1;i<c.length;i++) r[i] = c[i-1]>0 ? c[i]/c[i-1]-1 : 0;
  var out=new Array(c.length).fill(null);
  for (i=n;i<c.length;i++){
    var m=0, j;
    for (j=i-n+1;j<=i;j++) m+=r[j];
    m/=n;
    var v=0;
    for (j=i-n+1;j<=i;j++) v+=(r[j]-m)*(r[j]-m);
    out[i] = Math.sqrt(v/n)*Math.sqrt(252)*100;
  }
  return out;
}

/* ══ 지표 사전 ══
   cmp:'num'   → 부등호 + 숫자 비교
   cmp:'cross' → 골든크로스 / 데드크로스
   needs: 'hl'(고가·저가) 'vol'(거래량) — 데이터가 없으면 조건이 성립하지 않습니다 */
var IND_SPEC = {
  // ── 모멘텀 ──
  RSI:       { cat:'모멘텀', label:'RSI (상대강도)',           p1:'기간', d1:14, cmp:'num', dv:30, unit:'0~100' },
  STOCH:     { cat:'모멘텀', label:'스토캐스틱 %K',            p1:'기간', d1:14, cmp:'num', dv:20, unit:'0~100', needs:'hl' },
  WILLR:     { cat:'모멘텀', label:'윌리엄스 %R',              p1:'기간', d1:14, cmp:'num', dv:-80, unit:'-100~0', needs:'hl' },
  CCI:       { cat:'모멘텀', label:'CCI',                      p1:'기간', d1:20, cmp:'num', dv:-100, unit:'±100 기준' },
  MFI:       { cat:'모멘텀', label:'MFI (거래량 RSI)',         p1:'기간', d1:14, cmp:'num', dv:20, unit:'0~100', needs:'vol' },
  CHANGE:    { cat:'모멘텀', label:'기간 변동률',              p1:'기간', d1:5,  cmp:'num', dv:-10, unit:'%' },
  STREAK:    { cat:'모멘텀', label:'연속 상승/하락일',         cmp:'num', dv:-3, unit:'일 (음수=하락)' },

  // ── 추세 ──
  VS_SMA:    { cat:'추세',   label:'이동평균 이격도 (SMA)',    p1:'기간', d1:20, cmp:'num', dv:-7, unit:'%' },
  VS_EMA:    { cat:'추세',   label:'이동평균 이격도 (EMA)',    p1:'기간', d1:20, cmp:'num', dv:-7, unit:'%' },
  CROSS:     { cat:'추세',   label:'이동평균 교차 (SMA)',      p1:'단기', d1:5,  p2:'장기', d2:20, cmp:'cross' },
  EMA_CROSS: { cat:'추세',   label:'이동평균 교차 (EMA)',      p1:'단기', d1:12, p2:'장기', d2:26, cmp:'cross' },
  MACD:      { cat:'추세',   label:'MACD 히스토그램',          p1:'단기', d1:12, p2:'장기', d2:26, cmp:'num', dv:0, unit:'0 위=상승' },
  MACD_CROSS:{ cat:'추세',   label:'MACD 신호선 교차',         p1:'단기', d1:12, p2:'장기', d2:26, cmp:'cross' },
  ADX:       { cat:'추세',   label:'ADX (추세 강도)',          p1:'기간', d1:14, cmp:'num', dv:25, unit:'25↑ 추세장', needs:'hl', warm:2 },

  // ── 변동성 ──
  BB_PCT:    { cat:'변동성', label:'볼린저 %B',                p1:'기간', d1:20, cmp:'num', dv:0,  unit:'0=하단 100=상단' },
  BB_WIDTH:  { cat:'변동성', label:'볼린저 밴드폭',            p1:'기간', d1:20, cmp:'num', dv:10, unit:'%' },
  ATR_PCT:   { cat:'변동성', label:'ATR 비율',                 p1:'기간', d1:14, cmp:'num', dv:3,  unit:'%', needs:'hl' },
  VOLAT:     { cat:'변동성', label:'연환산 변동성',            p1:'기간', d1:20, cmp:'num', dv:40, unit:'%' },

  // ── 거래량 · 위치 ──
  VOL_RATIO: { cat:'거래량', label:'거래량 비율 (평균 대비)',  p1:'기간', d1:20, cmp:'num', dv:200, unit:'%', needs:'vol' },
  VS_HIGH:   { cat:'위치',   label:'기간 고점 대비',           p1:'기간', d1:252, cmp:'num', dv:-20, unit:'%', needs:'hl' },
  VS_LOW:    { cat:'위치',   label:'기간 저점 대비',           p1:'기간', d1:252, cmp:'num', dv:10,  unit:'%', needs:'hl' }
};

function specOf(ind){ return IND_SPEC[ind] || IND_SPEC.RSI; }
/*  ── 기간을 얼마까지 넣을 수 있나 ────────────────────────────

    ⚠️ 화면에서는 기간을 500 까지 넣을 수 있었습니다. 그런데 자동매매가
       종목당 받아오는 봉은 정해져 있어서, 그보다 긴 기간을 넣으면
       지표 값이 <아예 안 나오고>, 조건이 영영 성립하지 않습니다.
       오류도 안 나고 경고도 없이 그냥 아무것도 안 삽니다.

       특히 「기간 고점 대비」·「기간 저점 대비」는 <기본값이 252> 라,
       손도 안 대고 그대로 쓰면 안 되는 상태였습니다.

    ADX 는 평활을 두 번 하느라 기간의 두 배가 필요합니다 (warm:2).       */
var MT_BARS_UI = 300;                 //  서버의 MT_BARS 와 같은 값
function maxPeriod(ind){
  var sp = specOf(ind);
  return Math.max(2, Math.floor((MT_BARS_UI - 20) / (sp.warm || 1)));
}

function ruleKey(r){ return r.ind + '|' + (r.period||0) + '|' + (r.period2||0); }

/* 규칙이 필요로 하는 지표들을 한 번씩만 계산해 둡니다 */
function buildCtx(pts, rules){
  var c = pts.map(function(p){ return Number(p.v); });
  var hasHL  = pts.some(function(p){ return Number.isFinite(p.h) && Number.isFinite(p.l) && p.h !== p.l; });
  var hasVol = pts.some(function(p){ return Number.isFinite(p.q) && p.q > 0; });
  var h = pts.map(function(p,i){ return Number.isFinite(p.h) ? Number(p.h) : c[i]; });
  var l = pts.map(function(p,i){ return Number.isFinite(p.l) ? Number(p.l) : c[i]; });
  var q = pts.map(function(p){ return Number.isFinite(p.q) ? Number(p.q) : 0; });

  var ctx = { close:c, high:h, low:l, vol:q, hasHL:hasHL, hasVol:hasVol, s:{} };

  rules.forEach(function(r){
    var key = ruleKey(r), n = Number(r.period)||14, n2 = Number(r.period2)||26;
    if (ctx.s[key]) return;
    var sp = specOf(r.ind);
    if (sp.needs === 'hl'  && !hasHL)  { ctx.s[key] = null; return; }
    if (sp.needs === 'vol' && !hasVol) { ctx.s[key] = null; return; }

    switch (r.ind){
      case 'RSI':        ctx.s[key] = calcRSI(c,n); break;
      case 'STOCH':      ctx.s[key] = calcStochK(h,l,c,n); break;
      case 'WILLR':      ctx.s[key] = calcWillR(h,l,c,n); break;
      case 'CCI':        ctx.s[key] = calcCCI(h,l,c,n); break;
      case 'MFI':        ctx.s[key] = calcMFI(h,l,c,q,n); break;
      case 'CHANGE':     ctx.s[key] = calcChange(c,n); break;
      case 'STREAK':     ctx.s[key] = calcStreak(c); break;
      case 'VS_SMA':     ctx.s[key] = calcVsMA(c, calcSMA(c,n)); break;
      case 'VS_EMA':     ctx.s[key] = calcVsMA(c, calcEMA(c,n)); break;
      case 'MACD':       ctx.s[key] = calcMACDHist(c,n,n2,9); break;
      case 'BB_PCT':     ctx.s[key] = calcBB(c,n,2,'pct'); break;
      case 'BB_WIDTH':   ctx.s[key] = calcBB(c,n,2,'width'); break;
      case 'ATR_PCT':    ctx.s[key] = calcATRPct(h,l,c,n); break;
      case 'VOLAT':      ctx.s[key] = calcVolatility(c,n); break;
      case 'ADX':        ctx.s[key] = calcADX(h,l,c,n); break;
      case 'VOL_RATIO':  ctx.s[key] = calcVolRatio(q,n); break;
      case 'VS_HIGH':    ctx.s[key] = calcVsHigh(c,h,n); break;
      case 'VS_LOW':     ctx.s[key] = calcVsLow(c,l,n); break;
      case 'CROSS':      ctx.s[key] = { a: calcSMA(c,n), b: calcSMA(c,n2) }; break;
      case 'EMA_CROSS':  ctx.s[key] = { a: calcEMA(c,n), b: calcEMA(c,n2) }; break;
      case 'MACD_CROSS': {
        var line = calcMACDLine(c,n,n2);
        var valid = line.filter(function(x){ return x!=null; });
        var sig = calcEMA(valid, 9);
        var sigFull = new Array(c.length).fill(null), k = 0;
        for (var i=0;i<c.length;i++){ if (line[i]==null) continue; sigFull[i] = sig[k]; k++; }
        ctx.s[key] = { a: line, b: sigFull };
        break;
      }
      default: ctx.s[key] = null;
    }
  });
  return ctx;
}

/* 조건 하나를 그날 판정 */
function testRule(rule, ctx, i){
  var arr = ctx.s[ruleKey(rule)];
  if (!arr) return false;

  if (specOf(rule.ind).cmp === 'cross'){
    if (i < 1 || !arr.a || !arr.b) return false;
    var a0=arr.a[i-1], b0=arr.b[i-1], a1=arr.a[i], b1=arr.b[i];
    if (a0==null||b0==null||a1==null||b1==null) return false;
    /*  ⚠️ 예전에는 ‘'dead' 가 아니면 전부 골든크로스’ 였습니다. 오타 하나,
        예전 견본의 'down' 하나가 <반대 뜻으로 조용히 통과> 합니다.
        모르는 값은 <아무것도 아니라고> 해야 합니다.
        (예전 저장분 'up'·'down' 은 그대로 알아듣습니다)
        ⚠️ 서버(edge-market-data.ts)와 <글자 하나까지> 같아야 합니다      */
    var op = String(rule.op || '');
    if (op === 'dead' || op === 'down')   return a0 >= b0 && a1 < b1;
    if (op === 'golden' || op === 'up')   return a0 <= b0 && a1 > b1;
    return false;
  }

  var v = arr[i];
  if (v == null || !isFinite(v)) return false;
  var t = Number(rule.value);
  if (rule.op === '<')  return v <  t;
  if (rule.op === '<=') return v <= t;
  if (rule.op === '>')  return v >  t;
  if (rule.op === '>=') return v >= t;
  return false;
}

/*  ── 자동매매가 실제로 손댈 수 있는 시장 ─────────────────────

    ⚠️ 국내 주식은 무료 실시간 창구가 없어 <서버 자동매매에서 빠져> 있습니다
       (모의투자 화면에도 그렇게 적어 뒀습니다). 그런데 백테스트는 국내까지
       사고팔았습니다. 그래서 "미리 돌려보기에서 가온전선이 수익의 14% 를
       냈다" 같은, 실제로는 절대 일어날 수 없는 결과가 나왔습니다.

       백테스트는 <실제로 일어날 수 있는 일> 만 보여줘야 합니다. 두 엔진이
       같은 이 함수를 봅니다 — 한쪽만 고치면 engine_same41 에서 걸립니다.
       (국내 주식을 직접 매매하는 것은 그대로 됩니다. 자동매매만 빠집니다.) */
function autoTradable(market){
  return String(market || '').toUpperCase() !== 'KR';
}

/*  ── 자리보다 후보가 많을 때 누구를 사는가 ─────────────────────

    ⚠️ 예전에는 <명단에 먼저 나온 것> 부터 담았습니다. 명단이 시장 이름
       순(CRYPTO → KR → US)이라 코인이 다섯 자리를 다 채우고 미국 주식은
       차례가 오지 않았습니다. 90일 백테스트를 돌리면 미국 종목이 한 건도
       안 나왔습니다 — 조건이 안 맞아서가 아니라 <줄을 못 서서> 입니다.

    두 가지로 고칩니다.
      ① 조건을 <얼마나 넉넉히> 만족했는지 점수를 냅니다.
         RSI 45 이하가 조건이면 RSI 20 이 RSI 44 보다 강한 신호입니다.
      ② 시장을 번갈아 가며 각 시장의 1등부터 담습니다.
         어느 시장도 굶지 않고, 왜 그걸 샀는지 설명할 수 있습니다.       */
function ruleMargin(rule, ctx, i){
  var arr = ctx.s[ruleKey(rule)];
  if (!arr) return 0;
  if (specOf(rule.ind).cmp === 'cross'){
    //  교차에는 '얼마나' 가 없습니다. 두 선이 벌어진 폭으로 셉니다.
    if (i < 1 || !arr.a || !arr.b) return 0;
    var a1 = arr.a[i], b1 = arr.b[i];
    if (a1 == null || b1 == null || !isFinite(a1) || !isFinite(b1) || !b1) return 0;
    return Math.abs(a1 - b1) / Math.abs(b1);
  }
  var v = arr[i];
  if (v == null || !isFinite(v)) return 0;
  var t = Number(rule.value);
  var d = (rule.op === '<' || rule.op === '<=') ? (t - v) : (v - t);
  //  기준값이 0 인 지표가 있어서 (0 기준 확산지수 등) 그때는 값으로 나눕니다
  var base = Math.abs(t) > 1e-9 ? Math.abs(t) : Math.max(1e-9, Math.abs(v));
  return d > 0 ? d / base : 0;
}
function ruleScore(rules, ctx, i){
  if (!rules || !rules.length) return 0;
  var s = 0;
  for (var r = 0; r < rules.length; r++) s += ruleMargin(rules[r], ctx, i);
  return s / rules.length;
}
/*  cands = [{ market, symbol, score, ... }] · room = 남은 자리
    같은 값을 넣으면 언제나 같은 답이 나와야 합니다 (백테스트와 실제가
    어긋나면 안 되니까요). 그래서 점수가 같으면 종목 이름으로 줄 세웁니다. */
function rankPicks(cands, room){
  function better(a, b){
    if (b.score !== a.score) return b.score - a.score;
    return String(a.symbol) < String(b.symbol) ? -1
         : String(a.symbol) > String(b.symbol) ? 1 : 0;
  }
  var list = (cands || []).slice().sort(better);
  if (!(room > 0)) return [];

  var by = {}, order = [];
  list.forEach(function(c){
    var m = String(c.market || '');
    if (!by[m]){ by[m] = []; order.push(m); }
    by[m].push(c);
  });
  order.sort();

  /*  자리가 시장 수보다 적으면 <번갈아> 가 성립하지 않습니다. 자리가
      하나뿐인데 순서대로 돌리면 늘 앞 시장(CRYPTO)만 삽니다. 그럴 때는
      시장을 가리지 않고 <가장 강한 신호> 를 삽니다 — 한 자리라면
      그게 맞습니다.                                                    */
  if (room < order.length) return list.slice(0, room);

  //  ① 먼저 시장마다 한 자리씩 — 어느 시장도 굶지 않게
  var out = [], taken = {};
  order.forEach(function(m){
    if (out.length >= room) return;
    var c = by[m][0];
    if (c){ out.push(c); taken[m + '|' + c.symbol] = 1; }
  });
  //  ② 남은 자리는 시장을 가리지 않고 점수가 높은 것부터
  for (var i = 0; i < list.length && out.length < room; i++){
    var x = list[i];
    if (taken[x.market + '|' + x.symbol]) continue;
    taken[x.market + '|' + x.symbol] = 1;
    out.push(x);
  }
  return out;
}

/* ── 전략 재생 ──
   날짜 순서대로 하루씩 진행하면서 모든 종목을 함께 처리합니다.
   현금을 한 곳에서 관리하므로 없는 돈으로 사는 일이 없습니다. */
/* ── 전략 재생용 환율 ──
   미국 종목은 그날 환율로 원화 환산해야 현금·평가액이 맞습니다. */
var fxPts = [], fxDates = [], fxFixed = null;

/* 학회가 정한 고정 환율을 먼저 확인합니다.
   설정돼 있으면 매매일·평가일 모두 같은 값을 써서
   대회 성적이 환율 등락에 흔들리지 않습니다. */
async function loadFxFixed(){
  try {
    var r = await sb.rpc('fx_status');
    var v = r.data && r.data.fixed;
    fxFixed = (v != null && Number(v) > 0) ? Number(v) : null;
  } catch(e){ fxFixed = null; }
  return fxFixed;
}

async function loadFxSeries(start){
  await loadFxFixed();
  if (fxFixed) return 1;                    // 고정 환율이면 시세를 받을 필요가 없습니다
  try {
    var d = await edge({ source:'fred', code:'DEXKOUS', cycle:'D', start: start });
    fxPts = (d.points || []).filter(function(p){ return isFinite(p.v) && p.v > 0; });
  } catch(e){ fxPts = []; }
  fxDates = fxPts.map(function(p){ return p.d; });
  return fxPts.length;
}

/* 달러로 매겨지는 시장 — 미국 주식과 코인 */
function isUsd(market){ return market === 'US' || market === 'CRYPTO'; }

/* 코인은 0.001 BTC 처럼 쪼개서 삽니다.
   주식은 한 주 단위라 내림, 코인은 소수점 8자리까지 허용합니다. */
function isFractional(market){ return market === 'CRYPTO'; }
function roundQty(q, market){
  if (!isFractional(market)) return Math.floor(q);
  return Math.floor(q * 1e8) / 1e8;
}
function quoteSource(market){
  return market === 'KR' ? 'quote_kr' : (market === 'CRYPTO' ? 'quote_crypto' : 'quote_us');
}
function marketLabel(market){
  return market === 'KR' ? '국내' : (market === 'CRYPTO' ? '코인' : '미국');
}

function fxAt(day, market){
  if (!isUsd(market)) return 1;
  if (fxFixed) return fxFixed;
  if (!fxPts.length) return null;
  var j = idxAtOrBefore(fxDates, day);
  return fxPts[j < 0 ? 0 : j].v;
}

/* ══════════ 전략 재생 엔진 ══════════

   두 가지 방식을 지원합니다.
     지정 종목  — 내가 고른 몇 종목만 매일 검사
     유니버스 스캔 — 학회가 정한 전 종목을 매일 훑어 조건에 맞는 것을 매수

   매도는 세 가지 중 하나라도 걸리면 실행됩니다.
     손절(평단 대비 −N%) · 익절(평단 대비 +N%) · 지표 조건
   손절과 익절은 전량, 지표 조건은 설정한 비율만큼 팝니다.

   손매매(직접 매매)가 있으면 그만큼 현금이 줄어든 상태에서 자동매매가 돌아갑니다. */

function replayStrategy(strategies, priceMap, seed, startDate, manualTrades){
  var trades = [];
  var keys = Object.keys(priceMap);
  if (!keys.length) return trades;

  // 지표를 미리 계산해 두기 위해 모든 규칙을 모읍니다
  var allRules = [];
  strategies.forEach(function(st){
    (st.config.buy  || []).forEach(function(r){ allRules.push(r); });
    (st.config.sell || []).forEach(function(r){ allRules.push(r); });
  });

  var book = {}, dateSet = {};
  keys.forEach(function(k){
    //  서버 자동매매가 못 만지는 시장은 백테스트에서도 안 만집니다
    if (!autoTradable(k.split('|')[0])){ book[k] = null; return; }
    var all = priceMap[k] || [];
    var win = all.filter(function(p){ return p.d >= startDate; });
    if (win.length < 30){ book[k] = null; return; }        // 자료가 짧으면 제외

    /*  ⚠️ 지표는 <창 앞의 자료까지> 넣고 계산해야 합니다.

        예전에는 창 안(90일 = 거래일 62개)만 잘라 넣었습니다. 그러면
        RSI 80 은 83봉이 필요하니 <값이 아예 안 나오고>, 그 조건은 영영
        성립하지 않습니다. "RSI 80 이 65보다 크면 매도" 를 걸어둔 전략이
        백테스트에서 그 조건으로는 <한 번도 안 팔았습니다> — 손절·익절만
        걸렸습니다. 오류도 경고도 없이 조용히요.

        RSI 20 처럼 짧은 것도 마찬가지입니다. 창 앞 20일이 없으니 백테스트
        앞부분이 통째로 눈을 감고 시작합니다.

        gatherPrices 는 이미 창 앞 자료까지 받아옵니다. 버리지 말고 씁니다.
        <계산> 은 전체로, <매매> 는 창 안에서만 합니다.                  */
    var pts = all;
    var idx = {};
    pts.forEach(function(p, i){ idx[p.d] = i; });
    win.forEach(function(p){ dateSet[p.d] = 1; });
    book[k] = { pts:pts, ctx:buildCtx(pts, allRules), idx:idx,
                qty:0, spent:0, buys:0, lastAct:-999,
                market:k.split('|')[0], symbol:k.split('|')[1],
                name:(priceMap[k][0] && priceMap[k][0].n) || k.split('|')[1] };
  });

  // 손매매도 같은 시간축 위에서 현금에 반영합니다
  var manual = (manualTrades || []).slice()
    .filter(function(t){ return t.traded_on >= dayOf(startDate); })
    .sort(function(a,b){ return a.traded_on.localeCompare(b.traded_on); });
  manual.forEach(function(t){ dateSet[t.traded_on] = 1; });

  var days = Object.keys(dateSet).sort();
  var cash = seed, mi = 0;

  days.forEach(function(day, dayNo){

    // 0) 그날의 손매매를 먼저 반영 — 남은 현금이 자동매매의 상한이 됩니다
    while (mi < manual.length && manual[mi].traded_on <= dayOf(day)){
      var mt = manual[mi];
      var amt = Number(mt.qty) * Number(mt.price) * Number(mt.fx || 1);
      cash += (mt.side === 'buy' ? -amt : amt);
      mi++;
    }

    // 이 날짜에 유효한 전략
    var st = null;
    for (var k2 = 0; k2 < strategies.length; k2++){
      if (strategies[k2].effective_from <= day) st = strategies[k2];
    }
    if (!st) return;
    var cfg = st.config || {};

    var scan      = cfg.mode === 'scan';
    var buyRules  = cfg.buy  || [];
    var sellRules = cfg.sell || [];
    var buyPct    = Number(cfg.buy_pct  != null ? cfg.buy_pct  : 100)/100;
    var sellPct   = Number(cfg.sell_pct != null ? cfg.sell_pct : 100)/100;
    var cool      = Number(cfg.cooldown || 0);
    var tp        = Number(cfg.tp_pct || 0);
    var sl        = Number(cfg.sl_pct || 0);
    var autoCap   = seed * (Number(cfg.auto_budget_pct != null ? cfg.auto_budget_pct : 100)/100);
    var maxPos    = scan ? Math.max(1, Number(cfg.max_positions || 5)) : 9999;
    var perPct    = scan ? Math.max(1, Number(cfg.per_position_pct || 20))/100 : 0;

    // ── 1) 매도 : 손절 · 익절 · 지표 조건 ──
    keys.forEach(function(k){
      var b = book[k]; if (!b || b.qty <= 0) return;
      var i = b.idx[day]; if (i == null || i < 1) return;
      var rate = fxAt(day, b.market); if (rate == null) return;

      var price = b.pts[i].v;
      var cur   = price * rate;
      var avg   = b.qty > 0 ? b.spent / b.qty : 0;

      var hitSl   = sl > 0 && avg > 0 && cur <= avg * (1 - sl/100);
      var hitTp   = tp > 0 && avg > 0 && cur >= avg * (1 + tp/100);
      var hitRule = sellRules.length > 0 && (dayNo - b.lastAct) > cool
                    && sellRules.some(function(r){ return testRule(r, b.ctx, i); });
      if (!hitSl && !hitTp && !hitRule) return;

      // 손절·익절은 전량, 지표 조건은 설정 비율
      var sq = (hitSl || hitTp) ? b.qty : roundQty(b.qty * sellPct, b.market);
      if (sq <= 0) return;

      trades.push({ market:b.market, symbol:b.symbol, name:b.name,
                    side:'sell', qty:sq, price:price, fx:rate, traded_on:day,
                    reason: hitSl ? '손절' : (hitTp ? '익절' : '조건') });

      var keep = (b.qty - sq) / b.qty;
      b.spent = Math.max(0, b.spent * keep);
      b.buys  = Math.round(b.buys * keep);
      b.qty  -= sq;
      cash   += sq * price * rate;
      b.lastAct = dayNo;
    });

    // ── 2) 매수 ──
    var held = 0, autoSpent = 0;
    keys.forEach(function(k){
      var b = book[k]; if (!b) return;
      if (b.qty > 0) held++;
      autoSpent += b.spent;
    });

    var candidates = scan
      ? keys.filter(function(k){ return book[k] && book[k].qty <= 0; })   // 스캔: 새 종목만
      : keys;

    /*  ⚠️ 스캔 모드에서 이 목록을 <그냥 순서대로> 훑으면 안 됩니다.

        키가 'CRYPTO|…' · 'KR|…' · 'US|…' 라서 사실상 시장 이름 순입니다.
        먼저 나온 것부터 담으면 코인이 최대 보유 종목 수를 다 채우고
        미국 주식은 조건을 만족해도 영영 차례가 오지 않습니다. 실제로
        90일 백테스트에서 미국 종목이 한 건도 안 나왔습니다.

        오늘 조건에 맞는 것을 <전부> 모아 점수를 매기고, 시장을 번갈아
        가며 각 시장의 1등부터 담습니다. 서버(실제 자동매매)도 같은
        rankPicks 를 씁니다 — 어긋나면 engine_same41 에서 걸립니다.      */
    if (scan){
      var pass = [];
      candidates.forEach(function(k){
        var b = book[k]; if (!b) return;
        var i0 = b.idx[day]; if (i0 == null || i0 < 1) return;
        if ((dayNo - b.lastAct) <= cool) return;
        if (!buyRules.length) return;
        if (!buyRules.every(function(r){ return testRule(r, b.ctx, i0); })) return;
        pass.push({ market:b.market, symbol:b.symbol, key:k,
                    score: ruleScore(buyRules, b.ctx, i0) });
      });
      candidates = rankPicks(pass, Math.max(0, maxPos - held))
                     .map(function(c){ return c.key; });
    }

    candidates.forEach(function(k){
      var b = book[k]; if (!b) return;
      if (!buyRules.length) return;
      if (scan && held >= maxPos) return;
      var i = b.idx[day]; if (i == null || i < 1) return;
      if ((dayNo - b.lastAct) <= cool) return;

      var budget;
      if (scan){
        budget = autoCap * perPct;
      } else {
        var my = (cfg.symbols || []).filter(function(x){
          return x.market === b.market && x.symbol === b.symbol; })[0];
        if (!my) return;
        budget = autoCap * (Number(my.alloc || 0)/100);
      }
      if (!(budget > 0)) return;

      var maxTranches = Math.max(1, Math.round(1 / Math.max(buyPct, 0.01)));
      if (b.buys >= maxTranches) return;
      if (b.spent >= budget * 0.999) return;
      if (autoSpent >= autoCap * 0.999) return;
      if (cash <= 0) return;

      if (!buyRules.every(function(r){ return testRule(r, b.ctx, i); })) return;

      var rate = fxAt(day, b.market); if (rate == null) return;
      var price = b.pts[i].v, unit = price * rate;
      var tranche = Math.min(budget * buyPct, budget - b.spent, autoCap - autoSpent, cash);
      var bq = roundQty(tranche / unit, b.market);
      if (bq <= 0) return;

      trades.push({ market:b.market, symbol:b.symbol, name:b.name,
                    side:'buy', qty:bq, price:price, fx:rate, traded_on:day, reason:'조건' });

      if (b.qty <= 0) held++;
      b.qty   += bq;
      b.spent += bq * unit;
      b.buys  += 1;
      cash      -= bq * unit;
      autoSpent += bq * unit;
      b.lastAct  = dayNo;
    });
  });

  // 같은 날이면 매도를 먼저 (현금이 생겨야 매수가 가능하므로)
  trades.sort(function(a,b){
    var d = a.traded_on.localeCompare(b.traded_on);
    if (d !== 0) return d;
    if (a.side === b.side) return 0;
    return a.side === 'sell' ? -1 : 1;
  });
  return trades;
}

/*  봉 열쇠에서 날짜만 (분·시간봉은 "2026-09-01T13:30" 으로 옵니다).
    일별 기록은 <하루에 한 줄> 이어야 합니다 — 4시간봉이라고 하루에
    두 줄씩 쌓으면 수익 곡선이 하루를 두 번 세는 꼴이 됩니다.        */
function dayOf(x){ return String(x || '').slice(0, 10); }

function rebuildSnapshots(allTrades, priceMap, seed, startDate){
  var from = dayOf(startDate);
  var dates = {};
  Object.keys(priceMap).forEach(function(k){
    priceMap[k].forEach(function(p){ var d = dayOf(p.d); if (d >= from) dates[d] = 1; });
  });
  allTrades.forEach(function(t){
    var d = dayOf(t.traded_on); if (d >= from) dates[d] = 1; });
  var days = Object.keys(dates).sort();
  if (!days.length) return [];

  var sorted = allTrades.slice().sort(function(a,b){
    return String(a.traded_on).localeCompare(String(b.traded_on)); });
  var pos = {}, cash = seed, ti = 0, out = [];
  var lastPrice = {};
  /*  ⚠️ 여기서 돈이 <증발>하고 있었습니다.

      아래 평가 줄이 원래 이랬습니다.
          if (pos[k] > 0 && lastPrice[k]) hold += pos[k] * lastPrice[k] * rate;
      시세가 없으면 <그 종목은 아예 안 더합니다>. 그런데 살 때 현금은
      이미 빼놨습니다. 결과가 ‘현금은 나갔는데 주식은 없다’ — 산 만큼
      그대로 손실로 잡힙니다.

      실제로 터졌습니다. 채권팀 백테스트가 ‘수익률 −45.10%’ 를 냈는데,
      바로 아래 <종목별 기여도> 를 다 더하면 −223만원(−2.2%) 이었습니다.
      같은 39번의 매매인데 20배가 달랐습니다.

      원인: 팀이 직접 산 ETHU(2x Ether)·SOXS(반도체 3X 인버스)는
      S&P500 명단에 없습니다. 백테스트는 <스캔 명단의 시세만> 받아오니
      이 둘은 시세가 없었고, 4,067만원어치가 통째로 0 원이 됐습니다.
      (‘최종 자산 54,895,080 = 현금 + AAPL’ 만 남은 값이었습니다.)

      값을 못 매기면 <산 값(원가)> 으로라도 세웁니다. 틀릴 수는 있어도
      ‘없는 것’ 보다 낫습니다 — 0 원은 ‘−100%’ 라고 단언하는 것이라,
      모르는 것 중 가장 틀린 답입니다.                                */
  var cost = {};

  days.forEach(function(day){
    while (ti < sorted.length && dayOf(sorted[ti].traded_on) <= day){
      var t = sorted[ti], k = t.market+'|'+t.symbol;
      var q = Number(t.qty), pr = Number(t.price), fx = Number(t.fx || 1);
      if (t.side === 'buy'){
        pos[k] = (pos[k]||0) + q; cash -= q*pr*fx;
        //  원가(현지 통화)를 기억해 둡니다 — 시세를 못 받았을 때 씁니다
        cost[k] = cost[k] || { q:0, sum:0 };
        cost[k].q += q; cost[k].sum += q*pr;
      } else { pos[k] = Math.max(0, (pos[k]||0) - q); cash += q*pr*fx; }
      ti++;
    }
    Object.keys(priceMap).forEach(function(k){
      var arr = priceMap[k];
      //  그날 <마지막> 봉의 값이 그날 종가입니다
      for (var i=arr.length-1;i>=0;i--){ if (dayOf(arr[i].d) <= day){ lastPrice[k] = arr[i].v; break; } }
    });
    var hold = 0;
    Object.keys(pos).forEach(function(k){
      if (!(pos[k] > 0)) return;
      var mk = k.split('|')[0];
      var rate = fxAt(day, mk);
      var px = lastPrice[k];
      if (!(px > 0)){
        //  시세를 못 받았습니다 — 0 으로 지우지 말고 <산 값> 으로 세웁니다
        var c = cost[k];
        if (!c || !(c.q > 0)) return;         //  판 뒤 남은 자투리 등
        px = c.sum / c.q;
      }
      hold += pos[k] * px * (rate == null ? 1 : rate);
    });
    out.push({ d: day, cash: Math.round(cash*100)/100,
               holdings: Math.round(hold*100)/100, total: Math.round((cash+hold)*100)/100 });
  });
  /*  ‘값을 못 매긴 종목’ 은 <마지막 날 기준으로> 셉니다. 도중에 원가로
      세웠더라도 그 뒤에 팔았으면 판 값이 진짜 값이라 최종 자산은
      정확합니다 — 그런 종목까지 경고에 올리면 ‘고칠 것 없는 경고’ 가
      되어 다음부터 안 읽게 됩니다.                                   */
  out.noPrice = Object.keys(pos).filter(function(k){
    return pos[k] > 0 && !(lastPrice[k] > 0) && cost[k] && cost[k].q > 0;
  });
  return out;
}

/* ══════════ 전략 화면 ══════════ */
function indOptions(sel){
  var byCat = {};
  Object.keys(IND_SPEC).forEach(function(k){
    var sp = IND_SPEC[k];
    (byCat[sp.cat] = byCat[sp.cat] || []).push({ k:k, label:sp.label });
  });
  return Object.keys(byCat).map(function(cat){
    return '<optgroup label="'+esc(cat)+'">'
      + byCat[cat].map(function(o){
          return '<option value="'+o.k+'"'+(sel===o.k?' selected':'')+'>'+esc(o.label)+'</option>'; }).join('')
      + '</optgroup>';
  }).join('');
}

/*  규칙 목록 맨 위의 머리말. 칸 순서가 바뀌면 여기도 같이 바꿔야 합니다.  */
function ruleHeadHTML(rules){
  var sp = specOf((rules && rules[0] && rules[0].ind) || 'RSI');
  var cross = sp.cmp === 'cross';
  return '<div class="rule-head">'
    + '<span>지표</span>'
    + '<span>' + esc(sp.p1 || '-') + '</span>'
    + '<span>' + (cross ? esc(sp.p2 || '장기') : (sp.p2 ? esc(sp.p2) : '부등호')) + '</span>'
    + '<span>' + (cross ? '교차 방향' : '기준값') + '</span>'
    + '<span></span></div>';
}

function ruleRowHTML(kind, r, i){
  var sp = specOf(r.ind);
  var h = '<div class="rule-row">';
  h += '<select onchange="updRule(\''+kind+'\','+i+',\'ind\',this.value)">' + indOptions(r.ind) + '</select>';

  // 기간 (없는 지표도 있음)
  var mx = maxPeriod(r.ind);
  h += sp.p1
    ? '<input type="number" value="'+(r.period||sp.d1)+'" min="1" max="'+mx+'" title="'
      + esc(sp.p1) + ' (최대 ' + mx + ')"'
      + ' onchange="updRule(\''+kind+'\','+i+',\'period\',this.value)">'
    : '<span style="font-size:11px;color:var(--text-sub);text-align:center">-</span>';

  if (sp.cmp === 'cross'){
    h += '<input type="number" value="'+(r.period2||sp.d2)+'" min="2" max="'+mx+'" title="'
      +  esc(sp.p2||'장기') + ' (최대 ' + mx + ')"'
      +  ' onchange="updRule(\''+kind+'\','+i+',\'period2\',this.value)">';
    h += '<select onchange="updRule(\''+kind+'\','+i+',\'op\',this.value)">'
      +    '<option value="golden"'+(r.op==='golden'?' selected':'')+'>골든크로스</option>'
      +    '<option value="dead"'+(r.op==='dead'?' selected':'')+'>데드크로스</option></select>';
  } else {
    if (sp.p2){
      h += '<input type="number" value="'+(r.period2||sp.d2)+'" min="2" max="'+mx+'" title="'
        +  esc(sp.p2) + ' (최대 ' + mx + ')"'
        +  ' onchange="updRule(\''+kind+'\','+i+',\'period2\',this.value)">';
    } else {
      h += '<select onchange="updRule(\''+kind+'\','+i+',\'op\',this.value)">'
        +    ['<','<=','>','>='].map(function(o){
               return '<option value="'+o+'"'+(r.op===o?' selected':'')+'>'+o+'</option>'; }).join('')
        + '</select>';
    }
    h += '<input type="number" value="'+(r.value!=null?r.value:sp.dv)+'" step="0.1" title="기준값"'
      +  ' onchange="updRule(\''+kind+'\','+i+',\'value\',this.value)">';
  }

  h += '<button class="xbtn" onclick="delRule(\''+kind+'\','+i+')" title="삭제">&times;</button>';
  h += '</div>';
  //  방금 만든 규칙을 사람 말로 한 번 더 적어줍니다 (오해가 여기서 걸립니다)
  h += '<div class="rule-note">→ ' + esc(ruleWords(Object.assign({}, r,
        { period: r.period || sp.d1, period2: r.period2 || sp.d2,
          op: r.op || (sp.cmp === 'cross' ? 'golden' : '<'),
          value: (r.value != null ? r.value : sp.dv) }))) + '</div>';
  /*  ⚠️ 거래량을 쓰는 지표는 미국 주식에서 조심해야 합니다.
      무료 요금제는 IEX 한 거래소만 줍니다. Alpaca 문서에 IEX 는 전체
      거래량의 <약 2.5%> 라고 적혀 있습니다. 값·고가·저가는 그 거래소
      가격이라 크게 안 틀리지만, 거래량은 40분의 1 짜리 표본입니다.
      "거래량이 평소의 200%" 같은 조건은 여기서 뜻이 달라집니다.       */
  if (sp.needs === 'vol'){
    h += '<div class="rule-sub" style="color:var(--warn,#b26a00)">'
      +  '⚠️ 미국 주식의 거래량은 무료 요금제에서 <b>IEX 한 거래소</b>만 잡힙니다 '
      +  '(전체의 약 2.5%). 가격은 괜찮지만 거래량 조건은 실제와 다를 수 있어요. '
      +  '코인은 Alpaca 자체 체결이라 그대로입니다.</div>';
  }

  // 부등호가 4번째 칸으로 밀린 경우(장·단기 둘 다 쓰는 지표) 별도 줄로
  if (sp.p2 && sp.cmp !== 'cross'){
    h += '<div class="rule-sub">신호선 대비 '
      +  '<select onchange="updRule(\''+kind+'\','+i+',\'op\',this.value)">'
      +    ['<','<=','>','>='].map(function(o){
             return '<option value="'+o+'"'+(r.op===o?' selected':'')+'>'+o+'</option>'; }).join('')
      +  '</select> 기준값과 비교</div>';
  }

  var note = [];
  if (sp.unit) note.push(esc(sp.unit));
  if (sp.needs === 'hl')  note.push('고가·저가 필요');
  if (sp.needs === 'vol') note.push('거래량 필요');
  if (note.length) h += '<div class="rule-note">'+note.join(' · ')+'</div>';
  return h;
}

function symRowHTML(sy, i){
  /*  ⚠️ 국내를 <새로 고를 수는> 없습니다.

      자동매매는 국내를 못 만집니다 (autoTradable). 그런데 이 칸의
      첫 선택지가 「국내」였고, 「+ 종목 추가」 를 누르면 기본값도
      국내였습니다. 그대로 저장한 팀은 <한 종목도 안 사는> 전략을
      들고 며칠을 기다리게 됩니다.

      다만 예전에 국내로 저장해 둔 줄은 <그 줄에만> 국내를 남겨
      보여줍니다. 몰래 바꿔 놓으면 왜 안 사는지 알 수가 없고,
      아예 안 보여주면 칸이 비어 버립니다.                           */
  var isKr = String(sy.market || '').toUpperCase() === 'KR';
  return '<div class="sym-row">'
    + '<select onchange="updSym('+i+',\'market\',this.value)">'
    +   (isKr ? '<option value="KR" selected>국내 (자동매매 안 됨)</option>' : '')
    +   '<option value="US"'+(sy.market==='US'?' selected':'')+'>미국</option>'
    +   '<option value="CRYPTO"'+(sy.market==='CRYPTO'?' selected':'')+'>코인</option></select>'
    + '<input type="text" value="'+esc(sy.symbol||'')+'" placeholder="005930"'
    +   ' onchange="updSym('+i+',\'symbol\',this.value)">'
    + '<input type="text" value="'+esc(sy.name||'')+'" placeholder="종목명"'
    +   ' onchange="updSym('+i+',\'name\',this.value)">'
    + '<input type="number" value="'+(sy.alloc||0)+'" min="0" max="100" title="배분 %"'
    +   ' onchange="updSym('+i+',\'alloc\',this.value)">'
    + '<button class="xbtn" onclick="delSym('+i+')">&times;</button>'
    + '</div>';
}

/* ── 전략 템플릿 ──
   학회원이 빈 화면에서 시작하지 않도록 검증된 조합을 넣어 둡니다. */
var STRAT_PRESETS = [
  { name:'과매도 반등 (기본)', desc:'RSI 40 아래로 내려온 종목을 나눠 담고 손절 7% · 익절 15%',
    buy:[{ind:'RSI',period:14,op:'<',value:40}], sell:[],
    buy_pct:50, sell_pct:100, cooldown:3, sl_pct:7, tp_pct:15 },
  { name:'눌림목 매수', desc:'20일선보다 3% 이상 아래로 밀린 종목. 신호가 자주 나옵니다',
    buy:[{ind:'VS_SMA',period:20,op:'<',value:-3}], sell:[],
    buy_pct:50, sell_pct:100, cooldown:3, sl_pct:6, tp_pct:12 },
  { name:'추세 진입 (골든크로스)', desc:'5일선이 20일선을 위로 뚫는 순간 매수',
    /*  ⚠️ op 가 'up'·'down' 이었습니다. 판정은 ‘'dead' 면 데드크로스,
        <아니면 전부> 골든크로스’ 라 'down' 은 골든크로스로 읽혔습니다 —
        이 견본을 고른 팀은 ‘살 때 골든 · 팔 때 골든’ 이 됩니다.
        화면 고르는 칸이 쓰는 값은 'golden'·'dead' 입니다. 맞춥니다.  */
    buy:[{ind:'CROSS',period:5,period2:20,op:'golden'}],
    sell:[{ind:'CROSS',period:5,period2:20,op:'dead'}],
    buy_pct:100, sell_pct:100, cooldown:5, sl_pct:8, tp_pct:0 },
  { name:'볼린저 하단', desc:'밴드 하단(%B 10 이하)에서 4번에 나눠 담기',
    buy:[{ind:'BB_PCT',period:20,op:'<',value:10}], sell:[],
    buy_pct:25, sell_pct:100, cooldown:3, sl_pct:7, tp_pct:15 }
];

function renderPresets(){
  var box = $('stratPresets'); if (!box) return;
  box.innerHTML = STRAT_PRESETS.map(function(p,i){
    return '<button class="preset" onclick="applyPreset('+i+')">'
      + '<b>'+esc(p.name)+'</b><span>'+esc(p.desc)+'</span></button>';
  }).join('');
}
function applyPreset(i){
  var p = STRAT_PRESETS[i]; if (!p || !strat) return;
  strat.buy      = JSON.parse(JSON.stringify(p.buy));
  strat.sell     = JSON.parse(JSON.stringify(p.sell));
  strat.buy_pct  = p.buy_pct;
  strat.sell_pct = p.sell_pct;
  strat.cooldown = p.cooldown;
  strat.sl_pct   = p.sl_pct;
  strat.tp_pct   = p.tp_pct;
  lastPreview = null;
  renderStrategyEditor();
  warnStrat('"' + p.name + '" 조건을 넣었습니다. 종목을 확인하고 미리 돌려보세요.', 'info');
}
function warnStrat(msg, kind){
  var m = $('stratMsg'); if (!m) return;
  m.style.color = (kind === 'info' || kind === 'ok') ? 'var(--ok)' : 'var(--danger)';
  //  <b> 같은 강조를 쓰고 싶어서 innerHTML 입니다. 부르는 쪽에서 esc() 로
  //  감싼 값만 넣습니다 (사용자가 친 글자는 그대로 들어가지 않습니다).
  m.innerHTML = msg;
}

/* 배분 합계를 눈에 보이게 — 100%를 넘으면 현금이 모자랍니다 */
function renderAlloc(){
  var box = $('allocMsg'); if (!box) return;
  var syms = (strat && strat.symbols) || [];
  if (!syms.length){ box.innerHTML = ''; return; }
  /*  ⚠️ 예전에 국내로 저장해 둔 줄이 남아 있으면 <몇 줄이 안 사는지>
      를 숫자로 말해줍니다. 배분 합계는 100% 인데 실제로는 그만큼
      안 쓰이는 상황이라, 말 안 해주면 영영 모릅니다.                */
  var krRows = syms.filter(function(x){ return !autoTradable(x.market); });
  var krNote = krRows.length
    ? '<div class="note warn" style="margin-bottom:10px">국내 <b>' + krRows.length
      + '줄</b>은 자동매매가 <b>사지 않습니다</b> · 실시간 시세 창구가 없어서입니다. '
      + '(' + esc(krRows.map(function(x){ return x.symbol || '종목코드 없음'; }).join(', ')) + ')<br>'
      + '미국·코인으로 바꾸거나, 국내는 <b>직접 매매</b>로 사세요.</div>'
    : '';
  var sum = syms.reduce(function(a,x){ return a + Number(x.alloc||0); }, 0);
  var over = sum > 100.001;
  var short = sum < 99.999;
  box.innerHTML = krNote
    + '<div class="alloc-bar'+(over?' over':'')+'"><i style="width:'+Math.min(100,sum)+'%"></i></div>'
    + '<div style="font-size:11.5px;color:'+(over?'var(--danger)':(short?'var(--text-sub)':'var(--ok)'))
    + ';margin-bottom:12px">배분 합계 <b>'+sum.toFixed(0)+'%</b>'
    + (over  ? ' · 100%를 넘어 일부 종목은 현금이 모자라 못 삽니다.'
             : (short ? ' · 나머지 '+(100-sum).toFixed(0)+'%는 현금으로 남습니다.'
                      : ' · 시드를 모두 배분했습니다.'))
    + '</div>';
}

function setStMode(m){
  if (!strat) return;
  strat.mode = m;
  lastPreview = null;
  renderStrategyEditor();
}
/* 사용자가 설정을 바꾸면 이전 미리보기 결과를 무효로 만듭니다 */
function stratChanged(){ lastPreview = null; syncStratNums(); }

function syncStratNums(){
  if (!strat) return;
  strat.markets          = $('stMarkets') ? $('stMarkets').value : 'both';
  strat.max_positions    = Number($('stMaxPos').value);
  strat.per_position_pct = Number($('stPerPct').value);
  /*  자동매매 예산은 '자동매매 설정' 카드의 배정 금액 하나뿐입니다.
      전략 쪽 계산(백테스트·종목당 금액)은 그 값을 % 로 바꿔서 씁니다.  */
  strat.auto_budget_pct  = mtAutoPctFromBudget();
  strat.sl_pct = $('stSlOn').checked ? Number($('stSl').value) : 0;
  strat.tp_pct = $('stTpOn').checked ? Number($('stTp').value) : 0;

  /*  종목당 금액은 배정 금액(원)에서 바로 뽑습니다.
      시드 → % → 다시 원 으로 두 번 돌리면 반올림 때문에 화면 숫자와
      실제 주문 금액이 조금씩 어긋납니다. 원으로 한 번에 계산합니다.  */
  var cap = mtAutoCapWon();

  if (strat.mode === 'scan'){
    var per = cap * strat.per_position_pct/100;
    var tot = strat.max_positions * strat.per_position_pct;
    $('stScanHint').innerHTML = cap <= 0
      ? '<span style="color:var(--danger)">위 ①에서 배정 금액을 정해야 살 수 있습니다.</span>'
      : '종목당 약 <b>' + num(per) + '원</b>'
        + (tot > 100 ? ' · ⚠️ 최대 보유 × 배정 = ' + tot + '% 로 100%를 넘어 뒤쪽 종목은 못 삽니다'
                     : ' · 최대 ' + tot + '% 사용');
  }
  if ($('stMarketHint')){
    var mk  = $('stMarkets') ? $('stMarkets').value : 'both';
    var all = scanUniverse || universe || [];
    var picked = stratSymbols({ mode:'scan', markets: mk });
    /*  ⚠️ 예전에는 고른 종목 수를 그대로 적었습니다. 국내를 고르면
        "100종목을 훑습니다" 라고 나오는데 <실제로는 한 종목도 안 훑습니다>
        — 자동매매가 국내를 못 만지거든요. 셈에서 빼고, 왜 뺐는지 적습니다. */
    var able = picked.filter(function(u){ return autoTradable(u.market); });
    var n   = able.length;
    var krPick = picked.length - able.length;
    var kr  = all.filter(function(u){ return u.market === 'KR'; }).length;
    var us  = all.filter(function(u){ return u.market === 'US'; }).length;
    var cc  = all.filter(function(u){ return u.market === 'CRYPTO'; }).length;
    var tip = '';
    if (krPick)
      tip += ' · 국내 ' + krPick + '개는 자동매매 대상이 아니라 뺐습니다 (직접 매매는 가능합니다)';
    if ((mk === 'both' || mk === 'stock') && us > cc * 2)
      tip += ' · ⚠️ 미국이 ' + us + '개로 코인 ' + cc + '개보다 많아 미국 쪽에 쏠릴 수 있습니다';
    if (mk === 'CRYPTO' || (mk === 'both' && cc))
      tip += ' · 코인은 주말·야간에도 움직이고 변동성이 큽니다 · 손절 폭을 따로 잡으세요';
    /*  ⚠️ 여기가 가장 흔한 오해입니다.

        미국 장은 한국시간 밤 10:30 ~ 새벽 5:00 에 열립니다(서머타임 기준).
        한국 낮에 자동매매를 켜두고 "왜 안 사지" 하고 보면, 그 시간에는
        <미국 종목이 아예 대상에서 빠져 있습니다>. 코인을 안 넣어뒀으면
        훑을 것이 하나도 없습니다. 화면에 미리 적어둡니다.            */
    var mk = $('stMarkets') ? $('stMarkets').value : 'both';
    var hasUS = (mk === 'both' || mk === 'US' || mk === 'stock');
    var hasCC = (mk === 'both' || mk === 'CRYPTO');
    var when = '';
    if (hasUS){
      var h = new Date().getHours();
      var usNow = (h >= 22 || h < 5);          //  한국시간 기준 대략
      when = '<br><b>미국 장은 한국시간 밤 10:30 ~ 새벽 5:00</b> 에 열립니다'
           + (usNow ? ' · <b>지금 열려 있습니다</b>.'
                    : ' · <b>지금은 닫혀 있어 미국 종목은 안 훑습니다</b>'
                      + (hasCC ? ' (코인만 봅니다).' : '. 코인을 같이 넣으면 낮에도 돕니다.'));
    }
    /*  ⚠️ 0개라고만 적어두면 <무엇을 해야 하는지> 를 모릅니다.
        실제로 학회장이 「코인만」 을 골라놓고 0개를 며칠 봤습니다.
        원인은 코인이 종목 명단에 <한 개도 등록돼 있지 않아서> 였습니다.
        그래서 원인을 짚고, 임원진이면 <그 자리에서 등록하는 단추> 를 답니다. */
    var why = '', fix = '';
    if (!n){
      if (mk === 'CRYPTO' || mk === 'both'){
        if (!cc){
          why = ' · <b>코인이 종목 명단에 하나도 없습니다.</b> '
              + '자동매매는 명단에 있는 종목만 훑습니다.';
          fix = ' <button class="btn-sm" onclick="stratAddCrypto()" id="stCcBtn"'
              + ' style="margin-left:6px">코인 명단 지금 등록</button>';
        } else if (mk === 'both' && !us){
          why = ' · 미국 종목이 명단에 없습니다.';
        }
      } else if (mk === 'US' && !us){
        why = ' · <b>미국 종목이 명단에 없습니다.</b> 설정에서 S&P500 을 등록하세요.';
      }
    }
    $('stMarketHint').innerHTML = (n
        ? '<b>' + n + '종목</b>을 훑습니다'
        : '<span style="color:var(--danger)"><b>훑을 종목이 0개입니다</b>'
          + why + '</span>' + fix)
      + tip + when
      + (stratLegacyMk
          ? '<br><span style="color:var(--accent-dark,#b26a00)">※ 예전에 저장한 '
            + '<b>' + esc(stratLegacyMk === 'KR' ? '국내만' : '주식만') + '</b> 설정이었습니다. '
            + '자동매매는 국내를 못 만져서 <b>'
            + esc(stratLegacyMk === 'KR' ? '전부 (미국 + 코인)' : '미국만') + '</b> 으로 바꿨습니다 · '
            + '저장을 눌러야 반영됩니다.</span>' : '');
  }
}

/*  ── 코인 명단을 그 자리에서 등록합니다 ─────────────────────

    ⚠️ 원래는 설정 탭 깊숙이 「코인 명단 맞추기」 단추가 있었습니다.
       그런데 ‘훑을 종목 0개’ 를 보는 사람은 전략 화면에 있지 설정
       탭에 있지 않습니다. 고쳐야 할 자리에서 고칠 수 있어야 합니다.
    ⚠️ 명단 등록은 임원진만 할 수 있습니다. 학회원에게는 <누구에게
       말해야 하는지> 를 알려줍니다 — 막다른 길로 보내면 안 됩니다.   */
var stratLegacyMk = '';
async function stratAddCrypto(){
  var b = $('stCcBtn');
  if (!(me && me.role === 'officer')){
    if (b) b.outerHTML = '<span style="color:var(--danger)">'
      + '임원진에게 ‘설정 → 코인 명단 맞추기’ 를 눌러달라고 하세요.</span>';
    return;
  }
  if (b){ b.disabled = true; b.textContent = '등록 중…'; }
  try {
    var d = await edge({ source:'universe_crypto', top: 50 });
    /*  명단이 바뀌었으니 <다시 읽어> ‘몇 개를 훑는지’ 를 새로 셉니다.
        ⚠️ 여기서 안 읽으면 등록은 됐는데 화면은 계속 ‘0개’ 입니다 —
           고쳤는데 안 고쳐진 것처럼 보이는 게 제일 나쁩니다.          */
    scanUniverse = null;
    await loadScanUniverse();
    /*  ⚠️ 순서가 중요합니다. stratChanged() 가 ‘훑을 종목’ 줄을 통째로
        다시 그리기 때문에, 그 줄에 성공 메시지를 써두면 <바로 지워집니다>.
        개수가 0 → 50 으로 바뀌는 것 자체가 증거이므로 그건 그 줄에 맡기고,
        ‘등록했다’ 는 말은 <지워지지 않는 자리> 에 적습니다.            */
    stratChanged();
    warn('stratMsg', '✅ 코인 <b>' + num(d.picked, 0)
      + '개</b>를 종목 명단에 등록했습니다. 이제 자동매매가 코인을 훑습니다.', 'info');
  } catch(e){
    if (b){ b.disabled = false; b.textContent = '코인 명단 지금 등록'; }
    warn('stratMsg', esc(e.message));
  }
}

function renderStrategyEditor(){
  syncBackTf();                       //  백테스트 봉 기준 안내도 같이 새로
  if (!strat) return;
  if (!strat.mode) strat.mode = 'scan';
  var scan = strat.mode === 'scan';

  $('stMode-scan').classList.toggle('on', scan);
  $('stMode-fixed').classList.toggle('on', !scan);
  $('stScanBox').classList.toggle('hidden', !scan);
  $('stFixedBox').classList.toggle('hidden', scan);

  /*  ⚠️ 예전에 「국내만」·「주식만」 으로 저장한 전략이 있습니다.
      그대로 두면 드롭다운에 없는 값이라 <빈 칸> 이 되고, 저장하면
      엉뚱한 값이 들어갑니다. 열 때 바꿔주고 <바꿨다고 말해> 줍니다.  */
  if ($('stMarkets')){
    var mkSaved = strat.markets || 'both';
    var mkFix = (mkSaved === 'KR') ? 'both' : (mkSaved === 'stock' ? 'US' : mkSaved);
    if (mkFix !== mkSaved){
      strat.markets = mkFix;
      stratLegacyMk = mkSaved;          //  아래 안내에 씁니다
    }
    $('stMarkets').value = mkFix;
  }
  $('stMaxPos').value = String(strat.max_positions || 5);
  $('stPerPct').value = String(strat.per_position_pct || 20);
  $('stSlOn').checked = Number(strat.sl_pct || 0) > 0;
  $('stTpOn').checked = Number(strat.tp_pct || 0) > 0;
  if (strat.sl_pct) $('stSl').value = strat.sl_pct;
  if (strat.tp_pct) $('stTp').value = strat.tp_pct;

  renderPresets(); renderAlloc();
  $('symRows').innerHTML = (strat.symbols||[]).map(symRowHTML).join('')
    || '<div class="empty" style="padding:16px">종목을 추가해 주세요.</div>';
  //  칸 머리말을 먼저 얹습니다 — 「30 · < · 40」 을 범위로 읽지 않게
  $('buyRows').innerHTML = ((strat.buy||[]).length
      ? ruleHeadHTML(strat.buy) + (strat.buy||[]).map(function(r,i){ return ruleRowHTML('buy', r, i); }).join('')
      : '') || '<div class="empty" style="padding:16px">매수 조건을 추가해 주세요.</div>';
  $('sellRows').innerHTML = ((strat.sell||[]).length
      ? ruleHeadHTML(strat.sell) + (strat.sell||[]).map(function(r,i){ return ruleRowHTML('sell', r, i); }).join('')
      : '') || '<div class="empty" style="padding:16px">매도 조건을 추가해 주세요.</div>';
  $('stBuyPct').value = String(strat.buy_pct||100);
  $('stSellPct').value = String(strat.sell_pct||100);
  $('stCooldown').value = String(strat.cooldown != null ? strat.cooldown : 3);
  syncStratNums();
  if (typeof algoRender === 'function') algoRender();          //  (18차) 시장 신호
}
function addSymRow(){ strat.symbols = strat.symbols||[]; lastPreview = null;
  //  ⚠️ 기본값이 'KR' 이었습니다 — 자동매매가 못 만지는 시장입니다.
  //     그대로 저장하면 한 종목도 안 사는 전략이 됩니다.
  strat.symbols.push({ market:'US', symbol:'', name:'', alloc:0 }); renderStrategyEditor(); }
function delSym(i){ strat.symbols.splice(i,1); lastPreview = null; renderStrategyEditor(); }
function updSym(i,k,v){
  strat.symbols[i][k] = (k==='alloc') ? Number(v) : v.trim();
  lastPreview = null;
  renderAlloc();
}
function addRule(kind){
  lastPreview = null;
  strat[kind] = strat[kind]||[];
  var sp = specOf('RSI');
  strat[kind].push({ ind:'RSI', period:sp.d1, op: kind==='buy'?'<':'>',
                     value: kind==='buy'?30:70 });
  renderStrategyEditor();
}
function delRule(kind,i){ strat[kind].splice(i,1); lastPreview = null; renderStrategyEditor(); }
function updRule(kind,i,k,v){
  lastPreview = null;
  var r = strat[kind][i];
  if (k === 'ind'){
    var sp = specOf(v);
    r.ind = v;
    r.period  = sp.d1;
    r.period2 = sp.d2;
    r.op    = (sp.cmp === 'cross') ? (kind==='buy'?'golden':'dead') : (kind==='buy'?'<':'>');
    r.value = sp.dv;
    renderStrategyEditor();
    return;
  }
  /*  ⚠️ 기간은 봉 수보다 길 수 없습니다. 길면 지표 값이 안 나와서
      조건이 영영 성립하지 않는데, 오류도 경고도 없이 그냥 안 삽니다.
      직접 타이핑하면 max 를 넘길 수 있어서 여기서 한 번 더 자릅니다. */
  if (k === 'period' || k === 'period2'){
    var mx = maxPeriod(r.ind), n = Math.round(Number(v));
    if (!(n > 0)) n = specOf(r.ind)[k === 'period' ? 'd1' : 'd2'] || 14;
    if (n > mx){
      n = mx;
      warnStrat('기간은 최대 <b>' + mx + '</b> 까지입니다 · 자동매매가 종목당 '
              + MT_BARS_UI + '개 봉만 받아오기 때문에 그보다 길면 지표 값이 '
              + '아예 안 나옵니다 (조건이 영영 안 맞습니다).');
      setTimeout(renderStrategyEditor, 0);
    }
    r[k] = n;
    return;
  }
  r[k] = (k === 'op') ? v : Number(v);
}

/* 대회 설정과 종목 유니버스 */
var contest = {}, universe = [];

async function loadContest(){
  try {
    var r = await sb.rpc('contest_settings');
    contest = (r.data && !r.error) ? r.data : {};
  } catch(e){ contest = {}; }
  /*  ⚠️ contest_settings() 는 마감 시각을 안 줍니다. 순위표를 5분마다
      저절로 새로 받되 <대회가 끝나면 멈춰야> 하는데, 언제 끝나는지를
      알 길이 없었습니다. 표는 학회원도 읽을 수 있으니 여기서 같이
      읽어둡니다 (SQL 을 새로 돌릴 필요가 없습니다).                 */
  try {
    var c = await sb.from('contest').select('gen, starts_at, ends_at')
                    .order('gen', { ascending: false }).limit(1).maybeSingle();
    if (c.data && !c.error){
      contest.ends_at = c.data.ends_at;
      contest.starts_at = contest.starts_at || c.data.starts_at;
    }
  } catch(e){ /* 못 읽어도 순위표는 돕니다 — 멈추는 것만 못 합니다 */ }

  var u = await sb.from('universe').select('market,symbol,name').order('market').order('symbol');
  universe = (u.data && !u.error) ? u.data : [];
  await loadScanUniverse();

  /*  ⚠️ 이 칸은 <자동매매 탭> 안에 뜹니다.

      예전엔 여기에 ‘오늘 스캔 대상은 국내 100 · 미국 100 · 코인 50’
      이라고 적었습니다. 그런데 자동매매는 국내를 <원래 못 만집니다>
      (autoTradable). 실제로 훑는 건 100개인데 250개를 훑는다고 적어둔
      셈이었고, 그걸 믿고 기다린 팀은 ‘왜 안 사지’ 를 알 길이 없었습니다.

      자동매매가 <실제로 훑는 것만> 셉니다. 국내가 명단에 남아 있으면
      숨기지 않고 <직접 매매 전용이라 빠졌다>고 한 줄로 알려줍니다.   */
  var uniAll = scanUniverse || universe || [];
  var kr = uniAll.filter(function(x){ return x.market === 'KR'; }).length;
  var us = uniAll.filter(function(x){ return x.market === 'US'; }).length;
  var cc = uniAll.filter(function(x){ return x.market === 'CRYPTO'; }).length;
  var n  = uniAll.filter(function(x){ return autoTradable(x.market); }).length;
  var krTail = kr
    ? '<br><span class="st-hint">국내 ' + kr + '개는 <b>직접 매매 전용</b>입니다 · '
      + '자동매매는 훑지 않습니다. 실시간 시세를 받을 무료 창구가 없어서입니다.</span>'
    : '';
  if ($('uniCount')) $('uniCount').textContent = n ? (n + '개') : '전';
  if ($('uniNote')){
    if (n){
      $('uniNote').innerHTML =
          '<div class="note info" style="margin-bottom:14px">자동매매가 오늘 훑을 종목은 '
        + '<b>미국 ' + us + '</b>'
        + (cc ? ' · <b>코인 ' + cc + '</b>' : '')
        + ' · 모두 <b>' + n + '개</b>입니다. 매일 자동으로 갱신됩니다. '
        + '명단에서 빠진 종목도 <b>팔 수는 있습니다</b>.'
        + krTail + '</div>';
    } else {
      $('uniNote').innerHTML =
        '<div class="note warn" style="margin-bottom:14px">아직 <b>자동매매가 훑을 종목이 없습니다.</b> '
        + (isOfficer()
            ? '설정 → <b>팀 관리</b>에서 <b>미국 S&amp;P500 등록</b>과 '
              + '<b>코인 상위 50 등록</b>을 한 번씩 눌러주세요. 바로 채워집니다.'
            : '임원진이 미국·코인 종목을 등록하면 바로 쓸 수 있습니다.')
        + krTail + '</div>';
    }
  }
  return contest;
}

async function loadStrategy(){
  var r = await sb.rpc('team_strategies', { p_team_id: team });
  if (r.error){ $('stratMsg').textContent = errMsg(r.error); return; }
  stratList = r.data || [];
  strat = stratList.length
    ? JSON.parse(JSON.stringify(stratList[stratList.length-1].config))
    : { mode:'scan', symbols:[], markets:'both', max_positions:5, per_position_pct:20, auto_budget_pct:100,
        sl_pct:7, tp_pct:15,
        buy:[{ind:'RSI',period:14,op:'<',value:40}],
        sell:[], buy_pct:50, sell_pct:100, cooldown:3 };
  renderStrategyEditor();
  renderStratHistory();
  renderStratLive();
}

function renderStratHistory(){
  if (!stratList.length){ $('stratHist').innerHTML = ''; return; }
  $('stratHist').innerHTML = '<b>전략 변경 이력</b><br>' + stratList.map(function(s,i){
    var c = s.config || {};
    return (i+1) + '. ' + esc(s.effective_from) + ' 부터 · 종목 '
      + ((c.symbols||[]).length) + '개, 매수조건 ' + ((c.buy||[]).length)
      + '개, 매도조건 ' + ((c.sell||[]).length) + '개' + (typeof algoHistTxt === 'function' ? algoHistTxt(c) : '');
  }).join('<br>');
}

async function saveStrategy(){
  var cfg = collectStrategy();
  if (!cfg){ warnStrat('전략을 먼저 불러와 주세요.'); return; }

  var syms = stratSymbols(cfg);
  if (!syms.length){
    warnStrat(cfg.mode === 'scan'
      ? '허용 종목이 없습니다. 임원진이 팀 관리에서 종목을 등록해야 합니다.'
      : '종목을 한 개 이상 넣어주세요.'); return;
  }
  //  (18차) 종목 직접 지정 전략은 시장 신호만으로도 삼 (지표 조건 없이) · 스캔은 지표 조건이 꼭 있어야
  if (!(cfg.buy||[]).length && !(cfg.mode !== 'scan' && (cfg.signals||[]).length)){ warnStrat(cfg.mode === 'scan' && (cfg.signals||[]).length ? '전 종목 스캔은 시장 신호만으로 살 수 없습니다 (500종목을 다 사게 됨). 매수 조건을 한 개 이상 넣거나 종목 직접 지정으로 바꾸세요.' : '매수 조건이나 시장 신호를 한 개 이상 넣어주세요.'); return; }
  if (!Number(cfg.sl_pct) && !Number(cfg.tp_pct) && !(cfg.sell||[]).length && !(cfg.sig_sell||[]).length){
    warnStrat('매도 기준이 하나도 없습니다. 손절만이라도 켜주세요.'); return;
  }
  if (cfg.mode !== 'scan'){
    cfg.symbols = syms;
    var totalAlloc = syms.reduce(function(a,x){ return a + Number(x.alloc||0); }, 0);
    if (totalAlloc > 100){ warnStrat('배분 합계가 100%를 넘습니다. (현재 '+totalAlloc+'%)'); return; }
    if (totalAlloc === 0){ warnStrat('배분 비중을 입력해주세요.'); return; }
  }

  /*  ── 백테스트는 <관문이 아닙니다> ────────────────────────────

      예전에는 ‘미리 돌려보기’ 를 한 번 거쳐야만 저장이 됐고, 백테스트
      매매가 10회 미만이면 아예 막았습니다. 두 가지가 잘못됐습니다.

      ① <다른 봉을 재고 있었습니다.> 백테스트는 일봉·4시간봉만 됩니다
         (무료 창구로 500종목 90일치 분봉을 못 받습니다). 그런데 팀이
         실제로 돌리는 건 5분봉입니다. 일봉으로 ‘10회’ 가 안 나온다고
         5분봉 전략을 막는 것은 <재는 자가 다른> 것입니다. 5분봉 팀은
         아무리 해도 통과할 수 없는 관문 앞에 서 있었습니다.

      ② <그 숫자가 한동안 틀렸습니다.> 시세를 못 받은 보유 종목을
         0원으로 세는 버그가 있어서 ‘수익률 −45%’ 같은 값이 나왔습니다.
         틀린 숫자로 저장을 막고 있었던 셈입니다.

      그래서 <막지 않습니다>. 돌려본 사람은 그 기대치를 같이 남기고,
      안 돌려본 사람은 그냥 저장합니다. 거래가 적을 것 같으면 <말은>
      해주되, 결정은 팀이 합니다.

      ⚠️ 학회 기준(min_auto_trades)이 없어진 건 아닙니다. 순위표의
         <매매 횟수> 로 임원진이 그대로 봅니다 — 저장을 막는 방식이
         아니라 결과를 보는 방식으로 지킵니다.                        */
  var need = Number(contest.min_auto_trades || 10);
  var tfLive = ($('mtBarTf') || {}).value || '1d';
  var canBack = !!BACK_TF[tfLive];
  var saveNote = '';
  if (!lastPreview){
    saveNote = canBack
      ? '미리 돌려보지 않고 저장했습니다. 아래 <b>미리 돌려보기</b>로 언제든 확인할 수 있습니다.'
      : '지표 기준이 <b>' + esc(({ '5m':'5분봉','15m':'15분봉','30m':'30분봉','1h':'1시간봉' })[tfLive] || tfLive)
        + '</b>이라 백테스트로는 확인할 수 없습니다 (무료 자료로는 분봉 백테스트가 안 됩니다). '
        + '실제 매매 결과를 <b>실행 기록</b>에서 보세요.';
  } else if (lastPreview.n < need){
    saveNote = '백테스트 매매가 <b>' + lastPreview.n + '회</b>로 학회 기준(' + need + '회)보다 적습니다. '
             + '막지는 않지만, 진입 조건이 과도하게 엄격하지 않은지 확인해 보세요.'
             + (canBack ? '' : ' (지금 지표 기준으로는 백테스트와 실제가 다른 봉입니다)');
  }

  $('stratSaveBtn').disabled = true;
  $('stratSaveBtn').textContent = '저장 중…';
  try {
    var u = (await sb.auth.getUser()).data.user;
    var ins = await sb.from('strategies').insert({
      team_id: team, name: cfg.mode === 'scan' ? '스캔 전략' : '지정 종목 전략',
      config: cfg, effective_from: today(), created_by: u ? u.id : null,
      /*  ⚠️ 안 돌려봤으면 <비워 둡니다>. 0 이나 지어낸 값을 넣으면
          순위표의 ‘기대 대비’ 칸이 거짓말을 합니다. 비어 있으면
          team_scorecard 가 그 칸을 null 로 내려보냅니다 (확인했습니다). */
      expect: lastPreview
        ? { ret: lastPreview.ret, mdd: lastPreview.mdd,
            win: lastPreview.win, n: lastPreview.n, as_of: today() }
        : null });
    if (ins.error) throw ins.error;
    await runStrategy();

    /*  버튼 이름이 '저장하고 실행' 인데 눌러도 화면이 조용했습니다.
        저장했으면 실제로 켜주고, 켜졌다는 걸 위쪽 상태 띠에서 눈으로
        보게 합니다. 몇 분마다 도는지·다음이 언제인지까지 말해줍니다.  */
    try {
      if (!$('mtAutoOn').checked){ $('mtAutoOn').checked = true; }
      await edge({ source:'mt_auto_set', team_id: team,
                   auto_on: true,
                   auto_budget: Number($('mtAutoBudget').value) || 0,
                   auto_interval: $('mtAutoIv').value,
                   bar_tf: $('mtBarTf') ? $('mtBarTf').value : '1d' });
      await mtLoadAccount(); await mtLoadAuto();
      mtFlashAutoBar();
      //  저장 뒤에 목록을 다시 받아야 '지금 도는 전략' 이 새 것으로 바뀝니다
      var had = (stratList || []).length;
      await loadStrategy();
      mtFlashStratLive();
      var ivN = $('mtAutoIv').options[$('mtAutoIv').selectedIndex].textContent;
      var tfN = $('mtBarTf') ? $('mtBarTf').options[$('mtBarTf').selectedIndex].textContent : '일봉';
      warnStrat((had ? '<b>새 전략으로 바뀌었습니다.</b> 이제부터는 이 조건으로만 매매합니다 · '
                     + '예전 전략은 기록으로만 남습니다. '
                   : '저장했습니다. ')
        + '<b>' + esc(ivN) + '</b> ' + esc(tfN) + ' 기준으로 시장을 훑습니다.'
        + (had ? '<br>이미 사둔 종목은 그대로 있습니다 · 새 전략의 매도 조건에 걸리면 그때 팝니다.' : '')
        //  ⚠️ 막지 않는 대신 <말은> 합니다. 안 돌려봤다는 사실이 조용히
        //     묻히면 ‘백테스트를 봤다’ 고 착각한 채로 굴리게 됩니다.
        + (saveNote ? '<br><span style="color:var(--text-sub)">' + saveNote + '</span>' : ''),
        'ok');
    } catch(e2){
      warnStrat('전략은 저장됐지만 자동매매를 켜지 못했습니다: ' + esc(e2.message));
    }
  } catch(e){
    warnStrat(errMsg(e));
  } finally {
    $('stratSaveBtn').disabled = false;
    $('stratSaveBtn').textContent = '저장하고 실행';
  }
}

/* ══════════ 미리 돌려보기 ══════════
   DB 를 건드리지 않고 결과만 계산해서 보여줍니다.
   저장 전에 "이 조건이 말이 되나" 를 확인하는 용도입니다. */
var prevChart = null, lastPreview = null;

function collectStrategy(){
  if (!strat) return null;
  strat.buy_pct  = Number($('stBuyPct').value);
  strat.sell_pct = Number($('stSellPct').value);
  strat.cooldown = Number($('stCooldown').value);
  syncStratNums();
  if (strat.mode === 'scan') strat.symbols = [];
  return strat;
}

/* 전략이 검사할 종목 목록 — 스캔이면 오늘 명단 전체 */
var scanUniverse = null;
async function loadScanUniverse(){
  try {
    var r = await sb.rpc('universe_scan');
    if (!r.error && Array.isArray(r.data) && r.data.length){ scanUniverse = r.data; return scanUniverse; }
  } catch(e){ /* 아래 예전 방식으로 */ }
  scanUniverse = universe.map(function(u){
    return { market:u.market, symbol:u.symbol, name:u.name };
  });
  return scanUniverse;
}
function stratSymbols(cfg){
  if (cfg.mode === 'scan'){
    var mk = cfg.markets || 'both';
    return (scanUniverse || universe)
      .filter(function(u){
        if (mk === 'both')  return true;
        if (mk === 'stock') return u.market !== 'CRYPTO';
        return u.market === mk;
      })
      .map(function(u){ return { market:u.market, symbol:u.symbol, name:u.name }; });
  }
  return (cfg.symbols || []).filter(function(x){ return x.symbol; });
}

/* 공용 보관함에 쌓아둔 시세를 한 번에 읽습니다.
   [["2026-01-02", 71200], ...] 형태로 와서 {d,v} 로 펴줍니다. */
async function cachedPrices(since){
  var out = {};
  try {
    var r = await sb.rpc('price_bulk', { p_since: since });
    if (r.error || !r.data) return out;
    Object.keys(r.data).forEach(function(k){
      var arr = r.data[k] || [];
      out[k] = arr.map(function(p){ return { d: p[0], v: Number(p[1]) }; })
                  .filter(function(p){ return isFinite(p.v) && p.v > 0; });
    });
  } catch(e){ /* 보관함이 아직 없으면 빈 채로 */ }
  return out;
}

/* 시세 모으기 —
     1) 공용 보관함에서 한 번에 읽고
     2) 거기 없는 종목만 엣지 함수로 20개씩 채웁니다.
   임원진이 "과거 시세 채우기"를 돌려뒀다면 대부분 1)에서 끝납니다. */
/*  ── 백테스트를 일봉보다 잘게 돌리기 ─────────────────────────

    ⚠️ 무엇이든 잘게 할 수 있는 게 아닙니다. 재 봤습니다 (550종목·90일):
         일봉    35,500봉 · 3MB   → 넉넉
         4시간봉 89,000봉 · 7MB   → 넉넉
         1시간봉 325,000봉 · 26MB → 무료 월 egress(5GB)로 약 200회
         15분봉  1,238,000봉      → 3팀이 동시에 누르면 Alpaca 한도 초과
         5분봉   3,714,000봉·301MB→ Edge Function 메모리(256MB)를 넘겨 죽음
    그래서 화면에는 <일봉 · 4시간봉> 만 둡니다. 되는 것만 내놓습니다.

    ⚠️ 주말·공휴일은 빈 봉을 만들어 넣지 않습니다. 안 열린 날은 봉이
       아예 없고, 거래일만 그대로 이어 붙입니다. 그래야 "20봉 이동평균"
       이 20 거래봉이 됩니다 (달력 20일이 아니라).                     */
var BACK_TF = {
  '1d': { label:'일봉',    us:1, cc:1,  time:false },
  '4h': { label:'4시간봉', us:2, cc:6,  time:true  },
};
function backTf(){
  var el = $('stBackTf');
  var k = el ? el.value : '1d';
  return BACK_TF[k] ? k : '1d';
}
function syncBackTf(){
  var el = $('stBackTfHint'); if (!el) return;
  var k = backTf(), days = Number(($('stBackDays') && $('stBackDays').value) || 90);
  if (k === '1d'){
    el.innerHTML = '거래일 종가로 재생합니다. 자동매매의 <b>지표 기준 봉</b>도 '
                 + '일봉이면 백테스트와 실제가 같은 것을 봅니다.';
    return;
  }
  var t = BACK_TF[k];
  var bars = Math.round(days * 5/7 * t.us);
  el.innerHTML = '미국 종목은 하루 <b>' + t.us + '봉</b>, 코인은 <b>' + t.cc + '봉</b>이라 '
    + days + '일이면 미국 기준 약 <b>' + bars + '봉</b>입니다. '
    + '자동매매의 <b>지표 기준 봉</b>도 ' + esc(t.label) + '으로 맞춰야 같은 전략이 됩니다.'
    + '<br>주말·공휴일은 봉이 없어 그냥 건너뜁니다 · 「20봉 이동평균」은 '
    + '<b>20 거래봉</b>이지 달력 20일이 아닙니다.';
}

/*  분봉·시간봉은 보관함(일별 종가)에 없어서 Alpaca 에서 직접 받아옵니다.
    한 번에 다 받으면 Edge Function 메모리를 넘기니 나눠서 부릅니다.     */
async function gatherBars(syms, tfKey, from, onProgress){
  var use = syms.filter(function(x){ return autoTradable(x.market); });
  var out = {}, CH = 20;                //  서버의 BARS_BULK_MAX 와 같은 값
  for (var i = 0; i < use.length; i += CH){
    var chunk = use.slice(i, i + CH);
    if (onProgress) onProgress(Math.min(i + chunk.length, use.length), use.length);
    try {
      var d = await edgeCall('market-data', {
        source:'bars_bulk', tf: tfKey, start: from,
        codes: chunk.map(function(x){ return { market:x.market, symbol:x.symbol }; }) });
      var got = d.series || {};
      Object.keys(got).forEach(function(k){ out[k] = got[k]; });
    } catch(e){ /* 한 묶음이 실패해도 나머지는 계속 */ }
  }
  return out;
}

/*  창 앞으로 며칠치를 더 받아와야 하나 — <전략이> 정합니다.
    RSI 80 이면 80봉, ADX 60 이면 (평활을 두 번 해서) 120봉이 필요합니다.
    넉넉히 받으면 좋지만 그만큼 자료를 더 실어 나르니, 쓸 만큼만 받습니다. */
function warmupDays(cfg, tfKey){
  var mx = 0;
  ['buy', 'sell'].forEach(function(k){
    ((cfg && cfg[k]) || []).forEach(function(r){
      var sp = specOf(r.ind);
      var p  = Math.max(Number(r.period) || sp.d1 || 14,
                        Number(r.period2) || sp.d2 || 0);
      mx = Math.max(mx, p * (sp.warm || 1));
    });
  });
  //  ⚠️ 먼저 <봉 개수> 로 정하고, 그다음에 날짜로 바꿉니다.
  //     날짜로 먼저 정하면 4시간봉일 때 봉이 두 배로 들어와 낭비되고,
  //     반대로 하한을 날짜로 걸면 봉 기준마다 봉 수가 달라집니다.
  var bars = Math.max(30, mx + 20);          //  조건이 없어도 최소 30봉
  //  하루에 몇 봉 나오나 (일봉 1개, 4시간봉은 미국 2개 — 적은 쪽으로
  //  잡아야 모자라지 않습니다). 주말·공휴일 몫 1.55배.
  var per = (BACK_TF[tfKey || '1d'] || BACK_TF['1d']).us;
  //  400일은 보관함이 들고 있는 범위입니다 (price_bulk 기본값).
  return Math.min(400, Math.max(14, Math.ceil(bars / per * 1.55)));
}

async function gatherPrices(syms, startDate, onProgress, cfg, tfKey){
  var from = backDate(startDate, warmupDays(cfg, tfKey));
  //  일봉이 아니면 보관함(일별 종가)에 없는 자료라 Alpaca 에서 직접 받습니다
  if (tfKey && tfKey !== '1d') return await gatherBars(syms, tfKey, from, onProgress);
  var priceMap = await cachedPrices(from);

  var missing = syms.filter(function(x){
    var got = priceMap[x.market + '|' + x.symbol];
    return !got || got.length < 30;
  });
  if (onProgress) onProgress(syms.length - missing.length, syms.length);
  if (!missing.length) return priceMap;

  for (var i = 0; i < missing.length; i += 20){
    var chunk = missing.slice(i, i + 20);
    if (onProgress) onProgress(syms.length - missing.length + Math.min(i + chunk.length, missing.length),
                               syms.length);
    try {
      var d = await edgeCall('market-data', {
        source:'bulk',
        codes: chunk.map(function(x){ return { market:x.market, symbol:x.symbol }; }),
        start: from });
      var got = d.series || {};
      Object.keys(got).forEach(function(k){ priceMap[k] = got[k]; });
    } catch(e){
      // 한 묶음이 실패해도 나머지는 계속 받습니다
    }
  }
  return priceMap;
}

function previewStats(trades, snaps, seed){
  var last = snaps.length ? Number(snaps[snaps.length-1].total) : seed;
  var peak = -Infinity, mdd = 0;
  snaps.forEach(function(s){
    var v = Number(s.total);
    if (v > peak) peak = v;
    var dd = peak > 0 ? (v/peak - 1)*100 : 0;
    if (dd < mdd) mdd = dd;
  });
  var avg = {}, win = 0, lose = 0;
  trades.forEach(function(t){
    var k = t.market+'|'+t.symbol, f = Number(t.fx||1);
    avg[k] = avg[k] || { q:0, c:0 };
    if (t.side === 'buy'){ avg[k].c += t.qty*t.price*f; avg[k].q += t.qty; }
    else {
      var ac = avg[k].q > 0 ? avg[k].c/avg[k].q : 0;
      if (ac > 0){ if (t.price*f > ac) win++; else lose++; }
      var keep = Math.max(0, avg[k].q - t.qty);
      avg[k].c = avg[k].q > 0 ? avg[k].c * (keep/avg[k].q) : 0;
      avg[k].q = keep;
    }
  });
  var closed = win + lose;
  return { n:trades.length, last:last, ret:(last/seed-1)*100, mdd:mdd,
           win: closed ? win/closed*100 : null, closed:closed,
           sl: trades.filter(function(t){ return t.reason === '손절'; }).length,
           tp: trades.filter(function(t){ return t.reason === '익절'; }).length };
}

async function previewStrategy(){
  var btn = $('stratPrevBtn');
  var cfg = collectStrategy();
  if (!cfg){ warnStrat('전략을 먼저 불러와 주세요.'); return; }

  var syms = stratSymbols(cfg);
  if (!syms.length){
    warnStrat(cfg.mode === 'scan'
      ? '허용 종목이 없습니다. 임원진이 팀 관리에서 종목을 등록해야 합니다.'
      : '종목을 한 개 이상 넣어주세요.');
    return;
  }
  //  (18차) 시장 신호는 과거 기록이 없어 백테스트에 넣지 않음 (지표 조건만 돌림)
  if (!(cfg.buy||[]).length && (cfg.signals||[]).length){ warnStrat('시장 신호만 쓰는 전략은 백테스트로 확인할 수 없습니다 (신호의 과거 기록이 없습니다). 아래 ‘지금 신호 상태 보기’ 로 확인하고, 실제 결과는 실행 기록에서 보세요.', 'info'); return; }
  if (!(cfg.buy||[]).length){ warnStrat('매수 조건을 한 개 이상 넣어주세요.'); return; }
  if (!Number(cfg.sl_pct) && !Number(cfg.tp_pct) && !(cfg.sell||[]).length && !(cfg.sig_sell||[]).length){
    warnStrat('매도 기준이 하나도 없습니다. 손절만이라도 켜주세요.'); return;
  }

  btn.disabled = true;
  var tinfo = teams.filter(function(t){ return t.id === team; })[0] || {};
  var backDays = Number(($('stBackDays') && $('stBackDays').value) || 90);
  var startDate = backDate(today(), backDays);
  var seed = Number(tinfo.seed || 100000000);

  try {
    if (syms.some(function(x){ return isUsd(x.market); })){
      btn.textContent = '환율 확인 중…';
      if (!await loadFxSeries(backDate(startDate, 400))){
        warnStrat('원/달러 환율을 받지 못했습니다. 경제지표 탭에서 "원/달러 환율"을 한 번 조회해주세요.');
        btn.disabled = false; btn.textContent = '미리 돌려보기 · 기록에 남지 않습니다'; return;
      }
    }
    var tfKey = backTf();

    /*  ⚠️ 순서를 바꿨습니다 — 예전에는 시세를 <먼저> 받고 팀이 직접 산
        종목을 <나중에> 읽었습니다. 그래서 팀이 들고 있지만 스캔 명단에
        없는 종목(ETHU·SOXS 같은 레버리지 ETF)은 시세를 받을 기회가
        아예 없었고, 평가액이 0 이 됐습니다. 산 만큼 그대로 손실로
        잡혀서 ‘수익률 −45.10%’ 가 나왔습니다. 실제 전략 성적은
        −2.2% 였습니다.                                               */
    var man = await sb.from('trades')
      .select('market,symbol,side,qty,price,fx,traded_on')
      .eq('team_id', team).eq('auto', false);
    if (man.error) console.warn('직접 매매 내역을 못 읽었습니다', man.error);
    var manual = man.data || [];

    //  스캔 명단 + 팀이 실제로 산 종목 (겹치는 것은 한 번만)
    var seenSym = {}, want = [];
    syms.concat(manual.map(function(t){ return { market:t.market, symbol:t.symbol }; }))
        .forEach(function(x){
          var k = x.market + '|' + x.symbol;
          if (seenSym[k]) return;
          seenSym[k] = 1; want.push(x);
        });

    var priceMap = await gatherPrices(want, startDate, function(done, all){
      btn.textContent = '시세 ' + done + '/' + all + '…';
    }, cfg, tfKey);
    btn.textContent = '계산 중…';

    var list   = [{ effective_from: startDate, config: cfg }];
    var trades = replayStrategy(list, priceMap, seed, startDate, manual);
    var snaps  = rebuildSnapshots(manual.concat(trades), priceMap, seed, startDate);
    var st     = previewStats(trades, snaps, seed);

    // 실제 운용과 같은 방식으로 퀀트 지표까지 계산합니다
    var m = null;
    if (snaps.length >= 5){
      btn.textContent = '지표 계산 중…';
      try {
        var bench = await getBenchmark(snaps[0].d);
        var rf    = await getRiskFree();
        m = quantMetrics(snaps, bench, rf, seed);
      } catch(e){ m = null; }
    }
    renderPreview(st, snaps, seed, m, trades, backDays,
                  coverage(syms, priceMap, startDate), tfKey, manual);
    lastPreview = st;

    var need = Number(contest.min_auto_trades || 10);
    if (st.n < need){
      warnStrat('매매가 ' + st.n + '회뿐입니다. 학회 기준은 ' + need + '회 이상이에요. '
              + '진입 조건을 완화하거나(예: RSI 30 → 40) 최대 보유 종목을 늘려보세요.');
    } else {
      warnStrat('미리보기입니다 · 아직 저장되지 않았습니다. 괜찮으면 "저장하고 실행"을 누르세요.', 'info');
    }
  } catch(e){
    warnStrat(e.message);
  }
  btn.disabled = false; btn.textContent = '미리 돌려보기 · 기록에 남지 않습니다';
}

/*  ── 이 백테스트가 <실제로> 몇 종목을 훑었는가 ────────────────

    가장 흔한 오해가 "명단에 500종목이 있으니 500종목을 봤겠지" 입니다.
    아닙니다. 시세를 못 받았거나 기간이 짧으면 그 종목은 조용히 빠집니다
    (replayStrategy 의 `if (pts.length < 30) book[k] = null`).

    실제로 미국 주식이 결과에 한 건도 없어서 "조건이 안 맞았나" 하고
    한참 헤맸습니다. 조용히 빠지면 안 됩니다 — 숫자로 보여줍니다.        */
function coverage(syms, priceMap, startDate){
  var out = {};
  (syms || []).forEach(function(x){
    var m = x.market || '?';
    out[m] = out[m] || { total:0, used:0, thin:0, none:0, off:!autoTradable(m) };
    out[m].total++;
    if (out[m].off) return;                //  자동매매 대상이 아닌 시장
    var pts = (priceMap[m + '|' + x.symbol] || [])
                .filter(function(p){ return p.d >= startDate; });
    if (!pts.length)          out[m].none++;
    else if (pts.length < 30) out[m].thin++;
    else                      out[m].used++;
  });
  return out;
}
/*  ── 백테스트는 <일봉> 입니다 ────────────────────────────────

    ⚠️ 백테스트가 재생하는 것은 하루 한 개짜리 종가입니다. 그런데 서버
       자동매매는 팀이 고른 <지표 기준 봉> 으로 조건을 봅니다. 5분봉을
       골라두면 "RSI 20" 이 백테스트에서는 <20일>, 실제로는 <20개 5분봉
       = 100분> 이 됩니다. 이름만 같지 완전히 다른 전략입니다.

       무료 창구로는 500종목의 90일치 5분봉을 받을 수가 없어서 백테스트를
       분봉으로 돌릴 방법이 없습니다. 그러면 최소한 <다르다는 사실> 은
       화면에 적어야 합니다. 조용히 두면 "백테스트대로 안 움직인다" 를
       영영 못 풀게 됩니다.                                              */
/*  ── 값을 못 매긴 종목이 있으면 반드시 말합니다 ───────────────
    ⚠️ 조용히 넘어가면 ‘−45%’ 같은 숫자가 진짜인 줄 알고 전략을 버리게
       됩니다. 실제로 그랬습니다.                                     */
function noPriceHTML(snaps){
  var ks = (snaps && snaps.noPrice) || [];
  if (!ks.length) return '';
  return '<div class="note warn" style="margin:0 0 12px">'
    + '<b>' + esc(ks.map(function(k){ return k.split('|')[1]; }).join(' · ')) + '</b> '
    + '은(는) 지난 시세를 못 받아 <b>산 값 그대로</b> 세웠습니다 · 이 종목들의 '
    + '오르내림은 아래 성적에 <b>안 들어가 있습니다</b>.'
    + '<br>예전에는 이런 종목을 <b>0 원</b>으로 쳤습니다. 산 만큼이 그대로 손실로 잡혀서 '
    + '‘수익률 −45%’ 같은 숫자가 나왔습니다 · 전략과 아무 상관 없는 숫자였습니다.'
    + (isOfficer()
        ? '<br>설정 → 팀 관리의 <b>「과거 시세 채우기」</b>를 돌리면 채워집니다.'
        : '<br>임원진에게 <b>「과거 시세 채우기」</b>를 부탁하세요.')
    + '</div>';
}

/*  ── 직접 산 종목이 성적에 섞여 있다는 사실 ───────────────────
    ⚠️ 이 백테스트는 <시드 1억으로 처음부터> 돌리는 게 아닙니다. 팀이
       직접 산 것을 깔아놓고 그 위에서 전략을 돌립니다. 그래서 ‘수익률’
       에는 직접 매매 손익이 섞여 있고, <종목별 기여도> 는 <전략이 한
       매매만> 셉니다 — 두 숫자가 다른 게 정상입니다.                  */
function manualHTML(manual){
  if (!manual || !manual.length) return '';
  var syms = {};
  manual.forEach(function(t){ syms[t.market + '|' + t.symbol] = 1; });
  var n = Object.keys(syms).length;
  return '<div class="note info" style="margin:0 0 12px">'
    + '팀이 <b>직접 산 ' + n + '종목</b>도 함께 굴린 결과입니다 · '
    + '<b>수익률</b>에는 직접 매매 손익이 같이 들어 있습니다.'
    + '<br>아래 <b>종목별 기여도</b>는 <b>전략이 한 매매만</b> 셉니다. '
    + '두 숫자가 다른 것이 정상입니다.'
    + '</div>';
}

function tfMismatchHTML(usedTf){
  var el = $('mtBarTf');
  var live = el ? el.value : '1d';
  var back = usedTf || '1d';
  if (live === back) return '';
  var NM = { '5m':'5분봉','15m':'15분봉','30m':'30분봉','1h':'1시간봉',
             '4h':'4시간봉','1d':'일봉','1w':'주봉' };
  var canBack = !!BACK_TF[live];
  return '<div class="note warn" style="margin:0 0 12px">'
       + '이 백테스트는 <b>' + esc(NM[back] || back) + '</b>으로 돌렸습니다. '
       + '그런데 팀의 <b>지표 기준 봉</b>은 <b>' + esc(NM[live] || live) + '</b>입니다. '
       + '같은 「RSI 20」이라도 여기서는 <b>20개 ' + esc(NM[back] || back) + '</b>, '
       + '실제 자동매매에서는 <b>20개 ' + esc(NM[live] || live) + '</b>을 봅니다 · '
       + '이름만 같지 다른 전략입니다.<br>'
       + (canBack
          ? '위 <b>봉 기준</b>을 <b>' + esc(NM[live]) + '</b>으로 바꾸면 실제와 같아집니다.'
          : '<b>' + esc(NM[live] || live) + '</b>은 무료 자료로는 백테스트가 안 됩니다 '
            + '(자료량이 Edge Function 한도를 넘습니다). 모의투자 화면에서 지표 기준 봉을 '
            + '<b>일봉</b>이나 <b>4시간봉</b>으로 바꾸면 백테스트와 맞출 수 있습니다.')
       + '</div>';
}

function coverageHTML(cov){
  var names = { US:'미국 주식', KR:'국내 주식', CRYPTO:'코인' };
  var ks = Object.keys(cov).sort();
  if (!ks.length) return '';
  var bad = ks.filter(function(k){ return !cov[k].off && cov[k].used === 0 && cov[k].total > 0; });
  var offK = ks.filter(function(k){ return cov[k].off && cov[k].total > 0; });
  var rows = ks.map(function(k){
    var c = cov[k], miss = c.thin + c.none;
    if (c.off) return '<span style="display:inline-block;margin-right:14px">'
         + '<b>' + esc(names[k] || k) + '</b> <span style="color:var(--text-sub)">'
         + '자동매매 대상 아님 (' + c.total + '종목)</span></span>';
    return '<span style="display:inline-block;margin-right:14px">'
         + '<b>' + esc(names[k] || k) + '</b> ' + c.used + '/' + c.total + '종목'
         + (miss ? ' <span style="color:var(--text-sub)">(시세 없음 ' + c.none
                  + ' · 기간 짧음 ' + c.thin + ')</span>' : '')
         + '</span>';
  }).join('');
  return '<div class="note ' + (bad.length ? 'warn' : 'info')
       + '" style="margin:0 0 12px">실제로 훑은 종목: ' + rows
       + (bad.length
          ? '<br><b>' + bad.map(function(k){ return esc(names[k] || k); }).join(' · ')
            + '</b> 은(는) 과거 시세가 없어서 이번 백테스트에서 <b>통째로 빠졌습니다</b>. '
            + '결과에 안 나오는 게 당연합니다 · 조건이 안 맞아서가 아닙니다. '
            + '임원진 화면의 <b>「과거 시세 채우기」</b>를 돌려주세요.'
          : '')
       + (offK.length
          ? '<br>' + offK.map(function(k){ return esc(names[k] || k); }).join(' · ')
            + '은(는) 무료 실시간 창구가 없어 <b>서버 자동매매가 손대지 못합니다</b>. '
            + '실제로 일어날 수 없는 일을 성적표에 넣지 않으려고 백테스트에서도 뺐습니다 '
            + '(직접 매매는 그대로 됩니다).'
          : '')
       + '</div>';
}

function renderPreview(st, snaps, seed, m, trades, backDays, cov, tfKey, manual){
  show('stratPreview');
  var cls = st.ret >= 0 ? 'pos' : 'neg';
  var q = $('stratPrevQuant');
  if (q){
    q.innerHTML = m
      ? quantHTML(m, '<b>지난 ' + (backDays||90) + '일</b>을 그대로 재생한 결과입니다.')
        + attributionHTML(attribution(trades || [], []))
        + '<div class="q-group" style="margin-bottom:0"><div class="q-title">일간 수익률 분포</div>'
        + '<div id="prevDistBox" style="width:100%;height:230px"></div></div>'
      : '';
    if (m) setTimeout(function(){ drawDist('prevDistBox', m.rets); }, 30);
  }
  $('stratPrevTiles').innerHTML = tfMismatchHTML(tfKey)
    + noPriceHTML(snaps)
    + manualHTML(manual)
    + (cov ? coverageHTML(cov) : '')
    + '<div class="tiles">'
    + tile('최종 자산', num(st.last), '시드 ' + num(seed), cls)
    + tile('수익률', pct(st.ret), snaps.length + '일 기준', cls)
    + tile('최대 낙폭', st.mdd.toFixed(1) + '%', '고점 대비 최대 하락', 'neg')
    + tile('매매 횟수', num(st.n) + '회',
           (st.sl || st.tp) ? ('손절 ' + st.sl + ' · 익절 ' + st.tp) : (st.closed + '회 청산'))
    + tile('승률', st.win == null ? '-' : st.win.toFixed(0) + '%',
           st.closed ? '청산 ' + st.closed + '회 기준' : '아직 청산 없음')
    + '</div>';

  if (typeof echarts === 'undefined') return;
  prevChart = chartOn('stratPrevBox', prevChart); if (!prevChart) return;
  if (!snaps.length){ prevChart.clear(); return; }
  //  백테스트 그림도 같은 이유로 폭을 재서 눈금을 정합니다
  var sAll = snaps.map(function(x){ return Number(x.total); }).concat([seed]);
  var sSpan = Math.max.apply(null, sAll) - Math.min.apply(null, sAll);
  prevChart.setOption({
    backgroundColor:'transparent', animation:false,
    grid:{ left:80, right:22, top:18, bottom:36 },
    tooltip:{ trigger:'axis',
      formatter:function(ps){
        return fmtDateKo(ps[0].value[0]) + '<br><b>' + num(ps[0].value[1]) + '원</b>'; } },
    xAxis:{ type:'time', axisLine:{ lineStyle:{ color:'#e2e6f0' } },
      axisLabel:{ fontSize:10, color:'#5a6278', hideOverlap:true,
        formatter:{ year:'{yyyy}년', month:'{M}월', day:'{M}/{d}', none:'{yyyy}-{MM}-{dd}' } } },
    yAxis:{ type:'value', scale:true, splitLine:{ lineStyle:{ color:'#eef1f7' } },
      axisLabel:{ fontSize:10, color:'#5a6278', formatter: wonAxisBy(sSpan) } },
    series:[{ type:'line', showSymbol:false,
      lineStyle:{ color: st.ret >= 0 ? '#1f8a70' : '#c0392b', width:2 },
      areaStyle:{ color: st.ret >= 0 ? 'rgba(31,138,112,.10)' : 'rgba(192,57,43,.10)' },
      data: snaps.map(function(s){ return [s.d, Number(s.total)]; }),
      markLine:{ silent:true, symbol:'none',
        lineStyle:{ color:'#9aa3b8', type:'dashed' },
        label:{ formatter:'시드', fontSize:10, color:'#5a6278' },
        data:[{ yAxis: seed }] } }]
  }, true);
}

async function runStrategy(){
  var msg = $('stratMsg');
  msg.style.color = 'var(--text-sub)';
  msg.textContent = '전략을 다시 돌리는 중…';

  var r = await sb.rpc('team_strategies', { p_team_id: team });
  stratList = (r.data && !r.error) ? r.data : [];
  if (!stratList.length){ warnStrat('저장된 전략이 없습니다.'); return; }
  renderStratHistory();

  var tinfo = teams.filter(function(t){ return t.id === team; })[0] || {};
  var startDate = contest.scan_start || tinfo.started_on || '2026-01-01';
  var seed = Number(tinfo.seed || 100000000);

  // 전략들이 쓰는 종목 전부 (스캔이면 유니버스)
  var need = {};
  stratList.forEach(function(st){
    stratSymbols(st.config || {}).forEach(function(sy){
      need[sy.market+'|'+sy.symbol] = sy;
    });
  });
  var syms = Object.keys(need).map(function(k){ return need[k]; });
  if (!syms.length){ warnStrat('전략에 종목이 없습니다.'); return; }

  if (syms.some(function(x){ return isUsd(x.market); })){
    msg.textContent = '환율 확인 중…';
    if (!await loadFxSeries(backDate(startDate, 400))){
      warnStrat('원/달러 환율을 받지 못해 해외 종목을 계산할 수 없습니다.');
      return;
    }
  }

  var priceMap;
  try {
    /*  여러 전략이 줄줄이 있을 수 있으니, 그중 가장 긴 기간을 쓰는
        것에 맞춰 창 앞 자료를 받아옵니다 (하나라도 모자라면 그 조건이
        조용히 성립하지 않습니다).                                      */
    var allCfg = { buy:[], sell:[] };
    stratList.forEach(function(st){
      allCfg.buy  = allCfg.buy.concat((st.config || {}).buy  || []);
      allCfg.sell = allCfg.sell.concat((st.config || {}).sell || []);
    });
    priceMap = await gatherPrices(syms, startDate, function(done, all){
      msg.textContent = '시세 수집 ' + done + '/' + all + '…';
    }, allCfg, backTf());
  } catch(e){ warnStrat(e.message); return; }

  // 손매매는 그대로 두고, 자동 거래만 새로 씁니다
  var man = await sb.from('trades')
    .select('market,symbol,side,qty,price,fx,traded_on')
    .eq('team_id', team).eq('auto', false);
  var manual = man.data || [];

  msg.textContent = '전략을 재생하는 중…';
  var generated = replayStrategy(stratList, priceMap, seed, startDate, manual);

  var clr = await sb.rpc('clear_auto_trades', { p_team_id: team });
  if (clr.error){ warnStrat(errMsg(clr.error)); return; }

  if (generated.length){
    var u = (await sb.auth.getUser()).data.user;
    var rows = generated.map(function(t){
      //  trades.traded_on 은 <날짜> 칸입니다. 4시간봉이면 봉 열쇠에
      //  시각이 붙어 오므로 날짜만 잘라 넣습니다.
      return { team_id: team, market:t.market, symbol:t.symbol, name:t.name,
               side:t.side, qty:t.qty, price:t.price, fx: t.fx || 1,
               traded_on: dayOf(t.traded_on), note: t.reason || null,
               auto: true, created_by: u ? u.id : null };
    });
    for (var j = 0; j < rows.length; j += 200){
      msg.textContent = '거래 기록 중… (' + Math.min(j+200, rows.length) + '/' + rows.length + ')';
      var ins = await sb.from('trades').insert(rows.slice(j, j+200));
      if (ins.error){ warnStrat(errMsg(ins.error)); return; }
    }
  }

  msg.textContent = '일별 기록을 다시 계산하는 중…';
  var snaps = rebuildSnapshots(manual.concat(generated), priceMap, seed, startDate);
  if (snaps.length){
    var rs = await sb.rpc('replace_snapshots', { p_team_id: team, p_rows: snaps });
    if (rs.error) console.warn('스냅샷 저장 실패:', rs.error);
  }

  await sb.from('strategy_runs').upsert({
    team_id: team, last_date: today(), trades_made: generated.length,
    updated_at: new Date().toISOString() }, { onConflict:'team_id' });

  var sl = generated.filter(function(t){ return t.reason === '손절'; }).length;
  var tp = generated.filter(function(t){ return t.reason === '익절'; }).length;
  warnStrat('완료 · 자동매매 ' + generated.length + '건'
          + (sl||tp ? ' (손절 ' + sl + ' · 익절 ' + tp + ')' : '')
          + ', 일별 기록 ' + snaps.length + '일.', 'info');
  await loadTeam();
  loadLeaderboard();
}

function backDate(iso, days){
  var d = new Date(iso); d.setDate(d.getDate() - days);
  return d.toISOString().slice(0,10);
}

/*  ── 자동매매 진단 ───────────────────────────────────────────

    ⚠️ 왜 이게 필요했냐면 — 채권팀이 자동매매를 켜두고 2주를 기다렸는데
       체결이 하나도 없었습니다. 그런데 화면 어디에도 이유가 없었습니다.

    자동매매가 ‘아무것도 안 사는’ 이유는 갈래가 여럿이고, 갈래마다
    고치는 법이 완전히 다릅니다. 그런데 화면에서는 전부 똑같이
    ‘조용함’ 으로 보입니다. 그래서 <어느 갈래인지> 를 짚어 줍니다.

      · 스캔을 부르는 사람이 없다  → 고장. SQL 을 안 돌린 것
      · 팀이 안 켰다 / 배정 0 / 전략 없음 → 설정 문제. 화면에서 고침
      · 조건에 맞는 종목이 없었다 → 정상. 전략이 빡센 것
      · 봉을 못 받았다            → 고장. Alpaca 키·요금제                */
/*  ── 지금 한 번 돌려보기 ─────────────────────────────────────

    ⚠️ 진단이 ‘예약은 걸려 있는데 실행 기록이 없습니다’ 에서 멈춰
       있었습니다. 그 한 줄로는 둘을 못 가립니다.

         ㄱ. 스캔(Edge Function) 자체가 고장   → 키·배포 문제
         ㄴ. 스캔은 멀쩡한데 예약이 못 부름     → pg_net·설정 문제

       고칠 데가 완전히 다른데 화면은 똑같이 보였습니다.
       임원진은 스캔을 직접 부를 수 있으니(mt_scan 은 토큰 또는 임원진),
       한 번 돌려보면 그 자리에서 갈립니다.

    ⚠️ 돈이 나가는 건 아니지만 <진짜로 매매가 일어날 수 있습니다>.
       조건에 맞는 종목이 있으면 삽니다. 그래서 먼저 묻습니다.        */
async function autoRunNow(){
  if (!confirm('자동매매 스캔을 지금 한 번 돌립니다.\n\n'
             + '켜져 있는 팀의 조건에 맞는 종목이 있으면 <실제로 체결됩니다>.\n'
             + '계속할까요?')) return;
  var b = $('autoRunBtn'), label = b ? b.textContent : '';
  if (b){ b.disabled = true; b.textContent = '도는 중…'; }
  var box = $('autoDocBox');
  if (box) box.innerHTML = '<div class="empty" style="padding:14px">스캔을 돌리는 중…</div>';
  try {
    var d = await edge({ source: 'mt_scan' });
    /*  ⚠️ 결과를 그대로 늘어놓지 않습니다. 알고 싶은 건 ‘스캔이
        도느냐’ 하나입니다. 돌았으면 그 사실부터 크게 적습니다.      */
    var ran = Number(d && d.ran) || 0;
    warn('autoDocMsg',
      '<b>스캔이 돌았습니다.</b> 훑은 팀 ' + num(ran, 0) + '개'
      + (d && d.note ? ' · ' + esc(String(d.note)) : '')
      + '<br>→ 스캔 자체는 멀쩡합니다. 기록이 안 쌓였던 건 '
      + '<b>예약 작업이 스캔을 못 부르고 있다</b>는 뜻입니다 '
      + '(pg_net 이나 <code>private_warm_cfg</code> 를 확인하세요).', 'info');
  } catch(e){
    warn('autoDocMsg',
      '<b>스캔이 실패했습니다.</b> ' + esc(e.message)
      + '<br>→ 예약 작업 문제가 아니라 <b>스캔 자체</b>가 막혀 있습니다.', '');
  }
  if (b){ b.disabled = false; b.textContent = label; }
  autoDoc();
}

async function autoDoc(){
  var box = $('autoDocBox'); if (!box) return;
  box.innerHTML = '<div class="empty" style="padding:14px">보는 중…</div>';
  try {
    var r = await sb.rpc('auto_health');
    if (r.error) throw new Error(errMsg(r.error));
    var d = r.data || {};
    var teams = aiArr(d.teams), recent = aiArr(d.recent);

    //  ── 제일 위에 ‘한 줄 진단’ ──
    var head, cls;
    var lastMs = d.last_run ? Date.parse(d.last_run) : 0;
    var ageH = lastMs ? (Date.now() - lastMs) / 36e5 : null;
    var ready = teams.filter(function(t){ return !t.blocked; });

    if (d.cron_readable && !d.scan_scheduled){
      cls = 'warn';
      head = '⛔ <b>스캔을 부르는 예약 작업이 없습니다.</b> 자동매매는 '
           + '<b>한 번도 돌지 않았습니다</b> · 팀이 뭘 어떻게 설정했든 상관없습니다.<br>'
           + '고치는 법: Supabase SQL Editor 에서 <b>terminal-예열자동.sql</b> → '
           + '<b>terminal-자동운영.sql</b> 을 차례로 돌리세요.';
    } else if (!d.cfg){
      cls = 'warn';
      head = '⛔ <b>주소·열쇠가 저장돼 있지 않습니다</b> (private_warm_cfg). '
           + '예약 작업이 있어도 서버를 못 부릅니다.<br>'
           + '고치는 법: <b>terminal-예열자동.sql</b> 의 1단계를 마치세요.';
    } else if (!lastMs){
      cls = 'warn';
      head = '⛔ <b>스캔이 한 번도 돈 적이 없습니다.</b> 예약은 걸려 있는데 '
           + '실행 기록이 없습니다 · 예약 작업이 실패하고 있을 수 있습니다.';
    } else if (ageH > 2){
      cls = 'warn';
      head = '⛔ <b>마지막 스캔이 ' + num(ageH, 1) + '시간 전입니다.</b> '
           + '5분마다 돌아야 정상입니다 · 예약 작업이 멈췄습니다.';
    } else if (!ready.length){
      cls = 'warn';
      head = '⚠️ <b>스캔은 잘 돌고 있는데, 준비된 팀이 없습니다.</b> '
           + '아래 표에서 팀마다 무엇이 막고 있는지 보세요.';
    } else {
      cls = '';
      head = '✅ <b>스캔이 돌고 있습니다</b> (마지막 '
           + (ageH < 1 ? num(ageH * 60, 0) + '분' : num(ageH, 1) + '시간') + ' 전, '
           + '24시간 동안 ' + num(d.runs_24h, 0) + '회). '
           + '준비된 팀 ' + ready.length + '개 · 자동 체결 누적 '
           + num(d.trades_auto, 0) + '건.';
    }
    if (!d.cron_readable)
      head += '<br><span class="st-hint">※ 예약 작업 목록은 못 읽었습니다 '
            + '(권한). 아래 ‘마지막 스캔’ 시각으로 판단하세요.</span>';

    var H = '<div class="note ' + cls + '" style="margin-bottom:12px">' + head + '</div>';

    //  ── 팀별 ──
    H += '<div class="scroll"><table><thead><tr><th>팀</th><th>자동매매</th>'
       + '<th class="num">배정 금액</th><th class="num">전략</th>'
       + '<th>마지막 차례</th><th>막고 있는 것</th></tr></thead><tbody>'
       + (teams.length ? teams.map(function(t){
           return '<tr><td><b>' + esc(aiStr(t.name)) + '</b></td>'
             + '<td>' + (t.auto_on ? '<span class="by-tag auto">켜짐</span>'
                                   : '<span class="by-tag manual">꺼짐</span>') + '</td>'
             + '<td class="num">' + num(t.budget, 0) + '원</td>'
             + '<td class="num">' + num(t.strategies, 0) + '개</td>'
             + '<td class="st-hint">' + esc(String(t.last_at || '-').slice(0, 16).replace('T', ' ')) + '</td>'
             + '<td>' + (t.blocked
                 ? '<span style="color:var(--neg)">' + esc(t.blocked) + '</span>'
                 : '<span style="color:var(--pos)">준비됨</span>') + '</td></tr>';
         }).join('') : '<tr><td class="empty" colspan="6">팀이 없습니다.</td></tr>')
       + '</tbody></table></div>';

    //  ── 최근 실행 기록 — note 에 이유가 적혀 있습니다 ──
    H += '<h3 style="font-size:.9rem;color:var(--primary);margin:16px 0 8px">'
       + '최근 스캔 기록</h3>'
       + '<div class="scroll"><table><thead><tr><th style="width:130px">언제</th>'
       + '<th>팀</th><th class="num">훑음</th><th class="num">맞음</th>'
       + '<th class="num">삼</th><th>서버가 남긴 말</th></tr></thead><tbody>'
       + (recent.length ? recent.map(function(x){
           return '<tr><td class="st-hint">'
             + esc(String(x.ran_at || '').slice(0, 16).replace('T', ' ')) + '</td>'
             + '<td>' + esc(aiStr(x.team) || '-') + '</td>'
             + '<td class="num">' + num(x.scanned, 0) + '</td>'
             + '<td class="num">' + num(x.matched, 0) + '</td>'
             + '<td class="num"><b>' + num(x.filled, 0) + '</b></td>'
             + '<td class="st-hint">' + esc(aiStr(x.note) || '-') + '</td></tr>';
         }).join('')
         : '<tr><td class="empty" colspan="6">스캔이 한 번도 안 돌았습니다 · '
           + '이게 ‘아무것도 안 사는’ 이유입니다.</td></tr>')
       + '</tbody></table></div>';

    box.innerHTML = H;
  } catch(e){
    box.innerHTML = '<div class="note warn">' + esc(e.message)
      + '<br><span class="st-hint">terminal-자동진단.sql 을 아직 안 돌렸을 수 있습니다.</span></div>';
  }
}

/* ══════════ 학번 이름표 (임원진) ══════════

   ⚠️ 학번 전체는 이 화면 안에서만 씁니다 (임원진 전용). 붙인 이름은
      다른 화면으로 나가지만 학번은 안 나갑니다.
   ⚠️ 같은 이름표 두 개는 서버가 막습니다 — 매매 기록에서 누가 누군지
      모르게 되니까요.                                              */
var labelRows = [];
async function loadLabels(){
  var t = $('nkTable'); if (!t) return;
  var r = await sb.rpc('member_label_list');
  if (r.error){
    t.innerHTML = '<tr><td class="empty">' + esc(errMsg(r.error)) + '</td></tr>';
    return;
  }
  labelRows = aiArr(r.data);
  renderLabels();
}

function renderLabels(){
  var t = $('nkTable'); if (!t) return;
  var q = (($('nkFind') || {}).value || '').trim().toLowerCase();
  var rows = labelRows.filter(function(m){
    if (!q) return true;
    //  팀 이름으로도 찾을 수 있어야 ‘채권팀 누구누구’ 를 한 번에 봅니다
    return (String(m.student_id || '') + ' ' + (m.name || '') + ' '
          + (m.nickname || '') + ' '
          + (m.team || '')).toLowerCase().indexOf(q) >= 0;
  });
  if (!rows.length){
    t.innerHTML = '<tr><td class="empty">'
      + (labelRows.length ? '찾는 사람이 없습니다.' : '등록된 계정이 없습니다.')
      + '</td></tr>';
    return;
  }
  t.innerHTML = '<thead><tr><th style="width:120px">학번</th><th style="width:100px">이름</th>'
    + '<th style="width:170px">이름표 (터미널에 보일 이름)</th>'
    + '<th style="width:80px">기수</th>'
    + '<th style="width:130px">모의투자 팀</th>'
    + '<th>지금 이렇게 보입니다</th></tr></thead><tbody>'
    + rows.map(function(m){
        var i = labelRows.indexOf(m);
        return '<tr>'
          + '<td class="num">' + esc(m.student_id || '-') + '</td>'
          + '<td>' + (m.name ? esc(m.name) : '<span class="st-hint">-</span>') + '</td>'
          + '<td><input type="text" maxlength="20" value="' + esc(m.nickname || '')
          +   '" placeholder="예: 민수" style="width:150px;padding:5px 8px;font-size:12.5px"'
          +   ' onchange="setLabel(' + i + ', this.value)"></td>'
          + '<td class="num">' + (m.gen != null ? esc(String(m.gen)) + '기' : '-') + '</td>'
          /*  ⚠️ 팀이 없으면 ‘없음’ 이라고 <적습니다>. 빈 칸으로 두면
              ‘아직 안 불러온 것’ 처럼 보여서 기다리게 됩니다.           */
          + '<td>' + (m.team
                ? '<span class="by-tag">' + esc(m.team) + '</span>'
                : '<span class="st-hint">없음</span>') + '</td>'
          + '<td><span class="by-who" id="nkShow-' + i + '">' + esc(m.label || '') + '</span>'
          +   (m.role === 'officer' ? ' <span class="by-tag manual">임원진</span>' : '')
          + '</td></tr>';
      }).join('') + '</tbody>';
}

async function setLabel(i, v){
  var m = labelRows[i]; if (!m) return;
  var msg = $('nkMsg');
  var r = await sb.rpc('member_label_set', { p_id: m.id, p_nickname: v });
  if (r.error){
    msg.style.color = 'var(--neg)'; msg.textContent = errMsg(r.error);
    //  서버가 거절했으면 화면도 되돌립니다 (저장된 척하면 안 됩니다)
    renderLabels();
    return;
  }
  var d = r.data || {};
  m.nickname = d.nickname; m.label = d.label;
  var box = $('nkShow-' + i); if (box) box.textContent = d.label || '';
  msg.style.color = 'var(--pos)';
  msg.textContent = '✅ ' + (m.student_id || '') + ' → ' + (d.label || '') + ' 로 저장했습니다.';
}

/* ══════════ 학회원 관리 (임원진) ══════════ */
var memberRows = [];
async function loadMembers(){
  var r = await sb.from('profiles').select('id,student_id,name,gen,role,position,officer_pos,status').order('gen');
  //  (13차) SQL 을 아직 안 돌렸으면 officer_pos 칸이 없음 → 예전 방식으로
  if (r.error && /officer_pos/.test(r.error.message || '')) r = await sb.from('profiles').select('id,student_id,name,gen,role,position,status').order('gen');
  var t = $('memTable');
  if (r.error){ t.innerHTML = '<tr><td class="empty">'+esc(errMsg(r.error))+'</td></tr>'; return; }
  memberRows = r.data || [];
  if (!memberRows.length){ t.innerHTML = '<tr><td class="empty">등록된 계정이 없습니다.</td></tr>'; return; }
  t.innerHTML = '<thead><tr><th>학번</th><th>이름</th><th>기수</th><th>등급</th><th>직책</th><th>상태</th></tr></thead><tbody>'
    + memberRows.map(function(m,i){
        return '<tr>'
          + '<td class="num">'+esc(m.student_id||'-')+'</td>'
          + '<td><input type="text" value="'+esc(m.name||'')+'" style="width:100px;padding:5px 8px;font-size:12.5px"'
          +   ' onchange="updMember('+i+',\'name\',this.value)"></td>'
          + '<td><input type="number" value="'+(m.gen!=null?m.gen:'')+'" style="width:62px;padding:5px 8px;font-size:12.5px"'
          +   ' onchange="updMember('+i+',\'gen\',this.value)"></td>'
          + '<td><select style="padding:5px 8px;font-size:12.5px" onchange="updMember('+i+',\'role\',this.value)">'
          +   ['officer','member','alumni','guest'].map(function(x){
                var lb = x==='officer'?'임원진':x==='member'?'학회원':x==='guest'?'게스트':'수료';
                return '<option value="'+x+'"'+(m.role===x?' selected':'')+'>'+lb+'</option>'; }).join('')
          + '</select></td>'
          //  (13차) 직책 = 정해진 다섯 가지 (학회장 · 설립자만 바꿈 · 처음엔 임원진) · 예전 직책 글자는 옆에 작게
          + '<td>' + ('officer_pos' in m
              ? '<select style="padding:5px 8px;font-size:12.5px"' + (m.role !== 'officer' || !CLUB.manage ? ' disabled' : '') + ' onchange="setOfficerPos('+i+',this.value)" title="' + esc(m.role !== 'officer' ? '임원진 등급만 직책을 가질 수 있습니다' : !CLUB.manage ? '학회장 · 설립자만 바꿀 수 있습니다' : '') + '">'
                + '<option value="">없음</option>' + OFFICER_POS.map(function(p){ return '<option value="' + p[0] + '"' + (m.officer_pos === p[0] ? ' selected' : '') + '>' + esc(p[1]) + '</option>'; }).join('') + '</select>'
                + (m.position && !m.officer_pos ? ' <span class="st-hint" title="예전에 적어 둔 직책">' + esc(m.position) + '</span>' : '')
              : '<input type="text" value="'+esc(m.position||'')+'" style="width:90px;padding:5px 8px;font-size:12.5px" onchange="updMember('+i+',\'position\',this.value)">') + '</td>'
          + '<td><select style="padding:5px 8px;font-size:12.5px" onchange="updMember('+i+',\'status\',this.value)">'
          +   '<option value="active"'+(m.status==='active'?' selected':'')+'>활동</option>'
          +   '<option value="inactive"'+(m.status==='inactive'?' selected':'')+'>중지</option>'
          + '</select></td></tr>';
      }).join('') + '</tbody>';
}
async function setOfficerPos(i, v){
  var m = memberRows[i]; if (!m) return;
  var r = await sb.rpc('officer_pos_set', { p_id: m.id, p_pos: v || null });
  $('memMsg').style.color = r.error ? 'var(--danger)' : 'var(--ok)';
  $('memMsg').textContent = r.error ? errMsg(r.error) : (m.name || m.student_id) + ' → ' + (posLabel(v) || '직책 없음') + ' 저장했습니다.';
  if (r.error){ loadMembers(); return; }
  m.officer_pos = v || null;
  clubLoad();
}
async function updMember(i, k, v){
  var m = memberRows[i];
  var patch = {}; patch[k] = (k==='gen') ? (v===''?null:Number(v)) : v;
  var r = await sb.from('profiles').update(patch).eq('id', m.id);
  $('memMsg').style.color = r.error ? 'var(--danger)' : 'var(--ok)';
  $('memMsg').textContent = r.error ? errMsg(r.error)
    : (m.name || m.student_id) + ' 저장했습니다.';
  if (!r.error) m[k] = patch[k];
}

/* ══════════ 시작 ══════════ */
(async function init(){
  if (configError){ $('loginMsg').textContent = configError; return; }
  onMarketChange();
  if (typeof tbLoad === 'function') tbLoad();                //  (19차) 터미널 로고 · 탭 아이콘 (로그인 화면부터)
  if (typeof applyLang === 'function') applyLang(true);     //  머리의 ‘한/EN’ 단추 글만
  //  다른 탭에서 로그아웃했거나 서버가 세션을 끊으면 — 조용히 로그인 화면으로
  try { sb.auth.onAuthStateChange(function(ev, ss){
    if (ev === 'SIGNED_OUT' && me) authLost();
    //  (10/9) 다른 창에서 다른 계정으로 바꿔 로그인하면 — 이 창도 그 계정 것으로 (앞 계정 기록이 섞이지 않게)
    var nu = ss && ss.user && ss.user.id || '';
    if (nu && LS_UID && nu !== LS_UID) location.reload();
  }); } catch(e){}
  var s = (await sb.auth.getSession()).data.session;
  if (s){ try { await window.__p2r; } catch(e){} await afterLogin(); }   //  (35차) 두 번째 파일까지 다 읽은 뒤에
})();
